// Écrit par extraire.cjs : un échantillon de la base de la campagne, par thème et par difficulté.
window.BASE = {"qcm":{"Culture générale":{"facile":[{"id":"brg0edw0","t":"Combien de grammes compte un kilogramme ?","r":["100","1 000","10 000","500"],"b":1,"a":"À la fin du XVIIIe siècle, le gramme fut d'abord défini comme la masse d'un centimètre cube d'eau.","c":"Culture générale"},{"id":"f172guds","t":"Comment appelle-t-on un poème dont les initiales des vers, lues de haut en bas, forment un mot ?","r":["Un calembour","Un lipogramme","Un acrostiche","Un holorime"],"b":2,"a":"Le mot vient du grec akros, « extrémité », et stikhos, « vers ».","c":"Culture générale"},{"id":"uqq5djj8","t":"En France, de quelle couleur est le fond des panneaux qui indiquent une direction par l'autoroute ?","r":["Vert","Bleu","Blanc","Jaune"],"b":1,"a":"Le vert signale les grands itinéraires des routes nationales, le blanc les routes locales.","c":"Culture générale"},{"id":"3z6dc4zb","t":"Comment appelle-t-on une personne qui parle couramment deux langues ?","r":["Bilingue","Polyglotte","Biglotte","Duolingue"],"b":0,"a":"Le mot est formé du latin « bi », deux fois, et « lingua », la langue. Celui qui en parle beaucoup est polyglotte, du grec « glôssa ».","c":"Culture générale"},{"id":"2ib4l99o","t":"Combien de mois compte un semestre ?","r":["3","6","4","8"],"b":1,"a":"Le mot vient du latin semestris, formé sur sex, « six », et mensis, « mois ».","c":"Culture générale"},{"id":"offneoea","t":"Quel roi d'Ithaque est le héros de l'Odyssée ?","r":["Achille","Ulysse","Hector","Ajax"],"b":1,"a":"Son nom grec est Odysseus, qui a donné son titre au poème attribué à Homère.","c":"Culture générale"},{"id":"81u2yiz4","t":"Quel mot britannique correspond à l'américain « gas » pour le carburant des voitures ?","r":["Diesel","Paraffin","Petrol","Kerosene"],"b":2,"a":"Aux États-Unis, « gas » est l'abréviation de « gasoline », et non du gaz au sens chimique.","c":"Culture générale"},{"id":"os9ofq7l","t":"De quelle partie du chêne-liège tire-t-on le liège ?","r":["De ses racines","De ses feuilles","De ses glands","De son écorce"],"b":3,"a":"L'écorce repousse : on la récolte environ tous les neuf ans, sans abattre l'arbre.","c":"Culture générale"},{"id":"dceuar8e","t":"En France, quelle professionnelle ou quel professionnel de santé suit la grossesse et peut mettre les bébés au monde ?","r":["L'auxiliaire de puériculture","La sage-femme","L'orthophoniste","La diététicienne"],"b":1,"a":"Le métier est aussi ouvert aux hommes en France depuis 1982 : on les appelle également sages-femmes, et parfois maïeuticiens.","c":"Culture générale"},{"id":"0z8tbv6c","t":"Complétez le proverbe : « Pierre qui roule n'amasse pas… »","r":["fortune","poussière","mousse","herbe"],"b":2,"a":"Le proverbe anglais équivalent est « A rolling stone gathers no moss ».","c":"Culture générale"},{"id":"cdxb9sjj","t":"En France, quelle institution peut radier un docteur qui a manqué à sa déontologie, et lui interdire d'exercer ?","r":["La Haute Autorité de santé","L'Ordre des médecins","L'Assurance maladie","L'Agence régionale de santé"],"b":1,"a":"Tout médecin doit s'inscrire à l'Ordre pour exercer. Les ordres des pharmaciens, des dentistes et des infirmiers jouent le même rôle pour leur profession.","c":"Culture générale"},{"id":"bx82ijfb","t":"Quelle infirmière britannique, surnommée la Dame à la lampe, a fondé la formation moderne des infirmières ?","r":["Florence Nightingale","Mary Seacole","Edith Cavell","Clara Barton"],"b":0,"a":"Pendant la guerre de Crimée, elle visitait les blessés la nuit, une lampe à la main ; elle ouvrit une école d'infirmières en 1860.","c":"Culture générale"},{"id":"cxq0k11c","t":"Que signifie « sí » avec un accent, quand on répond à une question ?","r":["Si","Ainsi","Oui","Non"],"b":2,"a":"Sans accent, « si » est la conjonction « si » de la condition : l'accent écrit sépare ici deux mots de sens différents.","c":"Culture générale"},{"id":"vmc1lq8s","t":"Dans « Le gâteau est mangé par les enfants », à quelle voix est le verbe ?","r":["Active","Pronominale","Passive","Impersonnelle"],"b":2,"a":"Le complément d'agent, ici « par les enfants », est le sujet de la phrase active équivalente.","c":"Culture générale"},{"id":"238z10us","t":"Quel est le plus petit continent ?","r":["L'Europe","L'Antarctique","L'Océanie","L'Amérique du Sud"],"b":2,"a":"L'Océanie regroupe l'Australie, la Nouvelle-Zélande et des milliers d'îles du Pacifique.","c":"Culture générale"},{"id":"ybtwkxdb","t":"Combien de degrés compte un tour complet autour d'un point ?","r":["100","180","400","360"],"b":3,"a":"Ce choix viendrait des Babyloniens et de leur système de numération de base soixante.","c":"Culture générale"},{"id":"dphpvmky","t":"Quel médecin, appelé en cas de détresse vitale, intervient à bord d'une ambulance médicalisée ?","r":["Dermatologue","Radiologue","Urgentiste","Rhumatologue"],"b":2,"a":"Ce médecin exerce aussi dans les services d'accueil des urgences des hôpitaux, jour et nuit.","c":"Culture générale"},{"id":"cbu23rsk","t":"Combien de roues a une voiture ordinaire ?","r":["3","4","5","6"],"b":1,"a":"La roue est très ancienne : les plus vieilles connues datent d'environ 3500 avant notre ère.","c":"Culture générale"},{"id":"7a01q1sf","t":"Quel médecin endort le patient avant une opération et surveille ses constantes pendant l'intervention ?","r":["Radiologue","Urgentiste","Anesthésiste-réanimateur","Pneumologue"],"b":2,"a":"En 1846, à Boston, le dentiste William Morton a fait la première démonstration publique d'une anesthésie à l'éther.","c":"Culture générale"},{"id":"ha2e0pch","t":"Quel alphabet sert à écrire le russe ?","r":["Le grec","L'arménien","Le latin","Le cyrillique"],"b":3,"a":"Il doit son nom à saint Cyrille, moine byzantin du IXe siècle, même s'il a sans doute été mis au point par ses disciples.","c":"Culture générale"},{"id":"9v8bhiv4","t":"Quel héros de conte oriental frotte une lampe magique pour en libérer un génie ?","r":["Sindbad","Ali Baba","Aladin","Haroun al-Rachid"],"b":2,"a":"Le conteur syrien Hanna Diyab l'a raconté à Antoine Galland, à Paris, qui l'a ajouté à son édition des Mille et Une Nuits.","c":"Culture générale"},{"id":"0y9g2dwr","t":"Quand dit-on qu'on « voit trente-six chandelles » ?","r":["Après un coup violent sur la tête","Pendant une fête","Quand on a très peur","Au cours d'une nuit sans lune"],"b":0,"a":"Le nombre trente-six, comme « mille » ou « cent », sert ici à dire « beaucoup » plutôt qu'à compter.","c":"Culture générale"},{"id":"b10yjx3t","t":"Comment s'appelle l'organisme public espagnol qui promeut la langue et la culture espagnoles dans le monde ?","r":["L'Institut Lope de Vega","L'Institut Cervantes","L'Institut Unamuno","L'Institut Goya"],"b":1,"a":"Créé en 1991, il joue pour l'espagnol un rôle proche de celui de l'Alliance française ou de l'Institut Goethe.","c":"Culture générale"},{"id":"raf09h4r","t":"Quelle femme, enlevée par le Troyen Pâris, est à l'origine de la guerre de Troie ?","r":["Andromaque","Cassandre","Briséis","Hélène"],"b":3,"a":"Elle était l'épouse de Ménélas, roi de Sparte, dont le frère Agamemnon prit la tête de l'expédition grecque.","c":"Culture générale"}],"moyen":[{"id":"09c786pp","t":"Quel instrument grossissant, muni d'une lumière, sert à examiner de près un grain de beauté ?","r":["Un dermatoscope","Un otoscope","Un ophtalmoscope","Un laryngoscope"],"b":0,"a":"Grâce à lui, le médecin repère les signes d'un mélanome, un cancer de la peau, bien avant qu'ils soient visibles à l'œil nu.","c":"Culture générale"},{"id":"r97fo1m5","t":"Quel médecin spécialiste soigne les maladies des articulations, comme l'arthrose ?","r":["L'orthophoniste","Le néphrologue","Le rhumatologue","L'angiologue"],"b":2,"a":"Le mot vient du grec « rheuma », qui signifie écoulement : les Anciens pensaient que les douleurs venaient d'humeurs coulant dans le corps.","c":"Culture générale"},{"id":"olypvohr","t":"Quel président américain a donné son nom au principal aéroport international de New York ?","r":["Lincoln","Roosevelt","Kennedy","Washington"],"b":2,"a":"Avant d'être rebaptisé en 1963, l'aéroport s'appelait Idlewild.","c":"Culture générale"},{"id":"6hdn7gpz","t":"Dans le sigle CPAM, que signifie le P ?","r":["Primaire","Publique","Principale","Provinciale"],"b":0,"a":"Les CPAM sont les caisses locales de l'Assurance maladie, où l'on dépose ses demandes de remboursement.","c":"Culture générale"},{"id":"ava9u5ks","t":"L'adjectif « kafkaïen » vient du nom d'un écrivain né dans quelle ville ?","r":["Vienne","Budapest","Prague","Berlin"],"b":2,"a":"Franz Kafka écrivait en allemand ; « kafkaïen » qualifie une situation absurde et administrative.","c":"Culture générale"},{"id":"lykqrihv","t":"Le mot « salaire » vient du latin « sal ». Que veut dire ce mot ?","r":["L'or","Le pain","Le sel","Le travail"],"b":2,"a":"Chez les Romains, le « salarium » désigne la somme versée à certains soldats et fonctionnaires.","c":"Culture générale"},{"id":"phbxz3wu","t":"À quelle température l'eau gèle-t-elle sur l'échelle Fahrenheit ?","r":["32 °F","0 °F","12 °F","100 °F"],"b":0,"a":"Fahrenheit a fixé son zéro sur la température d'un mélange de glace, d'eau et de sel.","c":"Culture générale"},{"id":"e9vw2nnn","t":"Un nœud, unité de vitesse des navires, vaut combien de kilomètres par heure ?","r":["1,609 km/h","1,852 km/h","1,500 km/h","2,000 km/h"],"b":1,"a":"Le mot vient des nœuds d'une corde lestée, jetée à la mer autrefois pour estimer la vitesse du bateau.","c":"Culture générale"},{"id":"npqy5xxf","t":"Que signifie « tu », sans accent, en espagnol ?","r":["Toi","Tu","Ton, ta","Tout"],"b":2,"a":"Avec accent, « tú » est le pronom sujet « tu » : seul l'accent écrit distingue le possessif du pronom.","c":"Culture générale"},{"id":"3f0th10m","t":"Quel pays désigne le code « GR » sur les autocollants et plaques d'immatriculation internationaux ?","r":["Groenland","Grèce","Géorgie","Grenade"],"b":1,"a":"Les Grecs appellent eux-mêmes leur pays « Hellas » ou « Ellada », mais le code reprend le nom international.","c":"Culture générale"},{"id":"fip91c41","t":"De quel verbe « estuve » est-il le passé simple à la première personne ?","r":["estar","ser","tener","estudiar"],"b":0,"a":"Le passé simple de « estar » reprend le radical « estuv- », comme « tuve » pour « tener ».","c":"Culture générale"},{"id":"0qeb735d","t":"Dans « chronomètre » ou « chronologie », que veut dire l'élément grec « chrono » ?","r":["Vitesse","Mesure","Ordre","Temps"],"b":3,"a":"Un anachronisme est une chose placée hors de son temps, comme une montre au poignet d'un Romain dans un film.","c":"Culture générale"},{"id":"fbnl4yup","t":"Quelle est la tension nominale du courant du secteur dans les prises françaises ?","r":["110 V","127 V","230 V","24 V"],"b":2,"a":"Les États-Unis, eux, utilisent une tension d'environ 120 volts : un appareil français branché là-bas peut griller.","c":"Culture générale"},{"id":"6dpd3st2","t":"Quelle psychanalyste française animait à la radio, dans les années 1970, l'émission « Lorsque l'enfant paraît » ?","r":["Françoise Dolto","Élisabeth Roudinesco","Julia Kristeva","Anna Freud"],"b":0,"a":"En 1979, elle a fondé à Paris la Maison verte, lieu d'accueil pour les tout-petits et leurs parents.","c":"Culture générale"},{"id":"s30y1ky8","t":"Que mesure le joule, unité du Système international ?","r":["La puissance","L'énergie","La force","La pression"],"b":1,"a":"Le joule doit son nom au physicien anglais James Prescott Joule. Une calorie, l'unité des étiquettes alimentaires, vaut environ 4,18 joules.","c":"Culture générale"},{"id":"6sacpbwk","t":"Quel est le pluriel de « el lunes » ?","r":["los luneses","los lunees","las lunes","los lunes"],"b":3,"a":"Les autres jours de semaine fonctionnent de même, sauf « sábado » et « domingo », qui prennent un -s.","c":"Culture générale"},{"id":"ad2eswpo","t":"Que désigne le plus souvent « colegio » en Espagne ?","r":["Une école","Un collège","Une université","Un lycée"],"b":0,"a":"L'enseignement secondaire se fait en Espagne dans un « instituto ».","c":"Culture générale"},{"id":"38ve5g11","t":"Dans le mot « gynécologie », que signifie la racine grecque gunê ?","r":["Enfant","Femme","Naissance","Ventre"],"b":1,"a":"On retrouve la même racine dans « misogyne », celui qui n'aime pas les femmes, et dans « gynécée », partie de la maison grecque réservée aux femmes.","c":"Culture générale"},{"id":"u1vhs3hv","t":"Dans un service d'hôpital, quel professionnel encadre l'équipe soignante, après avoir souvent été infirmier ?","r":["Le cadre de santé","Le chef de clinique","L'interne","L'agent de service hospitalier"],"b":0,"a":"Il organise les plannings, la qualité des soins et la formation de l'équipe.","c":"Culture générale"},{"id":"k1571okg","t":"Dire « il nous a quittés » pour « il est mort » adoucit une réalité pénible. Quelle est cette figure ?","r":["Euphémisme","Hyperbole","Ironie","Gradation"],"b":0,"a":"On recourt volontiers à l'euphémisme pour parler de la mort, de la maladie ou de la vieillesse.","c":"Culture générale"},{"id":"9hsa1y6b","t":"Quelle partie du corps d'un nouveau-né pique-t-on à la maternité pour le dépistage néonatal ?","r":["Le pouce","L'oreille","Le talon","Le bras"],"b":2,"a":"Ce test porte le nom de l'Américain Robert Guthrie, qui l'a mis au point pour dépister la phénylcétonurie.","c":"Culture générale"},{"id":"vvh0oxs3","t":"Quelle ligne ferroviaire, qui relie Moscou à Vladivostok, passe pour la plus longue du monde ?","r":["Transmongolien","Transsibérien","Transmandchourien","Orient-Express"],"b":1,"a":"Sa construction, lancée en 1891, s'est étalée sur environ vingt-cinq ans.","c":"Culture générale"},{"id":"mrq19gl3","t":"À quel numéro de Downing Street, à Londres, se trouve la résidence officielle du Premier ministre britannique ?","r":["1","11","10","7"],"b":2,"a":"La maison voisine, au 11, est la résidence du chancelier de l'Échiquier, le ministre des Finances.","c":"Culture générale"},{"id":"ds94gdrv","t":"Combien de valeurs différentes de pièces la gamme euro comprend-elle ?","r":["6","7","8","10"],"b":2,"a":"Chaque pays de la zone euro choisit le dessin de la face nationale, qui circule dans toute la zone.","c":"Culture générale"}],"difficile":[{"id":"a8wq4nwg","t":"Quelle est la plus grande des deux îles principales de la Nouvelle-Zélande ?","r":["L'île du Nord","L'île du Sud","L'île Stewart","L'île Chatham"],"b":1,"a":"L'île du Sud est traversée par les Alpes du Sud, dont le point culminant est l'Aoraki, aussi appelé mont Cook.","c":"Culture générale"},{"id":"ogmb1p8u","t":"Au Chili et au Pérou, comment appelle-t-on l'avocat, le fruit ?","r":["aguacate","guayaba","palta","chirimoya"],"b":2,"a":"« Palta » vient du quechua, alors que « aguacate » vient du nahuatl, la langue des Aztèques.","c":"Culture générale"},{"id":"p9d9jtb2","t":"Quelle ville est desservie par l'aéroport de Fiumicino ?","r":["Milan","Naples","Venise","Rome"],"b":3,"a":"Son nom officiel rend hommage à Léonard de Vinci, qui dessina des machines volantes.","c":"Culture générale"},{"id":"2vg6d695","t":"Dans plusieurs pays d'Afrique francophone, que désigne le mot « essencerie » ?","r":["Une raffinerie","Un péage routier","Une station-service","Un parc de camions"],"b":2,"a":"Le mot est formé sur « essence » avec le suffixe -erie, comme boulangerie ou épicerie.","c":"Culture générale"},{"id":"1wlhdndi","t":"Quelle collectivité territoriale gère en France le service de protection maternelle et infantile ?","r":["La commune","La région","Le département","L'intercommunalité"],"b":2,"a":"Le service a été créé par une ordonnance de 1945, au lendemain de la guerre, pour réduire la mortalité des mères et des bébés.","c":"Culture générale"},{"id":"unvbb6kt","t":"Que désigne la racine grecque « ouron », dans « urologue » ?","r":["Le rein","La vessie","Le sang","L'urine"],"b":3,"a":"On retrouve la même racine dans « urémie ».","c":"Culture générale"},{"id":"g4nxcdii","t":"Quel géant primordial de la mythologie nordique est tué par Odin et ses frères, son corps servant à façonner le monde ?","r":["Surtr","Thrym","Ymir","Hrungnir"],"b":2,"a":"De sa chair naît la terre, de son sang les mers, de son crâne la voûte du ciel.","c":"Culture générale"},{"id":"osqqj22a","t":"Quel préfixe du Système international désigne 10 puissance 15 ?","r":["Téra","Péta","Exa","Giga"],"b":1,"a":"Le préfixe péta a été adopté en 1975, en même temps qu'exa.","c":"Culture générale"},{"id":"t45j2kgj","t":"Combien d'euros faut-il au minimum comme capital pour créer une société anonyme en France ?","r":["37 000 €","15 000 €","50 000 €","100 000 €"],"b":0,"a":"À l'inverse, une SARL peut se créer avec un seul euro de capital depuis 2003.","c":"Culture générale"},{"id":"09aa4w6j","t":"En quelle année le canal de Panama est-il ouvert à la navigation ?","r":["1904","1914","1909","1920"],"b":1,"a":"Les États-Unis ont repris le chantier abandonné par la France, dont les travaux, dirigés par Lesseps, avaient échoué.","c":"Culture générale"},{"id":"qqlf0w6o","t":"Les mots « zéro » et « chiffre » descendent du même mot. De quelle langue vient-il ?","r":["Grec","Latin","Arabe","Hébreu"],"b":2,"a":"Ce mot, « sifr », voulait dire « vide » ; le zéro lui-même est venu d'Inde en Europe par l'intermédiaire des savants arabes.","c":"Culture générale"},{"id":"nk9sws89","t":"Combien de millimètres sépare les deux rails d'une voie ferrée à écartement standard ?","r":["1 435 mm","1 520 mm","1 000 mm","1 668 mm"],"b":0,"a":"La voie russe, plus large, mesure 1 520 mm : les trains doivent changer de bogies à la frontière.","c":"Culture générale"},{"id":"r0asx2m2","t":"Dans quelle ancienne capitale ottomane, proche de la Grèce, l'hôpital du sultan Bayezid II soignait-il par la musique ?","r":["Bursa","Édirne","Konya","Ankara"],"b":1,"a":"Le complexe voisin comprenait aussi une mosquée, une école de médecine et une cuisine pour les pauvres.","c":"Culture générale"},{"id":"o3ynoknk","t":"De quelle langue vient le mot « algèbre » ?","r":["Du grec","De l'hébreu","De l'arabe","Du persan"],"b":2,"a":"Le mot vient du titre d'un traité du mathématicien Al-Khwârizmî, dont le nom a aussi donné « algorithme ».","c":"Culture générale"},{"id":"f25dzz7a","t":"En 1896, quelle ville ouvre la première ligne de métro d'Europe continentale ?","r":["Paris","Budapest","Vienne","Berlin"],"b":1,"a":"Cette ligne est construite pour fêter le millénaire de l'arrivée des Magyars dans la région.","c":"Culture générale"},{"id":"zyqxa98x","t":"De quels deux mots anglais le mot-valise « motel » est-il formé ?","r":["Motor et hostel","Mountain et hotel","Motor et hotel","Moto et hall"],"b":2,"a":"Le premier établissement de ce genre, le Milestone Mo-Tel, ouvre en 1925 à San Luis Obispo, en Californie.","c":"Culture générale"},{"id":"khryjqcn","t":"Que signifie TDM, autre nom médical du scanner ?","r":["Tomographie dynamique magnétique","Transmission de densité médicale","Tomodensitométrie","Thermodensitométrie"],"b":2,"a":"Le scanner assemble par ordinateur de nombreuses coupes réalisées avec des rayons X tournant autour du patient.","c":"Culture générale"},{"id":"x2tr7phy","t":"Le serment d'Hippocrate commence par « Je jure par… » quel dieu grec ?","r":["Zeus","Apollon","Hermès","Dionysos"],"b":1,"a":"Apollon y est invoqué avec le titre de « médecin », avant Asclépios, Hygie et Panacée.","c":"Culture générale"},{"id":"u0uoawax","t":"Quel prince troyen fuit sa ville en flammes en portant son père Anchise sur ses épaules ?","r":["Hector","Énée","Pâris","Troïlos"],"b":1,"a":"Dans l'Énéide de Virgile, ses descendants fondent la lignée d'où naîtront Romulus et Rémus.","c":"Culture générale"},{"id":"7y5t4c6f","t":"À quel temps et à quel mode est la forme « que nous aimassions » ?","r":["Imparfait de l'indicatif","Passé simple","Conditionnel présent","Imparfait du subjonctif"],"b":3,"a":"L'imparfait du subjonctif, très rare à l'oral, reste vivant dans les textes littéraires et dans quelques formules figées.","c":"Culture générale"}]},"Histoire":{"facile":[{"id":"dtiyj7gm","t":"Comment appelle-t-on en français les navires de guerre des Vikings ?","r":["Les drakkars","Les galères","Les trirèmes","Les caravelles"],"b":0,"a":"Leur faible tirant d'eau leur permettait de remonter les fleuves : en 845, des Vikings ont ainsi atteint Paris par la Seine.","c":"Histoire"},{"id":"qnqy6q9m","t":"Combien de mètres mesurait à l'origine la grande pyramide de Khéops, avant de perdre son revêtement et son sommet ?","r":["98 m","146 m","212 m","305 m"],"b":1,"a":"Elle est restée la plus haute construction humaine pendant près de quatre millénaires, jusqu'à la flèche de la cathédrale de Lincoln.","c":"Histoire"},{"id":"dq40dxqn","t":"Quel président de la République a donné son nom au centre d'art moderne de Beaubourg, à Paris ?","r":["Charles de Gaulle","Georges Pompidou","Valéry Giscard d'Estaing","François Mitterrand"],"b":1,"a":"Le bâtiment, conçu par Renzo Piano et Richard Rogers, affiche à l'extérieur ses tuyaux et ses escaliers, peints de couleurs vives.","c":"Histoire"},{"id":"jx5k91ww","t":"Quel ancien acteur de cinéma est élu président des États-Unis en 1980 ?","r":["Ronald Reagan","Gerald Ford","Jimmy Carter","Richard Nixon"],"b":0,"a":"Avant la Maison-Blanche, il avait été gouverneur de Californie et président du syndicat des acteurs de cinéma.","c":"Histoire"},{"id":"gjbsbgm6","t":"Quel alliage a donné son nom à l'âge des premières grandes civilisations, après l'âge du cuivre ?","r":["Le laiton","Le bronze","L'acier","La fonte"],"b":1,"a":"Le bronze s'obtient en ajoutant de l'étain au cuivre. Or l'étain était rare : son commerce reliait des régions très éloignées.","c":"Histoire"},{"id":"sfbl5war","t":"Quel maréchal dirige l'État français installé à Vichy à partir de 1940 ?","r":["Philippe Pétain","Maxime Weygand","Joseph Joffre","Ferdinand Foch"],"b":0,"a":"Héros de Verdun en 1916, il a 84 ans quand il prend la tête de l'État.","c":"Histoire"},{"id":"3hx3dx6x","t":"En 1773, que jettent à la mer des colons de Boston pour protester contre une taxe britannique ?","r":["Du thé","Du sucre","Du café","Du tabac"],"b":0,"a":"Les colons s'étaient déguisés en Amérindiens pour monter à bord des navires.","c":"Histoire"},{"id":"6i821kt4","t":"Quel tsar fonde Saint-Pétersbourg en 1703, sur les rives de la Neva ?","r":["Ivan le Terrible","Pierre le Grand","Nicolas II","Alexandre Ier"],"b":1,"a":"Pour bâtir la ville dans les marécages, des dizaines de milliers de travailleurs ont été mobilisés.","c":"Histoire"},{"id":"32068cve","t":"En mai 1953, Edmund Hillary et Tensing Norgay sont les premiers à atteindre le sommet de quelle montagne ?","r":["K2","Mont Everest","Kangchenjunga","Annapurna"],"b":1,"a":"Edmund Hillary était un apiculteur néo-zélandais ; Tensing Norgay, un sherpa qui avait déjà participé à plusieurs expéditions sur la montagne.","c":"Histoire"},{"id":"r5kyrb1j","t":"Quelle scientifique est la première femme à recevoir un prix Nobel, en 1903 ?","r":["Irène Joliot-Curie","Lise Meitner","Marie Curie","Rosalind Franklin"],"b":2,"a":"Elle est la seule personne à avoir reçu un Nobel de physique et un Nobel de chimie.","c":"Histoire"},{"id":"s8xjd7sz","t":"De quel pays viennent les soldats surnommés « GI » pendant la Seconde Guerre mondiale ?","r":["Royaume-Uni","Canada","Australie","États-Unis"],"b":3,"a":"Les lettres GI, apposées sur le matériel de l'armée américaine, ont fini par désigner les soldats eux-mêmes.","c":"Histoire"},{"id":"7ooyco7o","t":"Le 7 décembre 1941, quel pays attaque par surprise la base navale américaine de Pearl Harbor, à Hawaï ?","r":["Allemagne","Japon","Italie","URSS"],"b":1,"a":"Le lendemain, les États-Unis déclarent la guerre au Japon. Roosevelt parle d'une date qui restera marquée par l'infamie.","c":"Histoire"},{"id":"50bnzlo0","t":"Quel roi mérovingien bien réel est moqué dans la comptine où il met sa culotte à l'envers ?","r":["Clovis","Dagobert","Childéric","Pépin"],"b":1,"a":"La chanson date du XVIIIe siècle, bien après son règne : elle se moquait en fait du pouvoir royal de l'époque.","c":"Histoire"},{"id":"c9vokn4l","t":"Au Moyen Âge, comment appelle-t-on les guerriers à cheval, protégés d'une armure, qui servent un seigneur ?","r":["Mousquetaires","Chevaliers","Grenadiers","Légionnaires"],"b":1,"a":"Un futur chevalier commençait souvent comme page, puis comme écuyer, avant d'être adoubé.","c":"Histoire"},{"id":"yu9plvsg","t":"Comment appelait-on la galette de pain très dure, cuite deux fois, que les marins emportaient pour les longues traversées ?","r":["La fouace","Le pain d'épice","La brioche","Le biscuit de mer"],"b":3,"a":"Le mot biscuit vient justement de « bis cuit », cuit deux fois, pour qu'il se conserve longtemps à bord.","c":"Histoire"},{"id":"5qf2g3rn","t":"Quel roi succède à Élisabeth II sur le trône du Royaume-Uni, en septembre 2022 ?","r":["William","Charles III","Édouard VIII","George VII"],"b":1,"a":"Charles III a attendu plus de soixante-dix ans comme héritier, un record pour un héritier du trône britannique.","c":"Histoire"},{"id":"2wdt8txg","t":"Quel traité de 1919 impose à l'Allemagne de lourdes réparations après la Première Guerre mondiale ?","r":["Le traité de Trianon","Le traité de Versailles","Le traité de Saint-Germain","Le traité de Sèvres"],"b":1,"a":"Il est signé le 28 juin 1919 dans la galerie des Glaces, cinq ans jour pour jour après l'attentat de Sarajevo.","c":"Histoire"},{"id":"rgeoxvd5","t":"En quelle année Champollion annonce-t-il avoir déchiffré les hiéroglyphes ?","r":["1750","1822","1880","1930"],"b":1,"a":"Sa connaissance du copte, dernier état de la langue égyptienne, l'a beaucoup aidé.","c":"Histoire"},{"id":"k3ciarq1","t":"Quelle danseuse néerlandaise est fusillée à Vincennes en octobre 1917, accusée d'espionnage pour l'Allemagne ?","r":["Isadora Duncan","Mata Hari","Louise de Bettignies","Marthe Richard"],"b":1,"a":"Née Margaretha Zelle, elle avait choisi un nom de scène malais qui signifie « œil du jour », c'est-à-dire le soleil.","c":"Histoire"},{"id":"1dy4n31m","t":"Quels étaient les trois ordres de la société française avant la Révolution ?","r":["Roi, clergé et noblesse","Clergé, noblesse et bourgeoisie","Clergé, noblesse et tiers état","Noblesse, armée et paysannerie"],"b":2,"a":"En 1789, les États généraux réunissent les trois ordres, et la question du vote par ordre ou par tête provoque la crise.","c":"Histoire"},{"id":"uunuqekh","t":"Quel dirigeant de l'Allemagne nazie se faisait appeler « le Führer », c'est-à-dire le guide ?","r":["Hermann Göring","Joseph Goebbels","Adolf Hitler","Heinrich Himmler"],"b":2,"a":"Il réunit les fonctions de chancelier et de président du Reich à la mort d'Hindenburg, en 1934.","c":"Histoire"},{"id":"i23w5no9","t":"Quel physicien, père de la théorie de la relativité, meurt à Princeton en avril 1955 ?","r":["Niels Bohr","Albert Einstein","Max Planck","Enrico Fermi"],"b":1,"a":"Il avait demandé à être incinéré sans cérémonie ni monument, et ses cendres ont été dispersées en un lieu tenu secret.","c":"Histoire"},{"id":"svxcr9tc","t":"Quel nom donne-t-on couramment en français aux longs navires des Vikings ?","r":["Galion","Caravelle","Trirème","Drakkar"],"b":3,"a":"Les Vikings eux-mêmes ne disaient pas « drakkar » : le mot n'est apparu en français qu'au XIXe siècle.","c":"Histoire"},{"id":"8vv3o4tm","t":"Quel président américain signe en 1863 la proclamation d'émancipation des esclaves ?","r":["Ulysses Grant","Thomas Jefferson","Abraham Lincoln","George Washington"],"b":2,"a":"Lincoln sera réélu en 1864, et le XIIIe amendement abolira ensuite l'esclavage.","c":"Histoire"}],"moyen":[{"id":"dnb3czhb","t":"Quel président de la République soumet à référendum, en septembre 1992, le traité de Maastricht ?","r":["Jacques Chirac","Valéry Giscard d'Estaing","François Mitterrand","Georges Pompidou"],"b":2,"a":"Le « oui » l'emporte de justesse, avec un peu plus de 51 % des voix.","c":"Histoire"},{"id":"juz9j7aw","t":"Quelle civilisation a bâti les temples d'Angkor, en Asie du Sud-Est ?","r":["Les Thaïs","Les Chams","Les Vietnamiens","Les Khmers"],"b":3,"a":"Angkor Vat, construit au XIIe siècle, est le plus vaste monument religieux du monde.","c":"Histoire"},{"id":"f3wpdr3c","t":"Quelle fête américaine perpétue le souvenir d'un repas partagé en 1621 par les colons de Plymouth et des Amérindiens ?","r":["Halloween","Le Jour de l'indépendance","Thanksgiving","Le Memorial Day"],"b":2,"a":"Les colons partagèrent ce repas avec des Wampanoags, le peuple amérindien qui les avait aidés à survivre.","c":"Histoire"},{"id":"qk62r3v1","t":"Comment appelait-on le grand domaine agricole d'un riche Romain à la campagne ?","r":["La domus","La villa","L'insula","L'atrium"],"b":1,"a":"Le mot a traversé les siècles : le français « ville » vient du latin villa, qui désignait d'abord un domaine rural.","c":"Histoire"},{"id":"f9n5dnol","t":"Comment appelait-on l'ample jupon soutenu par des cerceaux, très à la mode sous le Second Empire ?","r":["La tournure","Le vertugadin","La crinoline","Le panier"],"b":2,"a":"Son nom vient du crin de cheval qui raidissait les premiers jupons, avant qu'on les remplace par des cerceaux d'acier.","c":"Histoire"},{"id":"whctleg8","t":"Quel maréchal, ancien chef des partisans, dirige la Yougoslavie de 1945 à sa mort en 1980 ?","r":["Nicolae Ceaușescu","Enver Hoxha","Josip Broz Tito","Todor Jivkov"],"b":2,"a":"Tito rompt avec Staline en 1948 et devient ensuite l'une des figures du mouvement des non-alignés.","c":"Histoire"},{"id":"rmw5wjcq","t":"Quelle victoire du 2 décembre 1805, surnommée la « bataille des Trois Empereurs », est le chef-d'œuvre de Napoléon ?","r":["Iéna","Wagram","Austerlitz","Eylau"],"b":2,"a":"Elle oppose les Français aux armées russe et autrichienne.","c":"Histoire"},{"id":"xsr4o8t9","t":"Comment appelle-t-on la sonnerie précipitée et répétée des cloches qui donnait l'alarme en cas d'incendie ou d'attaque ?","r":["Le glas","L'angélus","Le tocsin","Le bourdon"],"b":2,"a":"En juillet 1789, le tocsin retentit dans Paris pour appeler les habitants aux armes.","c":"Histoire"},{"id":"06rjrtso","t":"Quel homme d'État, président du Conseil en 1917, est surnommé « le Tigre » et « Père la Victoire » ?","r":["Raymond Poincaré","Georges Clemenceau","Aristide Briand","Jean Jaurès"],"b":1,"a":"Éditorialiste à L'Aurore, il avait donné son titre « J'accuse… ! » à la lettre de Zola, en 1898.","c":"Histoire"},{"id":"130va95j","t":"Quel roi perse a fondé l'Empire achéménide au VIe siècle av. J.-C. ?","r":["Cyrus II","Darius Ier","Xerxès Ier","Cambyse II"],"b":0,"a":"Il prend Babylone en 539 av. J.-C. et laisse partir les déportés qui y vivaient.","c":"Histoire"},{"id":"slcmbcl9","t":"Pendant l'Occupation, que fallait-il présenter, en plus de l'argent, pour acheter la plupart des aliments ?","r":["Un laissez-passer allemand","Des tickets de rationnement","Un livret militaire","Une ordonnance du maire"],"b":1,"a":"Les rations variaient selon l'âge et le travail ; beaucoup de familles ont complété les tickets par le marché noir.","c":"Histoire"},{"id":"nbctcfgx","t":"Quel général romain est le premier à débarquer en Bretagne, l'actuelle Angleterre, en 55 av. J.-C. ?","r":["Pompée","Jules César","Claude","Hadrien"],"b":1,"a":"Il y retourne l'année suivante avec cinq légions, mais ne laisse aucune garnison : la vraie conquête ne commence qu'en 43, sous l'empereur Claude.","c":"Histoire"},{"id":"wub5sn6t","t":"De mars à mai 1871, comment s'appelle le gouvernement insurrectionnel qui dirige Paris ?","r":["La Terreur","Le Directoire","La Commune","La Fronde"],"b":2,"a":"Elle s'achève par la « Semaine sanglante », fin mai 1871, quand l'armée de Versailles reprend la capitale rue par rue.","c":"Histoire"},{"id":"wn50pcgq","t":"Quel fanatique assassine le roi Henri IV, rue de la Ferronnerie, à Paris, en 1610 ?","r":["Jacques Clément","François Ravaillac","Robert-François Damiens","Jean Châtel"],"b":1,"a":"Le carrosse du roi était bloqué par des charrettes dans l'étroite rue, ce qui a facilité son geste.","c":"Histoire"},{"id":"aqc3oz37","t":"Quel dieu à tête de chacal veillait sur l'embaumement et guidait les défunts dans l'au-delà ?","r":["Horus","Anubis","Thot","Sobek"],"b":1,"a":"On le représente souvent en noir, couleur du limon fertile du Nil et de la renaissance, plutôt que du deuil.","c":"Histoire"},{"id":"n7hmgqx6","t":"Quel mot allemand désigne la « guerre éclair », stratégie d'offensives rapides de l'armée allemande en 1939-1940 ?","r":["Anschluss","Lebensraum","Blitzkrieg","Wehrmacht"],"b":2,"a":"Le mot associe Blitz, l'éclair, et Krieg, la guerre ; les Britanniques ont repris « Blitz » pour nommer les bombardements de Londres.","c":"Histoire"},{"id":"0ol1dncs","t":"Quelle bataille du 5 mai 1862 voit l'armée mexicaine repousser les troupes françaises, une victoire fêtée chaque année ?","r":["La bataille de Camerone","La bataille de Puebla","La bataille de Veracruz","La bataille de Querétaro"],"b":1,"a":"Le Cinco de Mayo est aujourd'hui célébré surtout aux États-Unis.","c":"Histoire"},{"id":"tyx8hdes","t":"En 1849, combien de centimes coûte le premier timbre-poste français, le noir à l'effigie de Cérès ?","r":["5 centimes","10 centimes","20 centimes","50 centimes"],"b":2,"a":"Avant le timbre, c'était le plus souvent le destinataire qui payait le port de la lettre, selon la distance parcourue.","c":"Histoire"},{"id":"at41ybq6","t":"Quel grand marché parisien Émile Zola a-t-il surnommé « le Ventre de Paris » ?","r":["Le marché d'Aligre","Le marché Saint-Germain","Les Halles","Le marché aux puces"],"b":2,"a":"En 1969, le marché de gros des Halles a quitté le centre de Paris pour s'installer à Rungis.","c":"Histoire"},{"id":"8wxfnizf","t":"Quel sigle désignait la radio dans les foyers français de l'entre-deux-guerres ?","r":["TSF","RTF","ORTF","CSF"],"b":0,"a":"Il signifie « télégraphie sans fil », et l'on disait « allumer le poste de TSF ».","c":"Histoire"},{"id":"9z84pgta","t":"Quel dernier tsar de Russie est exécuté avec sa famille par les bolcheviks, en juillet 1918 ?","r":["Nicolas II","Alexandre III","Alexandre II","Nicolas Ier"],"b":0,"a":"La famille impériale est tuée à Iekaterinbourg, dans l'Oural ; ses membres ont été canonisés par l'Église orthodoxe russe en 2000.","c":"Histoire"},{"id":"r8v27fi1","t":"Quels accords signés en mars 1962 ouvrent la voie à l'indépendance de l'Algérie ?","r":["Les accords de Matignon","Les accords d'Évian","Les accords de Grenelle","Les accords de Genève"],"b":1,"a":"L'indépendance est proclamée le 5 juillet 1962, après un référendum d'autodétermination.","c":"Histoire"},{"id":"g2f77fxo","t":"Quel pétrolier s'échoue en mars 1967 sur des récifs au large de la Cornouailles britannique ?","r":["Amoco Cadiz","Erika","Exxon Valdez","Torrey Canyon"],"b":3,"a":"Pour limiter la nappe, l'aviation britannique a bombardé l'épave afin d'y mettre le feu, une méthode qui s'est révélée peu efficace.","c":"Histoire"},{"id":"di5yoht5","t":"Quel général commande la 2e division blindée qui entre dans Paris libéré, en août 1944 ?","r":["De Lattre de Tassigny","Leclerc","Juin","Koenig"],"b":1,"a":"Leclerc est le nom de guerre de Philippe de Hauteclocque, pris pour protéger sa famille restée en France.","c":"Histoire"}],"difficile":[{"id":"6a9p4dld","t":"Quel roi de France est sacré à Reims le 17 juillet 1429, en présence de Jeanne d'Arc ?","r":["Charles VI","Louis XI","Charles VII","Charles V"],"b":2,"a":"Avant ce sacre, ses adversaires le surnommaient par moquerie « le roi de Bourges ».","c":"Histoire"},{"id":"w40srrxf","t":"Sous l'Ancien Régime, comment appelait-on les financiers qui percevaient certains impôts pour le compte du roi ?","r":["Les intendants","Les fermiers généraux","Les baillis","Les prévôts"],"b":1,"a":"Le chimiste Lavoisier était fermier général : cela lui valut d'être guillotiné en 1794.","c":"Histoire"},{"id":"1czsfgun","t":"En juillet 1940, dans quel port d'Algérie la Royal Navy attaque-t-elle la flotte française ?","r":["Alger","Mers el-Kébir","Bône","Philippeville"],"b":1,"a":"Les Britanniques craignaient que la flotte française ne tombe aux mains de l'Allemagne : l'attaque coûta la vie à près de 1 300 marins français.","c":"Histoire"},{"id":"pnlbjcli","t":"Quel roi de Prusse, ami de Voltaire, fait construire le palais de Sans-Souci à Potsdam ?","r":["Frédéric-Guillaume Ier","Guillaume Ier","Frédéric II","Frédéric-Guillaume II"],"b":2,"a":"Il joue de la flûte et compose des sonates pour son instrument.","c":"Histoire"},{"id":"8wnh123q","t":"En 1796, quel explorateur écossais atteint le fleuve Niger et observe qu'il coule vers l'est ?","r":["John Hanning Speke","Richard Burton","Mungo Park","René Caillié"],"b":2,"a":"Il est mort en 1806 lors d'une seconde expédition sur le Niger, attaqué au niveau des rapides de Bussa.","c":"Histoire"},{"id":"zn29irci","t":"En quelle année les Britanniques Alcock et Brown réussissent-ils la première traversée de l'Atlantique en avion sans escale ?","r":["1927","1909","1919","1935"],"b":2,"a":"Leur vol, de Terre-Neuve à l'Irlande, se termina dans une tourbière, où leur biplan atterrit sur le nez.","c":"Histoire"},{"id":"vqiabwx7","t":"En quelle année les Athéniens battent-ils les Perses à Marathon ?","r":["480 av. J.-C.","499 av. J.-C.","490 av. J.-C.","431 av. J.-C."],"b":2,"a":"La course du marathon moderne, créée en 1896, s'inspire de la légende du messager de cette bataille.","c":"Histoire"},{"id":"zr30d07g","t":"Quel conquistador espagnol descend l'Amazone sur toute sa longueur, de 1541 à 1542 ?","r":["Francisco Pizarro","Vasco Núñez de Balboa","Juan Ponce de León","Francisco de Orellana"],"b":3,"a":"Son équipage crut combattre des femmes guerrières, d'où le nom d'Amazone donné au fleuve, en souvenir des Amazones de la mythologie grecque.","c":"Histoire"},{"id":"qlkzt8e0","t":"Comment appelait-on les soldats d'élite chargés de garder l'empereur romain ?","r":["Les licteurs","Les centurions","Les prétoriens","Les vélites"],"b":2,"a":"Créée par Auguste, cette garde fit et défit plusieurs empereurs, avant d'être dissoute par Constantin en 312.","c":"Histoire"},{"id":"untnp94s","t":"Quel empire a aménagé la Voie royale, longue route reliant Sardes à Suse ?","r":["L'Empire assyrien","L'Empire babylonien","L'Empire hittite","L'Empire perse"],"b":3,"a":"Des relais de cavaliers y faisaient passer le courrier du roi en quelques jours.","c":"Histoire"},{"id":"krcfnl6r","t":"Quelle opération du travail de la laine accomplissait le cardeur ?","r":["Teindre le drap","Tisser le drap","Démêler les fibres","Fouler le drap"],"b":2,"a":"Le mot « carde » vient du latin « carduus », le chardon, plante épineuse.","c":"Histoire"},{"id":"kkvl52dz","t":"Quel empereur d'Éthiopie est couronné à Addis-Abeba en novembre 1930 ?","r":["Ménélik II","Haïlé Sélassié","Tewodros II","Yohannes IV"],"b":1,"a":"En 1936, chassé par l'invasion italienne, il vient plaider la cause de son pays devant la Société des Nations, à Genève.","c":"Histoire"},{"id":"849eu67h","t":"Quel est le prénom de l'impératrice d'Autriche surnommée Sissi, assassinée à Genève en 1898 ?","r":["Marie-Louise","Élisabeth","Marie-Thérèse","Zita"],"b":1,"a":"Elle fut poignardée sur les quais du lac Léman par l'anarchiste italien Luigi Lucheni.","c":"Histoire"},{"id":"riwd5fl7","t":"Sous quel empereur romain commence, vers 70, la construction du Colisée ?","r":["Néron","Vespasien","Trajan","Hadrien"],"b":1,"a":"Son nom antique est l'amphithéâtre Flavien, d'après la dynastie de cet empereur ; son fils Titus l'inaugure.","c":"Histoire"},{"id":"pru9qy50","t":"Quel roi de Germanie est couronné empereur à Rome en 962, fondant le Saint-Empire romain germanique ?","r":["Henri l'Oiseleur","Frédéric Barberousse","Conrad II","Otton Ier"],"b":3,"a":"Otton Ier avait arrêté les incursions des Hongrois en les battant au Lechfeld, en 955.","c":"Histoire"},{"id":"8mk3gjc6","t":"Quel prince portugais proclame l'indépendance du Brésil, en septembre 1822 ?","r":["Jean VI","Pierre Ier","Manuel Ier","Miguel Ier"],"b":1,"a":"Fils du roi du Portugal, il devint le premier empereur du Brésil, puis fut brièvement roi du Portugal sous le nom de Pierre IV.","c":"Histoire"},{"id":"gcs7av7b","t":"Le 6 juin 1944, sur quelle plage les Américains subissent-ils les plus lourdes pertes ?","r":["Utah Beach","Gold Beach","Juno Beach","Omaha Beach"],"b":3,"a":"Les Britanniques débarquent à Gold et Sword, les Canadiens à Juno, les Américains à Utah et Omaha.","c":"Histoire"},{"id":"mk1hc0ko","t":"En décembre 1959, la rupture d'un barrage dévaste une ville du Var et fait plus de quatre cents morts. Quelle ville ?","r":["Draguignan","Saint-Raphaël","Hyères","Fréjus"],"b":3,"a":"Le barrage de Malpasset, une voûte mince de béton, a cédé après des pluies diluviennes ; les eaux ont déferlé sur la vallée en quelques minutes.","c":"Histoire"},{"id":"7bimcxkt","t":"Quel président des États-Unis donne son nom à la doctrine de 1823 qui rejette toute ingérence européenne en Amérique ?","r":["James Monroe","Thomas Jefferson","John Adams","Andrew Jackson"],"b":0,"a":"La doctrine Monroe est résumée par la formule « l'Amérique aux Américains ».","c":"Histoire"},{"id":"olyf0svs","t":"Quelle bataille de l'été 1943, sur le front de l'Est, est restée célèbre pour ses immenses affrontements de chars ?","r":["Smolensk","Koursk","Kharkov","Stalingrad"],"b":1,"a":"L'opération allemande portait le nom de code Citadelle.","c":"Histoire"}]},"Géographie":{"facile":[{"id":"gdbdjpwm","t":"Quelle ville est la préfecture du Rhône ?","r":["Lyon","Villeurbanne","Saint-Étienne","Villefranche-sur-Saône"],"b":0,"a":"Lyon, fondée par les Romains sous le nom de Lugdunum, fut la capitale des Gaules.","c":"Géographie"},{"id":"hk1tel3c","t":"Quel oiseau de basse-cour, souvent en céramique peinte de couleurs vives, est le symbole touristique du Portugal ?","r":["Le coq","Le canard","Le paon","L'oie"],"b":0,"a":"Ce coq de Barcelos rappelle une légende : un coq rôti aurait chanté pour prouver l'innocence d'un pèlerin condamné.","c":"Géographie"},{"id":"p4zmzm5u","t":"Quel fleuve traverse La Nouvelle-Orléans avant de se jeter dans le golfe du Mexique ?","r":["Missouri","Mississippi","Colorado","Rio Grande"],"b":1,"a":"Son nom vient d'un mot algonquin signifiant « grand fleuve ».","c":"Géographie"},{"id":"zoo8z5bp","t":"Quel lac borde à la fois Genève et Lausanne ?","r":["Le lac de Neuchâtel","Le Léman","Le lac de Constance","Le lac des Quatre-Cantons"],"b":1,"a":"Le jet d'eau de Genève, posé sur le lac, est devenu l'emblème de la ville.","c":"Géographie"},{"id":"5vk53yxg","t":"Dans quel pays se trouve Bombay, aujourd'hui appelée Mumbai ?","r":["Pakistan","Bangladesh","Inde","Sri Lanka"],"b":2,"a":"Mumbai est le cœur de Bollywood, l'industrie du cinéma en hindi, dont le nom mêle Bombay et Hollywood.","c":"Géographie"},{"id":"4qg62iup","t":"En quelle année l'Allemagne de l'Est et l'Allemagne de l'Ouest se sont-elles réunies en un seul pays ?","r":["1989","1990","1991","1992"],"b":1,"a":"La réunification a eu lieu le 3 octobre, devenu le jour de la fête nationale allemande.","c":"Géographie"},{"id":"upzyb0w8","t":"Quelle chaîne de montagnes traverse le Maroc, l'Algérie et la Tunisie ?","r":["Hoggar","Drakensberg","Tibesti","Atlas"],"b":3,"a":"Son nom vient d'Atlas, le Titan de la mythologie grecque qui portait le ciel sur ses épaules.","c":"Géographie"},{"id":"63hmip0y","t":"Dans quelle ville se dresse la tour Eiffel ?","r":["Lyon","Bordeaux","Paris","Nice"],"b":2,"a":"Prévue pour durer vingt ans, elle fut conservée car elle servait d'antenne de radio.","c":"Géographie"},{"id":"rhrptxob","t":"Dans quel État américain se trouvent les volcans Mauna Loa et Kilauea ?","r":["Alaska","Hawaï","Californie","Washington"],"b":1,"a":"Hawaï est le seul État américain entièrement composé d'îles.","c":"Géographie"},{"id":"ni93cdgt","t":"En quelle année l'Inde est-elle devenue indépendante du Royaume-Uni ?","r":["1945","1950","1947","1952"],"b":2,"a":"L'indépendance s'est accompagnée de la partition qui a donné naissance au Pakistan.","c":"Géographie"},{"id":"7ubsqfc0","t":"Quelle grande ville s'étend sur deux continents, de part et d'autre du Bosphore ?","r":["Istanbul","Ankara","Athènes","Izmir"],"b":0,"a":"Elle s'est appelée Byzance, puis Constantinople, avant de prendre officiellement le nom d'Istanbul en 1930.","c":"Géographie"},{"id":"ow9nnprw","t":"De quelle couleur est le fond du drapeau de l'Union européenne ?","r":["Rouge","Vert","Jaune","Bleu"],"b":3,"a":"Ce drapeau a d'abord été celui du Conseil de l'Europe, une organisation distincte de l'Union européenne.","c":"Géographie"},{"id":"tzl5uqgr","t":"Dans quelle ville se dresse la Sagrada Família, église inachevée de Gaudí ?","r":["Madrid","Valence","Séville","Barcelone"],"b":3,"a":"Le chantier a débuté en 1882 ; Gaudí y a consacré la fin de sa vie.","c":"Géographie"},{"id":"5p0yue49","t":"De quelle couleur est la croix du drapeau suisse ?","r":["Rouge","Bleue","Blanche","Jaune"],"b":2,"a":"Le drapeau suisse est, avec celui du Vatican, l'un des deux drapeaux nationaux de forme carrée.","c":"Géographie"},{"id":"8mguh1l6","t":"Quel monument parisien, voulu par Napoléon, se dresse au centre de la place de l'Étoile ?","r":["Le Panthéon","L'Arc de triomphe","La Madeleine","L'Obélisque"],"b":1,"a":"Sous sa voûte repose le Soldat inconnu, et la flamme du Souvenir y est ravivée chaque soir.","c":"Géographie"},{"id":"27r21179","t":"Quel pays d'Amérique du Nord est situé entre les États-Unis et le Guatemala ?","r":["Cuba","Mexique","Honduras","Belize"],"b":1,"a":"Le Río Bravo, appelé Rio Grande aux États-Unis, marque une grande partie de la frontière entre les deux pays.","c":"Géographie"},{"id":"u0t3rx0l","t":"Dans quelle ville italienne les gondoles glissent-elles sur le Grand Canal ?","r":["Gênes","Venise","Ravenne","Trieste"],"b":1,"a":"Venise est bâtie sur plus de cent îlots d'une lagune de l'Adriatique.","c":"Géographie"},{"id":"ilasomoy","t":"Quelle ville est la capitale du Liban ?","r":["Damas","Beyrouth","Tripoli","Byblos"],"b":1,"a":"Byblos, au nord de la capitale, compte parmi les plus anciennes villes habitées sans interruption au monde.","c":"Géographie"},{"id":"3ydvg4jl","t":"Quelle ville est la capitale de l'Afghanistan ?","r":["Kandahar","Hérat","Mazar-e Charif","Kaboul"],"b":3,"a":"Kaboul se situe à près de 1 800 mètres d'altitude, entourée de montagnes.","c":"Géographie"},{"id":"g12goxtv","t":"Quelle est la capitale de la France ?","r":["Lyon","Paris","Marseille","Versailles"],"b":1,"a":"Paris s'est développée à partir de l'île de la Cité, sur la Seine, où vivait le peuple gaulois des Parisii.","c":"Géographie"},{"id":"aroihwlz","t":"Quelle ville est la préfecture des Bouches-du-Rhône ?","r":["Aix-en-Provence","Arles","Marseille","Toulon"],"b":2,"a":"Fondée par des marins grecs venus de Phocée, Marseille est souvent présentée comme la plus ancienne ville de France.","c":"Géographie"},{"id":"u4d94zv3","t":"Comment dit-on d'un drapeau abaissé à mi-mât en signe de deuil ?","r":["En panne","En lice","En berne","En friche"],"b":2,"a":"En France, c'est le Premier ministre qui décide de mettre les drapeaux en berne lors d'un deuil national.","c":"Géographie"},{"id":"ulrljora","t":"Quelle montagne est surnommée le « Toit de l'Afrique » ?","r":["Mont Kenya","Kilimandjaro","Mont Stanley","Toubkal"],"b":1,"a":"C'est un volcan endormi qui s'élève seul au-dessus de la plaine tanzanienne.","c":"Géographie"},{"id":"qycwt9gs","t":"Dans quel océan se trouve la Polynésie française ?","r":["L'océan Indien","L'océan Atlantique","L'océan Austral","L'océan Pacifique"],"b":3,"a":"Tahiti, sa plus grande île, a inspiré à Paul Gauguin une grande partie de ses toiles.","c":"Géographie"}],"moyen":[{"id":"vjv6xq2y","t":"Dans quel pays se dresse l'Annapurna, premier sommet de plus de 8 000 mètres gravi par l'homme ?","r":["Népal","Inde","Bhoutan","Pakistan"],"b":0,"a":"En 1950, les Français Maurice Herzog et Louis Lachenal atteignirent son sommet, mais au prix de graves gelures.","c":"Géographie"},{"id":"qs7ch9kc","t":"Dans quelle région d'Amérique du Nord des peuples comme les Comanches chassaient-ils le bison à cheval ?","r":["Les Grands Lacs","Les Grandes Plaines","Les Appalaches","La côte Pacifique"],"b":1,"a":"Le cheval, ramené par les Espagnols, a transformé le mode de vie de ces peuples.","c":"Géographie"},{"id":"g6w54x4r","t":"Quel pays d'Amérique du Sud a pour capitale Quito ?","r":["Pérou","Colombie","Équateur","Bolivie"],"b":2,"a":"Le pays tient son nom de la ligne équatoriale qui passe près de Quito.","c":"Géographie"},{"id":"nd6zfflt","t":"Quelle hauteur, en mètres, la Space Needle de Seattle atteint-elle ?","r":["184 m","124 m","244 m","304 m"],"b":0,"a":"Son plateau tournant offre un tour complet du panorama en moins d'une heure.","c":"Géographie"},{"id":"pqturuod","t":"Dans quelle ville se dresse la cathédrale où furent sacrés presque tous les rois de France ?","r":["Chartres","Amiens","Reims","Rouen"],"b":2,"a":"Clovis aurait été baptisé à Reims vers 500, ce qui explique le choix de la ville pour les sacres royaux.","c":"Géographie"},{"id":"ydg7eruf","t":"Près de son embouchure, quel fleuve d'Afrique de l'Ouest baigne la ville de Saint-Louis ?","r":["Le Niger","La Gambie","Le Sénégal","La Volta"],"b":2,"a":"Saint-Louis a été la capitale de la colonie du Sénégal, puis de l'Afrique-Occidentale française, avant Dakar.","c":"Géographie"},{"id":"m6gqhttc","t":"Quel pays d'Asie portait officiellement le nom de Perse pour l'étranger avant 1935 ?","r":["Irak","Iran","Afghanistan","Turquie"],"b":1,"a":"Le tapis persan garde le souvenir de l'ancien nom.","c":"Géographie"},{"id":"aik0cwr0","t":"Dans quelle ville française la basilique Notre-Dame de Fourvière domine-t-elle la colline ?","r":["Marseille","Toulouse","Bordeaux","Lyon"],"b":3,"a":"La colline de Fourvière est surnommée « la colline qui prie », face à la Croix-Rousse « qui travaille ».","c":"Géographie"},{"id":"tacbiv4x","t":"Comment appelle-t-on les habitants de Chypre ?","r":["Les Chypréens","Les Chypriotes","Les Chyprais","Les Chypriens"],"b":1,"a":"L'île est divisée depuis 1974 par une ligne de démarcation, la « ligne verte », qui traverse même sa capitale Nicosie.","c":"Géographie"},{"id":"q1f4gpzg","t":"Dans quel pays se dressent les falaises de Bandiagara, au pays dogon ?","r":["Niger","Burkina Faso","Sénégal","Mali"],"b":3,"a":"Les falaises de Bandiagara sont inscrites au patrimoine mondial de l'Unesco pour leurs paysages et leurs villages dogons.","c":"Géographie"},{"id":"qpep5pow","t":"Quelle ville est le chef-lieu de la Sicile ?","r":["Catane","Palerme","Messine","Syracuse"],"b":1,"a":"Catane, sur la même île, s'étend au pied de l'Etna, le plus haut volcan actif d'Europe.","c":"Géographie"},{"id":"enlt5lbk","t":"Quelle ville est la capitale de la Corée du Nord ?","r":["Séoul","Kaesong","Pyongyang","Busan"],"b":2,"a":"La ville est traversée par le fleuve Taedong.","c":"Géographie"},{"id":"ncka1gjw","t":"Dans quelle mer le Danube se jette-t-il ?","r":["Mer Noire","Mer Adriatique","Mer Baltique","Mer Égée"],"b":0,"a":"Le Danube traverse ou longe dix pays, plus que n'importe quel autre fleuve au monde.","c":"Géographie"},{"id":"mot0miz7","t":"Comment appelle-t-on la vaste dépression qui se forme quand le sommet d'un volcan s'effondre ?","r":["Une fumerolle","Une moraine","Une cheminée","Une caldeira"],"b":3,"a":"Le mot vient de l'espagnol et du portugais et signifie « chaudron » ; beaucoup de caldeiras abritent aujourd'hui un lac.","c":"Géographie"},{"id":"fonvvbvi","t":"Quel pays du Caucase a un drapeau blanc orné de cinq croix rouges ?","r":["Arménie","Géorgie","Azerbaïdjan","Moldavie"],"b":1,"a":"Ce drapeau, inspiré d'une bannière médiévale, est devenu officiel en 2004.","c":"Géographie"},{"id":"4aen47m6","t":"Quelle est l'altitude de la montagne Pelée, volcan du nord de la Martinique, en mètres ?","r":["1 197 m","1 397 m","1 597 m","1 797 m"],"b":1,"a":"Le volcan est coiffé d'un dôme de lave, dont la croissance a marqué ses éruptions successives.","c":"Géographie"},{"id":"50l41p5a","t":"Dans quel pays se trouve le lac Vänern, le plus grand lac d'Europe de l'Ouest ?","r":["Norvège","Suède","Finlande","Danemark"],"b":1,"a":"Le Vänern est relié à Göteborg et à la mer par le fleuve Göta älv, et son voisin le Vättern est le deuxième lac du pays.","c":"Géographie"},{"id":"juvl492w","t":"Quelle ville est la préfecture du Tarn ?","r":["Castres","Gaillac","Mazamet","Albi"],"b":3,"a":"Sa cathédrale Sainte-Cécile, en brique rouge, est inscrite à l'Unesco avec la cité épiscopale depuis 2010.","c":"Géographie"},{"id":"ratdhtk5","t":"Quel canal creusé au XVIIe siècle relie la Garonne à la Méditerranée ?","r":["Canal de Bourgogne","Canal du Midi","Canal de Briare","Canal du Nivernais"],"b":1,"a":"Son concepteur, Pierre-Paul Riquet, est mort quelques mois avant son inauguration.","c":"Géographie"},{"id":"r1bdg4qx","t":"Combien de cantons la Confédération suisse compte-t-elle ?","r":["16","20","26","30"],"b":2,"a":"Six d'entre eux sont des demi-cantons, comme Bâle-Ville et Bâle-Campagne.","c":"Géographie"},{"id":"49bxl5i6","t":"Quel pays d'Asie, sans accès à la mer, a pour capitale Oulan-Bator ?","r":["Kazakhstan","Mongolie","Ouzbékistan","Kirghizistan"],"b":1,"a":"La Mongolie est l'un des pays les moins densément peuplés du monde.","c":"Géographie"},{"id":"11s80xgd","t":"Le col du Galibier, dans les Alpes, culmine à quelle altitude en mètres ?","r":["2 115 m","3 120 m","2 642 m","1 980 m"],"b":2,"a":"Un monument y honore Henri Desgrange, le fondateur du Tour de France, au pied de la route qui franchit le col.","c":"Géographie"},{"id":"rdn75opb","t":"Quelle ville est la capitale du Gabon ?","r":["Port-Gentil","Franceville","Brazzaville","Libreville"],"b":3,"a":"Libreville doit son nom aux esclaves libérés qui s'y installèrent lors de sa fondation, en 1849.","c":"Géographie"},{"id":"np1wxl4t","t":"À la frontière de quels pays se dresse le Cervin ?","r":["France et Suisse","Suisse et Autriche","Suisse et Italie","France et Italie"],"b":2,"a":"Sa première ascension, en 1865, s'acheva par la chute mortelle de quatre alpinistes.","c":"Géographie"}],"difficile":[{"id":"sycoxu21","t":"Quel pays a un drapeau bleu avec l'Union Jack, une grande étoile à sept branches et cinq autres étoiles ?","r":["Nouvelle-Zélande","Fidji","Australie","Tuvalu"],"b":2,"a":"La grande étoile, sous l'Union Jack, représente les États et les territoires réunis dans la fédération.","c":"Géographie"},{"id":"t72b10rc","t":"Quel peuple amérindien du sud-ouest des États-Unis est célèbre pour ses tapis tissés ?","r":["Sioux","Cherokee","Navajo","Iroquois"],"b":2,"a":"Les Navajo se nomment eux-mêmes Diné, « le peuple ».","c":"Géographie"},{"id":"jpp77q3v","t":"Dans quel département se trouve la ville de Verdun ?","r":["Moselle","Marne","Meuse","Ardennes"],"b":2,"a":"Verdun est aussi réputée pour ses dragées, une spécialité confisière ancienne.","c":"Géographie"},{"id":"totpbk4p","t":"Quelle ville est la capitale du Nicaragua ?","r":["Tegucigalpa","Managua","San Salvador","San José"],"b":1,"a":"Le Nicaragua abrite le plus grand lac d'Amérique centrale, le lac Cocibolca, où vivent des requins.","c":"Géographie"},{"id":"sh53tasv","t":"Quelle ville italienne est surnommée la « Sérénissime » ?","r":["Florence","Gênes","Sienne","Venise"],"b":3,"a":"Ses doges l'ont gouvernée pendant plus de mille ans, jusqu'à la chute de la République, en 1797.","c":"Géographie"},{"id":"ud83rajo","t":"Quelle commune est la préfecture du Val-d'Oise ?","r":["Pontoise","Argenteuil","Sarcelles","Cergy"],"b":3,"a":"Cergy est une ville nouvelle, née dans les années 1960 pour désengorger l'agglomération parisienne.","c":"Géographie"},{"id":"eusq8m9p","t":"Quelle croix en X rouge représente l'Irlande sur l'Union Jack ?","r":["La croix de saint André","La croix de saint Patrick","La croix de saint Georges","La croix de saint David"],"b":1,"a":"La croix de saint Patrick n'a été ajoutée à l'Union Jack qu'en 1801, lors de l'union avec l'Irlande.","c":"Géographie"},{"id":"qtq9gwpq","t":"Comment s'appelle le peuple polynésien autochtone de l'île de Pâques ?","r":["Maoris","Tahitiens","Rapanui","Hawaïens"],"b":2,"a":"Les Rapanui ont sculpté les moaï, ces grandes statues de pierre tournées vers l'intérieur de l'île.","c":"Géographie"},{"id":"8qvcdcd0","t":"En quelle année a commencé la construction de la tour penchée de Pise ?","r":["1295","1066","1350","1173"],"b":3,"a":"La tour a commencé à pencher pendant le chantier, qui s'est étalé sur près de deux siècles.","c":"Géographie"},{"id":"azp0c35d","t":"Combien de bandes horizontales compte le drapeau de la Grèce ?","r":["7","11","9","13"],"b":2,"a":"Selon la tradition, elles évoquent les neuf syllabes de « Éleftheria i thanatos » : la liberté ou la mort.","c":"Géographie"},{"id":"tvrcz507","t":"Quels lacs les chutes du Niagara relient-elles par la rivière Niagara ?","r":["Huron et Érié","Supérieur et Huron","Érié et Ontario","Michigan et Huron"],"b":2,"a":"Elles marquent la frontière entre le Canada et les États-Unis.","c":"Géographie"},{"id":"f6s2wlw8","t":"Quelle ville est la préfecture de la Seine-et-Marne ?","r":["Meaux","Melun","Fontainebleau","Provins"],"b":1,"a":"Melun a donné son nom à un fromage, le brie de Melun, cousin du brie de Meaux.","c":"Géographie"},{"id":"95bfq8k3","t":"Dans quelle ville se dresse le palais du Potala, ancienne résidence des dalaï-lamas ?","r":["Lhassa","Katmandou","Thimphou","Oulan-Bator"],"b":0,"a":"Perché à environ 3 700 mètres d'altitude, le palais compte parmi les édifices les plus hauts du monde par son emplacement.","c":"Géographie"},{"id":"f2qoqsft","t":"Quel pays enclavé d'Afrique de l'Ouest doit son nom au fleuve qui le traverse ?","r":["Mali","Niger","Tchad","Burkina Faso"],"b":1,"a":"Son voisin du sud, le Nigeria, tire lui aussi son nom du même fleuve.","c":"Géographie"},{"id":"joqb5chk","t":"Quelle ville est la capitale du Nigeria ?","r":["Abuja","Lagos","Kano","Ibadan"],"b":0,"a":"Bâtie au centre du pays, elle a remplacé Lagos comme capitale en 1991.","c":"Géographie"},{"id":"huzqvj3h","t":"Quelle ville est la préfecture de l'Ille-et-Vilaine ?","r":["Saint-Malo","Vannes","Rennes","Fougères"],"b":2,"a":"Le département tient son nom de deux rivières, l'Ille et la Vilaine, qui se rejoignent à Rennes.","c":"Géographie"},{"id":"5v1xwevs","t":"Quel pays ses habitants appellent-ils « Suomi » dans leur propre langue ?","r":["L'Estonie","La Suède","La Finlande","L'Islande"],"b":2,"a":"Le finnois n'est pas une langue germanique comme le suédois : il appartient à la famille ouralienne, comme l'estonien.","c":"Géographie"},{"id":"fcrqtx26","t":"Quels pays se partagent les chutes d'Iguaçu ?","r":["Le Brésil et l'Argentine","Le Brésil et le Paraguay","L'Argentine et l'Uruguay","Le Brésil et l'Uruguay"],"b":0,"a":"Elles comptent plusieurs centaines de cascades, dont la plus impressionnante est surnommée la Gorge du Diable.","c":"Géographie"},{"id":"6aok3c0i","t":"Dans quel pays Chuseok, grande fête des récoltes, réunit-elle les familles autour des gâteaux de riz songpyeon ?","r":["Japon","Corée du Sud","Chine","Viêt Nam"],"b":1,"a":"Chuseok tombe le quinzième jour du huitième mois lunaire, à la pleine lune : on y honore aussi les ancêtres.","c":"Géographie"},{"id":"bgcijevr","t":"Quel nom porte le célèbre pont d'Avignon, interrompu au milieu du Rhône ?","r":["Pont du Gard","Pont Valentré","Pont Saint-Bénezet","Pont Saint-Esprit"],"b":2,"a":"Il ne reste que quatre arches du pont, chanté par la comptine « Sur le pont d'Avignon ».","c":"Géographie"}]},"Sciences":{"facile":[{"id":"lpc3un4u","t":"Sur quel astre les astronautes des missions Apollo ont-ils marché ?","r":["Mars","La Lune","Vénus","Mercure"],"b":1,"a":"Douze hommes ont marché sur la Lune, entre 1969 et 1972.","c":"Sciences"},{"id":"qev4opod","t":"Que désigne le « cloud » en informatique ?","r":["Un virus très répandu","Un type d'écran à nuances","Des serveurs distants","Une batterie de secours"],"b":2,"a":"Le nuage était dessiné sur les schémas de réseaux pour représenter Internet, une partie dont on ignorait le détail.","c":"Sciences"},{"id":"aoqurt26","t":"Comment appelle-t-on la petite cicatrice au milieu du ventre, laissée par le cordon ombilical ?","r":["Le mamelon","Le nombril","La fossette","Le pore"],"b":1,"a":"Son nom savant est l'ombilic. Le reste du cordon sèche puis tombe tout seul dans les premiers jours de la vie du bébé.","c":"Sciences"},{"id":"ycl25hl1","t":"Combien de mois dure en moyenne une grossesse humaine ?","r":["7 mois","8 mois","9 mois","10 mois"],"b":2,"a":"En médecine, on compte plutôt en semaines : environ quarante à partir des dernières règles.","c":"Sciences"},{"id":"i45u8bwv","t":"Sur quelle planète la NASA a-t-elle posé les robots Curiosity et Perseverance ?","r":["Vénus","Mars","Mercure","Jupiter"],"b":1,"a":"Perseverance a emporté un petit hélicoptère, Ingenuity, premier engin motorisé à avoir volé sur une autre planète.","c":"Sciences"},{"id":"oa40kov5","t":"En quelle année « La Géométrie » de Descartes paraît-elle, en annexe du Discours de la méthode ?","r":["1537","1637","1737","1837"],"b":1,"a":"C'est dans cet ouvrage que Descartes prend l'habitude de noter x, y et z les inconnues, usage resté depuis.","c":"Sciences"},{"id":"uzzhrctn","t":"En 1891, la jeune Polonaise Maria Skłodowska arrive à Paris pour étudier les sciences. Dans quelle institution s'inscrit-elle ?","r":["Collège de France","Sorbonne","Muséum d'histoire naturelle","École polytechnique"],"b":1,"a":"Elle y obtient deux licences, de physique puis de mathématiques, avant de rencontrer Pierre Curie en 1894.","c":"Sciences"},{"id":"evbsw50q","t":"Dès les premières secondes, avec quoi arrose-t-on une brûlure légère ?","r":["De l'eau tempérée","Du beurre","De la glace","Du vinaigre"],"b":0,"a":"Refroidir tôt la peau limite l'extension de la brûlure en profondeur et calme la douleur.","c":"Sciences"},{"id":"cwtlmktk","t":"Quelle planète est la plus brillante dans le ciel, vue de la Terre ?","r":["Jupiter","Mars","Mercure","Vénus"],"b":3,"a":"Son éclat est tel qu'on peut parfois la voir en plein jour, si l'on sait où regarder.","c":"Sciences"},{"id":"o19dj30n","t":"Quel savant italien a été condamné par l'Inquisition en 1633 pour avoir défendu que la Terre tourne autour du Soleil ?","r":["Giordano Bruno","Galilée","Evangelista Torricelli","Léonard de Vinci"],"b":1,"a":"Contraint de renier ses idées, il a passé le reste de sa vie en résidence surveillée près de Florence.","c":"Sciences"},{"id":"jthb9vdl","t":"Quelle maladie est liée à un taux de sucre trop élevé dans le sang, faute d'insuline efficace ?","r":["Le diabète","L'anémie","L'asthme","La jaunisse"],"b":0,"a":"Le mot « diabète » vient du grec et évoque un liquide qui traverse le corps.","c":"Sciences"},{"id":"6fkk6fs9","t":"Quel langage de balisage décrit la structure d'une page web : titres, paragraphes, liens ?","r":["CSS","HTML","SQL","PHP"],"b":1,"a":"Tim Berners-Lee a conçu le HTML au CERN, au début des années 1990, en même temps que le Web.","c":"Sciences"},{"id":"958cjznt","t":"Comment appelle-t-on la plus petite partie d'un élément chimique qui en garde les propriétés ?","r":["La molécule","L'atome","L'ion","Le cristal"],"b":1,"a":"Le mot vient du grec atomos, « qu'on ne peut couper », alors que l'atome est fait de particules plus petites.","c":"Sciences"},{"id":"eldijkmt","t":"À quelle altitude, en kilomètres, tournent les satellites en orbite géostationnaire ?","r":["400 km","3 600 km","36 000 km","360 000 km"],"b":2,"a":"L'écrivain Arthur C. Clarke a popularisé en 1945 l'idée d'y placer des satellites de télécommunication.","c":"Sciences"},{"id":"f6qgsabg","t":"Dans le mot « e-mail », que signifie la lettre e ?","r":["Express","Electronic","Easy","External"],"b":1,"a":"Au Québec, on a forgé « courriel », de « courrier électronique » : le mot a ensuite été adopté en France.","c":"Sciences"},{"id":"f7ka02qs","t":"Quelle planète porte le nom de la déesse romaine de l'amour ?","r":["Mars","Mercure","Saturne","Vénus"],"b":3,"a":"Vénus est l'astre le plus brillant du ciel après le Soleil et la Lune.","c":"Sciences"},{"id":"jbfa9ygx","t":"Combien de dents de lait un enfant possède-t-il en général une fois la série complète ?","r":["16","24","20","28"],"b":2,"a":"Les dents de lait tombent entre six et douze ans environ, remplacées par les dents définitives.","c":"Sciences"},{"id":"r5exspad","t":"À partir de quelle vitesse de vent soutenu, en kilomètres par heure, une tempête tropicale devient-elle un ouragan ?","r":["62 km/h","118 km/h","250 km/h","90 km/h"],"b":1,"a":"Le même phénomène s'appelle ouragan dans l'Atlantique, typhon dans le nord-ouest du Pacifique et cyclone dans l'océan Indien.","c":"Sciences"},{"id":"w0dtjrnz","t":"Comment appelle-t-on l'explosion d'une étoile massive en fin de vie ?","r":["Une nova","Une supernova","Un pulsar","Un quasar"],"b":1,"a":"Celle de 1054, notée par des astronomes chinois, a laissé derrière elle la nébuleuse du Crabe.","c":"Sciences"},{"id":"ud6m39hh","t":"Comment s'appelle la ligne imaginaire, à la latitude 0°, qui sépare l'hémisphère Nord de l'hémisphère Sud ?","r":["Le tropique du Cancer","L'équateur","Le méridien de Greenwich","Le cercle polaire arctique"],"b":1,"a":"Sur l'équateur, le jour et la nuit durent à peu près douze heures toute l'année.","c":"Sciences"},{"id":"z0acalx9","t":"En quelle année Benoît Mandelbrot a-t-il forgé le mot « fractale » ?","r":["1875","1925","1975","2005"],"b":2,"a":"Mandelbrot a tiré ce mot du latin fractus, « brisé », pour décrire des formes qui se répètent à toutes les échelles.","c":"Sciences"},{"id":"75a6t2ul","t":"Dans quelle bande de fréquence, en gigahertz, fonctionne historiquement le Wi-Fi ?","r":["1,1 GHz","1,6 GHz","2,4 GHz","4,2 GHz"],"b":2,"a":"Les fours à micro-ondes chauffent aussi autour de cette fréquence, ce qui peut perturber le Wi-Fi quand ils tournent.","c":"Sciences"},{"id":"ux0ntggj","t":"Quel périphérique capte la voix d'un utilisateur pour un appel ou un enregistrement ?","r":["Un haut-parleur","Une imprimante","Un microphone","Un écran"],"b":2,"a":"Le mot vient du grec : « mikros », petit, et « phônê », la voix ou le son.","c":"Sciences"},{"id":"enlmippj","t":"Quelle température peut atteindre l'air traversé par un éclair, en degrés Celsius ?","r":["300 °C","3 000 °C","30 000 °C","3 000 000 °C"],"b":2,"a":"Le tonnerre naît de cet échauffement brutal : l'air dilaté d'un coup produit une onde de choc qui gronde.","c":"Sciences"}],"moyen":[{"id":"awno2485","t":"Quel grand muscle en forme de dôme sépare le thorax de l'abdomen et commande la respiration ?","r":["Le trapèze","Le psoas","Le grand pectoral","Le diaphragme"],"b":3,"a":"Le hoquet vient de contractions involontaires et brusques de ce muscle.","c":"Sciences"},{"id":"heeof4wp","t":"Quelle application de messagerie, créée par Jan Koum et Brian Acton, Facebook a-t-il rachetée en 2014 ?","r":["Telegram","Viber","Signal","WhatsApp"],"b":3,"a":"Son nom est un jeu de mots sur l'expression anglaise « What's up ? », qui signifie « Quoi de neuf ? ».","c":"Sciences"},{"id":"ee33jt9w","t":"Quel pays a posé en août 2023 un atterrisseur près du pôle Sud de la Lune ?","r":["Chine","Japon","États-Unis","Inde"],"b":3,"a":"Son atterrisseur se nomme Vikram et son petit rover Pragyan.","c":"Sciences"},{"id":"r2pbyewi","t":"Comment appelle-t-on une zone de hautes pressions atmosphériques, souvent synonyme de beau temps ?","r":["Une dépression","Un front","Un anticyclone","Un thalweg"],"b":2,"a":"Dans l'hémisphère Nord, l'air tourne autour d'un anticyclone dans le sens des aiguilles d'une montre.","c":"Sciences"},{"id":"xhl2gzmc","t":"Quel officier allemand a donné son nom aux grands dirigeables rigides du début du XXe siècle ?","r":["Otto Lilienthal","Gottlieb Daimler","Ferdinand von Zeppelin","Wilhelm Maybach"],"b":2,"a":"Le premier de ses dirigeables a volé en 1900 au-dessus du lac de Constance.","c":"Sciences"},{"id":"p92fxbxb","t":"Comment nomme-t-on une maladie qui touche la population de plusieurs continents à la fois ?","r":["Une endémie","Une épidémie","Une épizootie","Une pandémie"],"b":3,"a":"Le préfixe grec « pan- » signifie tout : la pandémie frappe potentiellement tout le monde.","c":"Sciences"},{"id":"jcyb128a","t":"Quelle glande, à l'avant du cou, produit des hormones qui règlent le métabolisme ?","r":["L'hypophyse","La thyroïde","Le thymus","Le pancréas"],"b":1,"a":"Elle a la forme d'un papillon et a besoin d'iode pour fonctionner.","c":"Sciences"},{"id":"v87nzqlx","t":"Par quelle lettre désigne-t-on l'ensemble des entiers relatifs, …, −2, −1, 0, 1, 2, … ?","r":["R","Z","N","E"],"b":1,"a":"La notation vient de l'allemand Zahlen, « nombres ». Le Q des rationnels vient, lui, de « quotient ».","c":"Sciences"},{"id":"vl2tw5sv","t":"Quelle substance, produite par les glandes sébacées, graisse naturellement la peau et les cheveux ?","r":["La kératine","Le sébum","La mélanine","Le collagène"],"b":1,"a":"Un excès de sébum qui bouche les pores favorise l'apparition des boutons d'acné.","c":"Sciences"},{"id":"fsob79fd","t":"Quel langage visuel à blocs, né au MIT en 2007, initie les enfants à la programmation ?","r":["Logo","Scratch","Pascal","Basic"],"b":1,"a":"Les enfants y assemblent des blocs colorés pour animer un petit chat orange.","c":"Sciences"},{"id":"uaunayku","t":"Quel débit maximal, en mégabits par seconde, offre la norme USB 2.0 ?","r":["12 Mbit/s","100 Mbit/s","480 Mbit/s","5 000 Mbit/s"],"b":2,"a":"La norme suivante, l'USB 3.0, a reconnu les ports rapides par une languette souvent colorée en bleu.","c":"Sciences"},{"id":"kyeodfhl","t":"Quel est le symbole chimique de l'azote ?","r":["Na","N","Ne","Ni"],"b":1,"a":"Lavoisier l'a nommé azote, « sans vie » en grec, parce qu'il n'entretient pas la respiration.","c":"Sciences"},{"id":"cm8ygrqr","t":"Quel médecin allemand a identifié en 1882 le bacille responsable de la tuberculose ?","r":["Louis Pasteur","Emil von Behring","Paul Ehrlich","Robert Koch"],"b":3,"a":"Il a reçu le prix Nobel de médecine en 1905 pour ses travaux sur la tuberculose.","c":"Sciences"},{"id":"0ov01ylf","t":"Comment s'appelle l'assistant vocal d'Amazon, intégré à ses enceintes Echo ?","r":["Cortana","Siri","Bixby","Alexa"],"b":3,"a":"Alexa est apparue avec l'enceinte connectée Echo, lancée par Amazon fin 2014.","c":"Sciences"},{"id":"u4euzj9c","t":"En combien d'années terrestres Neptune fait-elle le tour du Soleil ?","r":["84 ans","165 ans","248 ans","29 ans"],"b":1,"a":"Découverte en 1846, Neptune n'a achevé son premier tour complet depuis cette date qu'en 2011.","c":"Sciences"},{"id":"pvxr18qq","t":"Quel navigateur, lancé fin 1994, dominait le Web grand public avant l'essor d'Internet Explorer ?","r":["Opera","Netscape Navigator","Lynx","HotJava"],"b":1,"a":"Son éditeur, Netscape Communications, a été racheté en 1999 par AOL, et le code du navigateur a servi de base à Mozilla.","c":"Sciences"},{"id":"y4chyzgw","t":"Comment appelle-t-on les lueurs d'orage lointain qu'on voit sans entendre le tonnerre, les soirs d'été ?","r":["Feu de Saint-Elme","Éclairs de chaleur","Foudre en boule","Aurores"],"b":1,"a":"Malgré leur nom, ils ne naissent pas de la chaleur : ce sont les éclairs d'un orage trop éloigné pour que son tonnerre nous parvienne.","c":"Sciences"},{"id":"qc4u4yaj","t":"Dans quelle commune de Guyane se trouve le Centre spatial d'où partent les fusées européennes ?","r":["Cayenne","Kourou","Saint-Laurent-du-Maroni","Mana"],"b":1,"a":"Le site a été choisi pour sa proximité avec l'équateur, où la rotation de la Terre donne un élan supplémentaire aux fusées.","c":"Sciences"},{"id":"2nxlq8gz","t":"Comment s'appelle la plus grosse artère du corps, celle qui part du cœur ?","r":["L'artère pulmonaire","L'aorte","La veine cave","La carotide"],"b":1,"a":"Chez l'adulte, elle mesure environ 2,5 cm de diamètre à sa sortie du cœur.","c":"Sciences"},{"id":"1u6y0iri","t":"De quelle expression anglaise le mot « bit » est-il la contraction ?","r":["Basic item","Binary digit","Big integer","Byte unit"],"b":1,"a":"Le mot a été popularisé par le mathématicien américain Claude Shannon en 1948.","c":"Sciences"},{"id":"j3ipi4ea","t":"Quelle étoile est la plus proche du Soleil ?","r":["Sirius","Véga","Proxima du Centaure","Bételgeuse"],"b":2,"a":"Trop faible pour être vue à l'œil nu, elle se trouve à un peu plus de quatre années-lumière de nous.","c":"Sciences"},{"id":"mer0wl5a","t":"Quel physicien français a montré en 1851, sous la coupole du Panthéon à Paris, la rotation de la Terre avec un grand pendule ?","r":["Léon Foucault","Hippolyte Fizeau","François Arago","Augustin Fresnel"],"b":0,"a":"Il a aussi inventé le gyroscope, en 1852.","c":"Sciences"},{"id":"obkxbcqc","t":"Que signifie le sigle PDF, celui d'un type de document très répandu ?","r":["Portable Document Format","Printable Data File","Personal Document Form","Public Digital File"],"b":0,"a":"Adobe a créé le PDF en 1993 pour qu'un document s'affiche à l'identique sur n'importe quel appareil.","c":"Sciences"},{"id":"75z1d7hr","t":"En 2020, quelle microbiologiste française a partagé le prix Nobel de chimie pour les « ciseaux génétiques » CRISPR ?","r":["Françoise Barré-Sinoussi","Anne L'Huillier","Emmanuelle Charpentier","Esther Duflo"],"b":2,"a":"Elle a développé cet outil avec l'Américaine Jennifer Doudna.","c":"Sciences"}],"difficile":[{"id":"yzw08d9v","t":"Quelle force, due à la rotation de la Terre, fait dévier les vents vers la droite dans l'hémisphère Nord ?","r":["La force de Laplace","La poussée d'Archimède","La force de Lorentz","La force de Coriolis"],"b":3,"a":"Elle porte le nom du mathématicien français Gaspard-Gustave Coriolis, qui l'a décrite au XIXe siècle.","c":"Sciences"},{"id":"a3b1phoi","t":"Combien de poignées de main sont échangées si six personnes se serrent toutes la main une fois chacune ?","r":["12","15","18","21"],"b":1,"a":"Ce problème des poignées de main sert souvent à introduire les combinaisons et la théorie des graphes.","c":"Sciences"},{"id":"b37uew70","t":"Comment appelle-t-on la partie finale d'un nom de domaine, comme « .fr » ou « .com » ?","r":["Sous-domaine","Protocole","Domaine de premier niveau","Port"],"b":2,"a":"Le « .fr » de la France est géré par l'Afnic, une association installée près de Paris.","c":"Sciences"},{"id":"4kjn6nax","t":"Quel sommet est le point de la surface terrestre le plus éloigné du centre de la Terre ?","r":["Everest","Kilimandjaro","Chimborazo","Mauna Kea"],"b":2,"a":"Situé en Équateur, il profite du renflement de la Terre à l'équateur : son sommet dépasse celui de l'Everest d'environ deux kilomètres en distance au centre.","c":"Sciences"},{"id":"3zc2px5t","t":"Quelle unité mesure l'éclairement, c'est-à-dire la lumière reçue par une surface ?","r":["Le lumen","La candela","Le watt","Le lux"],"b":3,"a":"Un bureau bien éclairé reçoit quelques centaines de lux, quand le plein soleil d'été en apporte des dizaines de milliers.","c":"Sciences"},{"id":"yr47vxjo","t":"Quel est le nom savant des globules rouges ?","r":["Leucocytes","Thrombocytes","Lymphocytes","Érythrocytes"],"b":3,"a":"Chez l'être humain, les globules rouges adultes n'ont pas de noyau, ce qui leur laisse plus de place pour l'hémoglobine.","c":"Sciences"},{"id":"zqiedrhd","t":"Dans quel organe se trouvent les néphrons, unités qui filtrent le sang ?","r":["Foie","Rate","Rein","Pancréas"],"b":2,"a":"Chaque rein compte environ un million de néphrons, qui travaillent chacun comme un minuscule filtre.","c":"Sciences"},{"id":"8oqlpiiw","t":"Combien existe-t-il de solides de Platon, ces polyèdres réguliers convexes ?","r":["4","5","6","8"],"b":1,"a":"Euclide conclut ses Éléments en montrant qu'il n'en existe aucun autre.","c":"Sciences"},{"id":"8fg26fpw","t":"Quel muscle triangulaire recouvre l'épaule et permet de lever le bras sur le côté ?","r":["Le trapèze","Le deltoïde","Le biceps","Le pectoral"],"b":1,"a":"Son nom vient de la lettre grecque delta, dont il rappelle la forme en triangle.","c":"Sciences"},{"id":"wyrn6vnh","t":"Quel inventeur américain a découvert en 1839 la vulcanisation, qui rend le caoutchouc solide et élastique ?","r":["John Dunlop","Charles Goodyear","Henry Ford","André Michelin"],"b":1,"a":"Charles Goodyear est mort couvert de dettes ; l'entreprise de pneus qui porte son nom a été fondée après sa mort, sans lui.","c":"Sciences"},{"id":"a5ezk3ja","t":"Quel ingénieur allemand a breveté en 1892 un moteur où le carburant s'enflamme par la seule compression de l'air ?","r":["Nikolaus Otto","Rudolf Diesel","Carl Benz","Gottlieb Daimler"],"b":1,"a":"À l'Exposition universelle de Paris en 1900, un de ses moteurs a fonctionné à l'huile d'arachide.","c":"Sciences"},{"id":"pdtc1yus","t":"Comment s'appelle la valve située entre l'oreillette gauche et le ventricule gauche du cœur ?","r":["Valve tricuspide","Valve aortique","Valve pulmonaire","Valve mitrale"],"b":3,"a":"Son nom vient de sa forme, qui rappelle celle d'une mitre d'évêque.","c":"Sciences"},{"id":"mz0xq07g","t":"Que vaut 2 puissance 0 ?","r":["0","2","1","Un demi"],"b":2,"a":"Tout nombre non nul élevé à la puissance 0 vaut 1, une convention qui garde vraie la règle d'addition des exposants.","c":"Sciences"},{"id":"rrw5xbud","t":"Quelle lune de Jupiter, la plus petite des quatre découvertes par Galilée, cache sans doute un océan sous sa glace ?","r":["Ganymède","Callisto","Io","Europe"],"b":3,"a":"Une mission de la NASA, Europa Clipper, a été conçue pour étudier cet océan caché.","c":"Sciences"},{"id":"pm4z16h6","t":"Quelle technologie d'affichage, qui imite le papier, équipe la plupart des liseuses électroniques ?","r":["L'encre électronique","L'écran OLED","L'écran plasma","L'écran à tube cathodique"],"b":0,"a":"Un écran à encre électronique ne consomme de l'énergie que lorsqu'il change d'image : une page fixe ne coûte rien à la batterie.","c":"Sciences"},{"id":"3cdiwleq","t":"Comment appelait-on l'épilepsie dans l'Antiquité ?","r":["Le mal des ardents","Le mal sacré","Le mal des montagnes","Le mal du siècle"],"b":1,"a":"Un traité attribué à Hippocrate, « De la maladie sacrée », soutenait pourtant qu'elle avait une cause naturelle et non divine.","c":"Sciences"},{"id":"hcr2sxe8","t":"Quel gaz a été surnommé « gaz hilarant » ?","r":["Le dioxyde d'azote","L'ammoniac","Le protoxyde d'azote","Le monoxyde de carbone"],"b":2,"a":"Dès le XIXe siècle, des dentistes l'ont employé comme anesthésiant ; il sert encore en médecine, mêlé à de l'oxygène.","c":"Sciences"},{"id":"u4bvv93f","t":"Quelle maladie les médecins du XIXe siècle appelaient-ils souvent la phtisie ?","r":["La pneumonie","L'asthme","La tuberculose","La coqueluche"],"b":2,"a":"Le poète John Keats en est mort en 1821, à vingt-cinq ans.","c":"Sciences"},{"id":"xapes4pr","t":"Comment nomme-t-on le point de l'orbite terrestre où la Terre est la plus éloignée du Soleil ?","r":["Le périhélie","L'apogée","L'aphélie","Le zénith"],"b":2,"a":"La Terre y passe début juillet, en plein été de l'hémisphère Nord.","c":"Sciences"},{"id":"4tciuaw5","t":"Comment appelle-t-on le point où se coupent les trois médianes d'un triangle ?","r":["L'orthocentre","Le centre de gravité","Le centre du cercle inscrit","Le centre du cercle circonscrit"],"b":1,"a":"Une plaque triangulaire de bois ou de carton, posée sur une pointe en ce point, tient en équilibre.","c":"Sciences"}]},"Nature":{"facile":[{"id":"7s9ghcan","t":"Comment appelle-t-on le petit du bouc et de la bique ?","r":["Le chevreau","L'agneau","Le veau","Le poulain"],"b":0,"a":"On dit aussi cabri ; et la chèvre donne souvent naissance à deux petits à la fois.","c":"Nature"},{"id":"b8ymdz4r","t":"Quelle fleur blanche à cœur jaune effeuille-t-on en récitant « il m'aime, un peu, beaucoup… » ?","r":["Coquelicot","Violette","Tulipe","Marguerite"],"b":3,"a":"Son nom vient du grec margaritês, « perle ».","c":"Nature"},{"id":"xubtojbp","t":"Comment appelle-t-on la femelle du loup ?","r":["La laie","La hase","La louve","La biche"],"b":2,"a":"Selon la légende, une louve aurait allaité Romulus et Rémus, les jumeaux fondateurs de Rome.","c":"Nature"},{"id":"ef1inzir","t":"Comment appelle-t-on le petit du chat ?","r":["Chiot","Chaton","Lapereau","Ourson"],"b":1,"a":"Le chaton naît les yeux fermés : ils ne s'ouvrent qu'au bout d'une à deux semaines.","c":"Nature"},{"id":"x6l4ljx3","t":"Quelle plante sauvage pique la peau quand on la frôle ?","r":["Le pissenlit","L'ortie","Le trèfle","La pâquerette"],"b":1,"a":"Ses poils fonctionnent comme de minuscules seringues : leur pointe cassante injecte un liquide irritant.","c":"Nature"},{"id":"m4zm8r3c","t":"Quel oiseau bleu et orange plonge dans les rivières pour attraper de petits poissons ?","r":["Le guêpier","Le geai","Le loriot","Le martin-pêcheur"],"b":3,"a":"Il creuse son nid au bout d'un tunnel dans une berge de terre, parfois long de près d'un mètre.","c":"Nature"},{"id":"rcm7u6vz","t":"En quelle année le moratoire international sur la chasse commerciale à la baleine est-il entré en vigueur ?","r":["1972","1979","1986","1995"],"b":2,"a":"Ce moratoire a été voté par la Commission baleinière internationale en 1982, avec un délai de quelques saisons avant son application.","c":"Nature"},{"id":"ippbfyy4","t":"Quel serpent géant d'Amérique du Sud passe l'essentiel de sa vie dans l'eau des marais et des rivières ?","r":["Le python royal","Le cobra royal","Le boa constricteur","L'anaconda vert"],"b":3,"a":"Ses yeux et ses narines sont placés sur le dessus de la tête : l'anaconda peut guetter ses proies presque entièrement immergé.","c":"Nature"},{"id":"vuvu1n1z","t":"Combien de kilomètres parcourt environ une cigogne blanche d'Europe qui va hiverner en Afrique du Sud ?","r":["1 000 km","10 000 km","50 000 km","500 km"],"b":1,"a":"Pour économiser ses forces, la cigogne plane sur les courants d'air chaud et contourne la Méditerranée par Gibraltar ou le Bosphore.","c":"Nature"},{"id":"04r8ydps","t":"Quel animal de la ferme est tondu pour sa laine ?","r":["La vache","Le mouton","Le cochon","La chèvre"],"b":1,"a":"Un mouton qu'on ne tond jamais continue de faire pousser sa laine, au point de pouvoir porter une toison énorme et étouffante.","c":"Nature"},{"id":"j4c2z88f","t":"Quel poisson d'eau douce doit son nom à ses longs barbillons, qui rappellent des moustaches ?","r":["Le poisson-chat","Le poisson-lion","Le poisson-chien","Le poisson-loup"],"b":0,"a":"Ses barbillons sont couverts de récepteurs du goût : le poisson-chat s'en sert pour trouver sa nourriture dans l'eau trouble.","c":"Nature"},{"id":"n0xdjzu5","t":"Quels sont les plus proches parents vivants de l'espèce humaine ?","r":["Gibbon et siamang","Gorille et orang-outan","Babouin et macaque","Chimpanzé et bonobo"],"b":3,"a":"Le bonobo, longtemps pris pour un chimpanzé de petite taille, n'a été reconnu comme une espèce à part qu'en 1929.","c":"Nature"},{"id":"2hq04x3p","t":"Quel mammifère marin des mers froides est reconnaissable à ses longues défenses ?","r":["Le phoque","Le morse","L'otarie","Le lamantin"],"b":1,"a":"Les défenses du morse servent aussi à se hisser sur la glace, d'où son nom scientifique Odobenus, « qui marche avec les dents ».","c":"Nature"},{"id":"3uotjkkt","t":"Quel petit lézard, très commun en France, se chauffe au soleil sur les pierres des vieilles bâtisses ?","r":["Le lézard vert","Le lézard ocellé","Le lézard des murailles","Le seps strié"],"b":2,"a":"Comme tous les reptiles, il ne produit pas sa propre chaleur : il doit s'exposer au soleil pour être actif.","c":"Nature"},{"id":"ov5dvelk","t":"Quel petit arbuste épineux donne les prunelles, petits fruits bleu-noir très âpres ?","r":["L'aubépine","Le prunellier","Le cornouiller","Le sureau"],"b":1,"a":"On dit que les prunelles gagnent en douceur après les premières gelées ; elles parfument des liqueurs.","c":"Nature"},{"id":"ogg2qd63","t":"Quel poisson géant, tacheté, se nourrit de plancton et ne représente aucun danger pour l'homme ?","r":["Le requin blanc","Le requin tigre","Le requin-marteau","Le requin-baleine"],"b":3,"a":"On le reconnaît à sa robe de taches blanches, unique chez chaque individu.","c":"Nature"},{"id":"ek3gxxqm","t":"Comment qualifie-t-on un oiseau qui se nourrit surtout de graines ?","r":["Insectivore","Frugivore","Piscivore","Granivore"],"b":3,"a":"Les granivores, comme le moineau ou le pinson, ont souvent un bec court et conique, idéal pour casser les graines.","c":"Nature"},{"id":"yb8ha06z","t":"Quelle fleur est l'emblème des Pays-Bas, cultivée en immenses champs colorés ?","r":["Rose","Iris","Tulipe","Jacinthe"],"b":2,"a":"Originaire d'Asie centrale, elle a provoqué en Hollande une spéculation folle, la tulipomanie, en 1636-1637.","c":"Nature"},{"id":"n60cjyoe","t":"Quel mot désigne la diversité des espèces vivantes, de leurs gènes et des milieux qu'elles habitent ?","r":["Biodiversité","Biosphère","Biologie","Biomasse"],"b":0,"a":"Le mot s'est imposé dans les années 1980 et s'est répandu dans le monde avec le Sommet de la Terre de Rio, en 1992.","c":"Nature"},{"id":"0csdkbmc","t":"Quels organes permettent à un poisson d'avancer et de se diriger dans l'eau ?","r":["Les nageoires","Les branchies","Les écailles","Les barbillons"],"b":0,"a":"La nageoire de la queue, la caudale, fournit l'essentiel de la poussée chez la plupart des poissons.","c":"Nature"},{"id":"q54nvjfq","t":"Quelle plante détient le record de croissance, avec parfois près d'un mètre par jour ?","r":["Le lierre","Le tournesol","Le bambou","La vigne"],"b":2,"a":"Malgré sa taille, le bambou n'est pas un arbre mais une herbe géante, de la même famille que le blé.","c":"Nature"},{"id":"d36lhclw","t":"Quel animal transporte sa coquille sur son dos ?","r":["La limace","Le ver de terre","L'escargot","La chenille"],"b":2,"a":"L'escargot peut se retirer entièrement dans sa coquille pour se protéger de la sécheresse ou d'un prédateur.","c":"Nature"},{"id":"pd78mkvl","t":"Combien pèse environ un œuf d'autruche, en kilogrammes ?","r":["0,4 kg","1,4 kg","5 kg","8 kg"],"b":1,"a":"Sa coquille est si épaisse qu'un adulte peut monter dessus sans la briser.","c":"Nature"},{"id":"8aar5psg","t":"Combien de dents environ un grand requin blanc compte-t-il dans la gueule, toutes rangées confondues ?","r":["30","300","3 000","30 000"],"b":1,"a":"Ses dents sont triangulaires et dentelées comme une scie, ce qui l'aide à découper de grosses proies.","c":"Nature"}],"moyen":[{"id":"4hyub5kb","t":"Dans quel pays se trouve le parc national de Banff, au cœur des montagnes Rocheuses ?","r":["États-Unis","Canada","Nouvelle-Zélande","Norvège"],"b":1,"a":"Créé en 1885, Banff est le plus ancien parc national du Canada ; son lac Louise est célèbre pour ses eaux turquoise.","c":"Nature"},{"id":"1zxgb3ui","t":"Quel félin d'Afrique porte deux traits noirs, comme des larmes, du coin des yeux jusqu'à la gueule ?","r":["Serval","Lion","Caracal","Guépard"],"b":3,"a":"Contrairement aux autres grands félins, le guépard ne rugit pas : il émet notamment des sortes de gazouillis qui rappellent des cris d'oiseau.","c":"Nature"},{"id":"xoa9wl75","t":"En 2018, Sudan est mort au Kenya : de quelle sous-espèce était-il le dernier mâle ?","r":["Rhinocéros blanc du Nord","Rhinocéros de Java","Rhinocéros blanc du Sud","Rhinocéros de Sumatra"],"b":0,"a":"Seules deux femelles, sa fille Najin et sa petite-fille Fatu, lui ont survécu.","c":"Nature"},{"id":"t3ma19bn","t":"Quel site californien de bitume naturel a piégé des milliers d'animaux de l'ère glaciaire, des loups comme des mammouths ?","r":["Burgess Shale","Hell Creek","Dinosaur Ridge","La Brea"],"b":3,"a":"Les herbivores s'enlisaient dans le bitume, attirant des carnivores qui s'y piégeaient à leur tour.","c":"Nature"},{"id":"pebp51p4","t":"Combien de doigts un chat ordinaire a-t-il en tout, aux quatre pattes réunies ?","r":["18 doigts","16 doigts","20 doigts","14 doigts"],"b":0,"a":"Les pattes avant portent cinq doigts, dont un petit, haut sur la patte ; les pattes arrière n'en ont que quatre.","c":"Nature"},{"id":"8v0a9djd","t":"Quel grand rapace sud-américain figure sur les armoiries de la Colombie, de l'Équateur et de la Bolivie ?","r":["Quetzal","Aigle harpie","Condor des Andes","Ara rouge"],"b":2,"a":"Avec trois mètres d'envergure environ, le condor des Andes compte parmi les plus grands oiseaux volants du monde.","c":"Nature"},{"id":"2lsf2kyg","t":"En quelle année l'Office national des forêts a-t-il été créé ?","r":["1964","1946","1970","1954"],"b":0,"a":"Il gère les forêts publiques de l'État et des communes, soit environ un quart de la forêt française.","c":"Nature"},{"id":"rg1ajnzf","t":"De quelles couleurs est la peau de la salamandre tachetée ?","r":["Vert et rouge","Noir et jaune","Brun et blanc","Bleu et orange"],"b":1,"a":"Ses couleurs vives avertissent les prédateurs : sa peau sécrète une substance toxique.","c":"Nature"},{"id":"bc1535kt","t":"De quelle matière est principalement faite la coquille d'un mollusque comme l'escargot de mer ou la moule ?","r":["De la kératine","De la chitine","Du calcaire","De la silice"],"b":2,"a":"La coquille grandit par son bord : le manteau du mollusque y dépose sans cesse de nouvelles couches.","c":"Nature"},{"id":"892zbjbh","t":"Sous quel autre nom la morue fraîche est-elle vendue chez le poissonnier ?","r":["Merlu","Cabillaud","Colin","Lieu noir"],"b":1,"a":"Salée et séchée, la même espèce se vend sous le nom de morue ; elle nourrit les pêcheurs depuis des siècles.","c":"Nature"},{"id":"wwopyg3h","t":"De quelle couleur est le duvet des poussins de flamant rose à l'éclosion ?","r":["Rose pâle","Gris","Jaune","Orangé"],"b":1,"a":"Les jeunes flamants mettent plusieurs années à prendre leur couleur rose définitive, au fil de leur alimentation.","c":"Nature"},{"id":"gireadlg","t":"Comment appelle-t-on l'art japonais de cultiver des arbres miniatures en pot ?","r":["L'ikebana","Le kokedama","Le bonsaï","L'origami"],"b":2,"a":"Un bonsaï n'est pas une espèce naine : c'est un arbre ordinaire, maintenu petit par la taille des branches et des racines.","c":"Nature"},{"id":"wta0bu57","t":"Comment appelle-t-on le petit de l'âne ?","r":["Le poulain","L'ânon","Le muleton","Le bardot"],"b":1,"a":"L'âne descend de l'âne sauvage d'Afrique et a été domestiqué il y a plusieurs millénaires.","c":"Nature"},{"id":"jhbk5fut","t":"Quel grand oiseau migrateur fait chaque automne halte par milliers au lac du Der, en Champagne ?","r":["Le flamant rose","Le pélican blanc","Le fou de Bassan","La grue cendrée"],"b":3,"a":"Au lac du Der, on vient observer à l'automne le vol de ces grandes migratrices, qui font étape avant l'Espagne.","c":"Nature"},{"id":"ds7auzjb","t":"En 1627, en Pologne, quel grand bovin sauvage, ancêtre des vaches domestiques, a vu mourir sa dernière femelle connue ?","r":["Le bison d'Europe","Le yack","L'aurochs","Le buffle d'Asie"],"b":2,"a":"On le voit sur les parois de la grotte de Lascaux.","c":"Nature"},{"id":"a2ybhnuv","t":"Quel serpent de France, inoffensif et bon nageur, se reconnaît à deux taches claires en croissant derrière la tête ?","r":["La vipère aspic","La couleuvre à collier","La couleuvre d'Esculape","La coronelle lisse"],"b":1,"a":"Menacée, elle peut faire la morte, la bouche ouverte et la langue pendante, pour décourager son agresseur.","c":"Nature"},{"id":"fb5cflxe","t":"Quel arbre fruitier donne les mirabelles, spécialité de la Lorraine ?","r":["Cerisier","Abricotier","Prunier","Pêcher"],"b":2,"a":"La Lorraine assure l'essentiel de la production mondiale de mirabelles, et la mirabelle de Lorraine bénéficie d'une indication géographique protégée.","c":"Nature"},{"id":"oc1m00pb","t":"Quel animal d'Amérique du Sud porte aussi le nom de grand fourmilier ?","r":["Le tatou","Le pécari","Le coati","Le tamanoir"],"b":3,"a":"Le tamanoir n'a pas de dents : il capture fourmis et termites avec une langue très longue et collante.","c":"Nature"},{"id":"q0n178t5","t":"Quel est le plus grand félin d'Amérique ?","r":["Le puma","L'ocelot","Le jaguar","Le lynx roux"],"b":2,"a":"Le jaguar est un des rares félins qui aiment l'eau : il chasse volontiers caïmans et poissons.","c":"Nature"},{"id":"39ajb5bb","t":"Quel insecte porte le surnom de « bête à bon Dieu » ?","r":["Le hanneton","La coccinelle","Le carabe","La punaise verte"],"b":1,"a":"Elle est la meilleure alliée des jardiniers : une seule coccinelle dévore des centaines de pucerons au cours de sa vie.","c":"Nature"},{"id":"io7x1jcu","t":"Quels grands oiseaux sans ailes de Nouvelle-Zélande, chassés par les Maoris, ont disparu avant l'arrivée des Européens ?","r":["Les kiwis","Les kakapos","Les casoars","Les moas"],"b":3,"a":"L'aigle de Haast, le plus grand aigle connu, les chassait ; il a disparu avec eux.","c":"Nature"},{"id":"0yxwp282","t":"Comment appelle-t-on un groupe de poissons qui nagent ensemble de manière coordonnée ?","r":["Une harde","Une meute","Un banc","Une volée"],"b":2,"a":"En nageant en banc, les poissons déroutent les prédateurs, qui peinent à isoler un individu au milieu de la masse.","c":"Nature"},{"id":"z9ut78nm","t":"Quel organe permet aux poissons de percevoir les mouvements de l'eau ?","r":["Les évents","La vessie natatoire","La ligne latérale","Les opercules"],"b":2,"a":"Elle explique comment un banc change de direction d'un seul coup, sans que les poissons se touchent.","c":"Nature"},{"id":"8qm13yk8","t":"Combien de jours dure l'incubation d'un œuf de cane de Barbarie ?","r":["28 jours","42 jours","35 jours","30 jours"],"b":2,"a":"Croisé avec la cane commune, le canard de Barbarie mâle donne le mulard.","c":"Nature"}],"difficile":[{"id":"mbbu1nd0","t":"Que signifie le nom du dinosaure Diplodocus ?","r":["Cou de serpent","Longue queue","Double poutre","Lézard géant"],"b":2,"a":"Le nom évoque de petits os en forme de double poutre sous la queue, les chevrons.","c":"Nature"},{"id":"4ufxqel4","t":"Quel héron de nos marais, très discret, émet un cri grave qui évoque le mugissement d'un taureau ?","r":["Le héron pourpré","Le blongios nain","Le bihoreau gris","Le butor étoilé"],"b":3,"a":"Son « boum » grave porte à plusieurs kilomètres, alors que cet oiseau reste presque toujours caché dans les roseaux.","c":"Nature"},{"id":"vnmwkw7q","t":"Qu'avait de particulier le pouce de l'Iguanodon ?","r":["Une pointe osseuse conique","Il était palmé","Il était absent","Une ventouse"],"b":0,"a":"Gideon Mantell avait d'abord placé cette pointe sur le nez de l'animal, comme une corne de rhinocéros.","c":"Nature"},{"id":"gqc9gx38","t":"Quel petit dinosaure à plumes de Chine semble avoir eu quatre ailes, aux bras comme aux pattes ?","r":["Caudiptéryx","Microraptor","Sinosauroptéryx","Oviraptor"],"b":1,"a":"Il vivait au Crétacé, il y a plus de cent millions d'années, et son corps était couvert de plumes.","c":"Nature"},{"id":"4cqbchb7","t":"Dans quel pays l'organisation WWF a-t-elle été fondée, en 1961 ?","r":["Royaume-Uni","États-Unis","Pays-Bas","Suisse"],"b":3,"a":"Le WWF a établi son premier siège à Morges, au bord du lac Léman ; il est aujourd'hui installé à Gland, dans le canton de Vaud.","c":"Nature"},{"id":"ep361ft3","t":"Quels insectes un myrmécologue étudie-t-il ?","r":["Les fourmis","Les abeilles","Les papillons","Les termites"],"b":0,"a":"Les fourmis vivent sur tous les continents sauf l'Antarctique, et l'on en a décrit plus de dix mille espèces.","c":"Nature"},{"id":"wmai8sbd","t":"Quel chien, dont le nom allemand Dachshund signifie « chien à blaireau », fut créé pour chasser dans les terriers ?","r":["Le teckel","Le basset hound","Le beagle","Le cocker"],"b":0,"a":"Ses pattes courtes et son corps allongé lui permettaient de se faufiler dans les galeries pour y débusquer l'animal.","c":"Nature"},{"id":"sx83zxyx","t":"Quel oiseau marin plonge en piqué du ciel et niche en grande colonie aux Sept-Îles, en Bretagne ?","r":["Le fou de Bassan","Le goéland argenté","Le cormoran huppé","Le macareux moine"],"b":0,"a":"Les Sept-Îles abritent la seule colonie de fous de Bassan de France.","c":"Nature"},{"id":"7f1mmwdx","t":"Quel lézard venimeux vit dans les déserts du sud-ouest des États-Unis et du Mexique ?","r":["Le monstre de Gila","Le moloch épineux","Le lézard à collerette","Le crapaud cornu"],"b":0,"a":"Il stocke des réserves de graisse dans sa queue et passe l'essentiel de sa vie dans un terrier.","c":"Nature"},{"id":"by5s3weq","t":"Quelle tortue marine, la plus grande de toutes, a une carapace souple, de type cuir ?","r":["La tortue caouanne","La tortue luth","La tortue verte","La tortue imbriquée"],"b":1,"a":"Elle plonge à plus d'un kilomètre de profondeur pour chasser les méduses, dont elle fait son menu principal.","c":"Nature"},{"id":"xkhawce3","t":"Comment s'appelle la troisième paupière, presque transparente, qui protège et humidifie l'œil des oiseaux ?","r":["La cornée","La conjonctive","La sclérotique","La membrane nictitante"],"b":3,"a":"Les rapaces abaissent cette paupière au moment de frapper leur proie, ce qui protège leurs yeux sans les aveugler.","c":"Nature"},{"id":"0l35jwpm","t":"Quel président était à l'Élysée quand le navire de Greenpeace Rainbow Warrior a été coulé dans le port d'Auckland, en 1985 ?","r":["Valéry Giscard d'Estaing","Jacques Chirac","François Mitterrand","Georges Pompidou"],"b":2,"a":"L'attentat, mené par des agents des services secrets français, a coûté la vie à un photographe du bateau et provoqué une grave crise politique.","c":"Nature"},{"id":"mc8tnd2f","t":"Quel arbre d'Amérique tropicale fournit un bois si léger qu'on l'emploie pour les maquettes d'avion ?","r":["L'acajou","L'ébène","Le teck","Le balsa"],"b":3,"a":"Le radeau Kon-Tiki, avec lequel Thor Heyerdahl traversa le Pacifique en 1947, était fait de troncs de balsa.","c":"Nature"},{"id":"5vlv0q2n","t":"Quel grand oiseau incapable de voler, proche cousin du dodo, vivait sur l'île Rodrigues avant de disparaître au XVIIIe siècle ?","r":["L'ibis de La Réunion","Le solitaire de Rodrigues","Le grand pingouin","Le moa"],"b":1,"a":"Le huguenot François Leguat, naufragé volontaire sur l'île à la fin du XVIIe siècle, a décrit ces oiseaux et leurs combats à coups d'ailes.","c":"Nature"},{"id":"8eib67w1","t":"Dans quelle région du monde vivent la plupart des oiseaux de paradis ?","r":["Madagascar","Amazonie","Nouvelle-Guinée","Bornéo"],"b":2,"a":"Les premières peaux arrivées en Europe n'avaient plus de pattes, d'où la légende d'oiseaux qui ne se posaient jamais.","c":"Nature"},{"id":"okpqb4sw","t":"Quel parc national, créé en 1925 dans l'actuelle République démocratique du Congo, fut le premier d'Afrique ?","r":["Le Serengeti","Le Kruger","Virunga","Tsavo"],"b":2,"a":"Il abrite des gorilles de montagne et des volcans actifs, et reste l'un des parcs les plus riches en espèces du continent.","c":"Nature"},{"id":"yyo08oy6","t":"Que signifie le nom du dinosaure Brachiosaure ?","r":["Lézard-colonne","Lézard-pilier","Lézard-bras","Lézard-tour"],"b":2,"a":"Ce nom date de 1903 ; ses premiers restes ont été trouvés aux États-Unis, dans le Colorado.","c":"Nature"},{"id":"2y84imzs","t":"Quel est le plus long serpent venimeux du monde ?","r":["Le mamba noir","Le cobra royal","Le taïpan du désert","La vipère du Gabon"],"b":1,"a":"Il peut dépasser cinq mètres. Menacé, il se dresse haut sur l'avant de son corps.","c":"Nature"},{"id":"pve9z1n6","t":"À quelle famille d'animaux le gnou appartient-il ?","r":["Les bovidés","Les équidés","Les cervidés","Les giraffidés"],"b":0,"a":"Chaque année, plus d'un million de gnous migrent entre le Serengeti et le Masai Mara.","c":"Nature"},{"id":"8ed5k75q","t":"Quel animal marin réel est sans doute à l'origine de la légende du kraken ?","r":["Le requin-baleine","Le calmar géant","Le cachalot","La raie manta"],"b":1,"a":"Le kraken, monstre des récits scandinaves, était dépeint capable d'entraîner des navires par le fond.","c":"Nature"}]},"Cinéma & séries":{"facile":[{"id":"w3oohdvx","t":"Dans « Friends », quel métier exerce Ross Geller ?","r":["Archéologue","Géologue","Historien","Paléontologue"],"b":3,"a":"Ross travaille d'abord dans un musée d'histoire naturelle, puis enseigne à l'université.","c":"Cinéma & séries"},{"id":"h41uf31f","t":"Quelle est la durée de « Titanic » (1997) de James Cameron, en minutes ?","r":["162 min","194 min","221 min","148 min"],"b":1,"a":"Pour le tournage, un immense décor du paquebot a été construit au Mexique, au bord du Pacifique.","c":"Cinéma & séries"},{"id":"nsvlv1n9","t":"De quelle couleur est Bob l'éponge, le héros de la série d'animation ?","r":["Rose","Jaune","Vert","Orange"],"b":1,"a":"Son créateur, Stephen Hillenburg, était biologiste marin avant de se consacrer à l'animation.","c":"Cinéma & séries"},{"id":"b14eyqoh","t":"Quel personnage déclare à Han Solo, dans « L'Empire contre-attaque », qu'elle préférerait embrasser un Wookiee ?","r":["Padmé Amidala","Rey","Leia Organa","Jyn Erso"],"b":2,"a":"Les Wookiees, dont fait partie Chewbacca, sont des géants poilus originaires de la planète Kashyyyk.","c":"Cinéma & séries"},{"id":"sc5k28mo","t":"Dans quel dessin animé deux souris de laboratoire se proposent-elles chaque nuit de « conquérir le monde » ?","r":["Tic et Tac","Minus et Cortex","Tom et Jerry","Les Razmoket"],"b":1,"a":"Minus et Cortex sont nés comme une rubrique de la série « Animaniacs », avant d'obtenir leur propre série en 1995.","c":"Cinéma & séries"},{"id":"8de87is0","t":"Devant un fond de quelle couleur unie filme-t-on souvent les acteurs pour y incruster ensuite un décor numérique ?","r":["Rouge","Vert","Noir","Jaune"],"b":1,"a":"On utilise aussi le bleu. Ces couleurs sont choisies car elles sont éloignées des tons de la peau, ce qui facilite le détourage.","c":"Cinéma & séries"},{"id":"xiwp6d6i","t":"En quelle année la série américaine Dallas a-t-elle été diffusée pour la première fois ?","r":["1991","1955","1978","2003"],"b":2,"a":"La question « Qui a tiré sur J.R. ? » a tenu des millions de spectateurs en haleine pendant l'été 1980.","c":"Cinéma & séries"},{"id":"l2yij7wy","t":"Combien d'images par seconde défilent traditionnellement dans un film de cinéma ?","r":["12","18","24","30"],"b":2,"a":"Cette cadence s'est imposée avec le cinéma parlant, à la fin des années 1920, pour assurer une bonne qualité de son.","c":"Cinéma & séries"},{"id":"kg979g3t","t":"Au cinéma, comment appelle-t-on un mouvement où la caméra se déplace, par exemple sur des rails ?","r":["Un panoramique","Un zoom","Un travelling","Un fondu"],"b":2,"a":"Le mot vient de l'anglais « to travel » : on y voit la caméra voyager à travers le décor.","c":"Cinéma & séries"},{"id":"m39s7j5w","t":"Quel réalisateur a signé « Inception » (2010) ?","r":["Denis Villeneuve","Christopher Nolan","Ridley Scott","David Fincher"],"b":1,"a":"Le film a reçu quatre Oscars techniques, dont celui des meilleurs effets visuels.","c":"Cinéma & séries"},{"id":"z7siyghr","t":"Dans « Les Simpson », quel est le prénom de la mère de famille aux hauts cheveux bleus ?","r":["Patty","Marge","Selma","Edna"],"b":1,"a":"Matt Groening a donné aux membres de la famille les prénoms de ses proches : Homer et Marge sont ceux de ses parents.","c":"Cinéma & séries"},{"id":"k9a8h1hn","t":"Quelle gigantesque station spatiale du premier « Star Wars » (1977) est capable de détruire une planète ?","r":["Base Starkiller","Étoile de la mort","Étoile rouge","Soleil noir"],"b":1,"a":"Ses plans, volés par les rebelles, révèlent la faille qui permettra de la détruire.","c":"Cinéma & séries"},{"id":"ivcdbuuh","t":"Quelle série française suit le roi Arthur et ses chevaliers de la Table ronde sur un ton comique ?","r":["Kaamelott","Hero Corp","Les Visiteurs","Caméra Café"],"b":0,"a":"Avant les longs épisodes, la série a commencé par des épisodes de quelques minutes, diffusés sur M6.","c":"Cinéma & séries"},{"id":"4uieqcd3","t":"Quelle arme Indiana Jones porte-t-il toujours à la ceinture, avec son chapeau ?","r":["Un lasso","Un boomerang","Un fouet","Une machette"],"b":2,"a":"Le personnage d'Indiana Jones est né de l'imagination de George Lucas, qui l'a confié à Steven Spielberg.","c":"Cinéma & séries"},{"id":"5nljt003","t":"Quelle actrice américaine incarne Katniss Everdeen dans « Hunger Games » (2012) ?","r":["Emma Watson","Kristen Stewart","Jennifer Lawrence","Shailene Woodley"],"b":2,"a":"Jennifer Lawrence a reçu l'Oscar de la meilleure actrice en 2013, pour « Happiness Therapy ».","c":"Cinéma & séries"},{"id":"16rpwb4w","t":"Qui a réalisé « Dracula », film français de 2025 inspiré du roman de Bram Stoker ?","r":["Mahamat Saleh Haroun","Jean-Paul Salomé","Cédric Klapisch","Luc Besson"],"b":3,"a":"Caleb Landry Jones y incarne le comte Dracula.","c":"Cinéma & séries"},{"id":"yp87b1kf","t":"Quel pionnier du cinéma, ancien illusionniste, a réalisé « Le Voyage dans la Lune » (1902) ?","r":["Louis Lumière","Charles Pathé","Émile Cohl","Georges Méliès"],"b":3,"a":"Il dirigeait le théâtre Robert-Houdin à Paris, et c'est de la magie qu'il tirait ses trucages.","c":"Cinéma & séries"},{"id":"447x0k7i","t":"Quel pouvoir possède Onze, la fillette de « Stranger Things » (2016) ?","r":["La télékinésie","L'invisibilité","La métamorphose","La super-vitesse"],"b":0,"a":"Son nom vient du chiffre 011 tatoué sur son poignet, souvenir du laboratoire où elle a grandi.","c":"Cinéma & séries"},{"id":"buwzbdal","t":"De quel pays vient la légende qui a inspiré « Mulan » (1998) ?","r":["Japon","Corée","Chine","Mongolie"],"b":2,"a":"Elle vient d'un très ancien poème chinois, « La Ballade de Mulan ».","c":"Cinéma & séries"},{"id":"qdd1hgum","t":"Dans « Les Trois Petits Cochons », qui menace de souffler pour faire s'envoler les maisons ?","r":["Le renard","L'ours","Le loup","Le tigre"],"b":2,"a":"Dans le conte, seule la maison de briques résiste au souffle du loup.","c":"Cinéma & séries"},{"id":"gv1s46j6","t":"Quel acteur prête ses traits à Obélix dans « Astérix et Obélix contre César » (1999) ?","r":["Christian Clavier","Gérard Depardieu","Gérard Jugnot","Michel Galabru"],"b":1,"a":"Christian Clavier y joue Astérix, et Roberto Benigni le traître Détritus.","c":"Cinéma & séries"},{"id":"e76ohm8a","t":"Quel acteur américain incarne l'agent J dans « Men in Black » (1997) ?","r":["Eddie Murphy","Jamie Foxx","Will Smith","Martin Lawrence"],"b":2,"a":"Will Smith a aussi chanté le tube qui accompagne le film.","c":"Cinéma & séries"},{"id":"6dic973v","t":"Quel personnage de « The Big Bang Theory » s'exclame « Bazinga ! » après avoir fait une blague ?","r":["Leonard Hofstadter","Howard Wolowitz","Sheldon Cooper","Raj Koothrappali"],"b":2,"a":"Sheldon utilise ce cri pour annoncer qu'il vient de faire une farce à son entourage, un humour que les autres ne comprennent pas toujours.","c":"Cinéma & séries"},{"id":"9wykkz3e","t":"Dans « La Soupe aux choux » (1981), qui vient rendre visite aux deux vieux paysans joués par Louis de Funès et Jean Carmet ?","r":["Un fantôme","Un chevalier du Moyen Âge","Un extraterrestre","Un robot"],"b":2,"a":"Le visiteur, surnommé La Denrée, est joué par Jacques Villeret. Le film est adapté d'un roman de René Fallet.","c":"Cinéma & séries"}],"moyen":[{"id":"yetaes99","t":"Dans « Harry Potter », quel sortilège impardonnable tue sur le coup ?","r":["Endoloris","Impero","Sectumsempra","Avada Kedavra"],"b":3,"a":"Il existe trois sortilèges impardonnables : le sortilège de la Mort, le Doloris et l'Imperium.","c":"Cinéma & séries"},{"id":"1i9mn2o7","t":"Quel acteur a reçu deux années de suite l'Oscar du meilleur acteur, en 1994 et en 1995 ?","r":["Tom Cruise","Denzel Washington","Al Pacino","Tom Hanks"],"b":3,"a":"Tom Hanks a été récompensé pour « Philadelphia » puis pour « Forrest Gump ». Spencer Tracy avait réussi le même doublé en 1938 et 1939.","c":"Cinéma & séries"},{"id":"8qnsd3ro","t":"Quel film de Ridley Scott a reçu l'Oscar du meilleur film lors de la cérémonie de 2001 ?","r":["Traffic","Gladiator","Erin Brockovich","Le Chocolat"],"b":1,"a":"Russell Crowe a reçu le même soir l'Oscar du meilleur acteur pour son rôle de Maximus.","c":"Cinéma & séries"},{"id":"keao8dm9","t":"Dans « Bob l'éponge », quel animal est Patrick, le meilleur ami du héros ?","r":["Un poulpe","Un oursin","Une méduse","Une étoile de mer"],"b":3,"a":"La série a été créée par Stephen Hillenburg, qui avait enseigné la biologie marine avant de se lancer dans l'animation.","c":"Cinéma & séries"},{"id":"7q0n2uuc","t":"Combien de marches compte l'escalier d'Odessa, rendu célèbre par « Le Cuirassé Potemkine » ?","r":["192","100","250","150"],"b":0,"a":"Eisenstein y a filmé une scène de massacre souvent reprise ensuite par d'autres cinéastes.","c":"Cinéma & séries"},{"id":"5t2nd5cj","t":"Sur quelle planète vivent les Gungans dans « La Menace fantôme » ?","r":["Coruscant","Naboo","Alderaan","Endor"],"b":1,"a":"Les Gungans habitent des cités sous-marines, tandis que les humains de la planète vivent sur la terre ferme.","c":"Cinéma & séries"},{"id":"8kjzbydz","t":"Dans la série allemande « Dark » (2017), tous les combien d'années le cycle des événements revient-il ?","r":["25 ans","33 ans","40 ans","50 ans"],"b":1,"a":"L'intrigue se déroule autour d'une grotte voisine d'une centrale nucléaire, dans la petite ville de Winden.","c":"Cinéma & séries"},{"id":"53wcz8xv","t":"Qui a réalisé le film « Into the Wild », adapté du livre de Jon Krakauer ?","r":["Sean Penn","Richard Linklater","Sam Raimi","Jay Roach"],"b":0,"a":"Le film suit Christopher McCandless, parti vivre seul en Alaska. La bande originale a été composée par Eddie Vedder.","c":"Cinéma & séries"},{"id":"aiyib7xa","t":"Dans « Le Roi lion » (1994), quel vieux babouin présente Simba nouveau-né aux animaux ?","r":["Zazu","Rafiki","Mufasa","Pumbaa"],"b":1,"a":"Le nom Rafiki veut dire « ami » en swahili, langue dont le film emprunte plusieurs noms.","c":"Cinéma & séries"},{"id":"5gmjqpcb","t":"Quel acteur joue le gangster vieillissant Max dans « Touchez pas au grisbi » (1954) ?","r":["Lino Ventura","Alain Delon","Jean Gabin","Fernandel"],"b":2,"a":"Lino Ventura y fait ses débuts d'acteur, dans un rôle de second plan.","c":"Cinéma & séries"},{"id":"8q3gjn7c","t":"Dans « Game of Thrones » (2011), quel surnom porte Sandor Clegane, le garde du corps balafré ?","r":["La Montagne","Le Régicide","Le Limier","Le Lutin"],"b":2,"a":"Sa brûlure au visage lui vient de son frère aîné Gregor, qui lui a enfoncé la tête dans un brasier quand il était enfant.","c":"Cinéma & séries"},{"id":"wpr2ggqs","t":"Quel âge, en années, a Jean Dujardin quand il reçoit l'Oscar du meilleur acteur en 2012 ?","r":["39 ans","45 ans","33 ans","51 ans"],"b":0,"a":"Jean Dujardin est le premier acteur français récompensé par l'Oscar du meilleur acteur.","c":"Cinéma & séries"},{"id":"3b3vwnhp","t":"Quel réalisateur italien a lancé le western spaghetti avec « Pour une poignée de dollars » (1964) ?","r":["Sergio Corbucci","Dario Argento","Sergio Leone","Bernardo Bertolucci"],"b":2,"a":"Le film s'inspire de « Yojimbo » de Kurosawa, ce qui a valu un procès à ses producteurs.","c":"Cinéma & séries"},{"id":"71pn45qh","t":"Quel acteur italien a reçu l'Oscar du meilleur acteur en 1999 pour « La vie est belle » ?","r":["Nanni Moretti","Marcello Mastroianni","Roberto Benigni","Giancarlo Giannini"],"b":2,"a":"Le film a aussi reçu l'Oscar du meilleur film étranger.","c":"Cinéma & séries"},{"id":"01lnhrui","t":"Quel pays africain est le berceau de l'industrie du film surnommée « Nollywood » ?","r":["Le Ghana","Le Kenya","Le Nigeria","L'Afrique du Sud"],"b":2,"a":"Nollywood tourne chaque année des centaines de films, souvent en quelques jours, directement pour la vidéo.","c":"Cinéma & séries"},{"id":"zvnldkcm","t":"Qui a réalisé « L'Auberge espagnole », comédie de 2002 sur des étudiants Erasmus à Barcelone ?","r":["Abderrahmane Sissako","Laurent Cantet","Cédric Klapisch","Mahamat Saleh Haroun"],"b":2,"a":"Le film a eu deux suites, « Les Poupées russes » en 2005 et « Casse-tête chinois » en 2013, avec les mêmes personnages principaux.","c":"Cinéma & séries"},{"id":"eprvpk5a","t":"Minas Tirith, la Cité blanche du « Retour du roi », est la capitale de quel royaume ?","r":["Rohan","Mordor","Gondor","Arnor"],"b":2,"a":"Minas Tirith signifie « la tour de garde » en sindarin, la langue elfique inventée par Tolkien.","c":"Cinéma & séries"},{"id":"rie2ixzw","t":"Qui a réalisé « Star Wars, épisode IV : Un nouvel espoir », sorti en 1977 ?","r":["Nicholas Meyer","Jonathan Demme","Steven Spielberg","George Lucas"],"b":3,"a":"À sa sortie, le film s'appelait simplement « Star Wars ». Alec Guinness y joue Obi-Wan Kenobi.","c":"Cinéma & séries"},{"id":"3jeyh26d","t":"Qui a réalisé « Les Aventures de Rabbi Jacob », comédie de 1973 avec Louis de Funès ?","r":["Éric Rohmer","Gérard Oury","Henri Verneuil","Alain Resnais"],"b":1,"a":"Louis de Funès y joue un industriel raciste contraint de se faire passer pour un rabbin.","c":"Cinéma & séries"},{"id":"ohkp4811","t":"Dans « La Belle et la Bête » (1991) de Disney, avant quel anniversaire la Bête doit-elle être aimée pour rompre le sort ?","r":["18 ans","30 ans","21 ans","25 ans"],"b":2,"a":"Le film s'inspire du conte publié par Jeanne-Marie Leprince de Beaumont en 1756.","c":"Cinéma & séries"},{"id":"a1e1oyz6","t":"Quel détective de fiction a inspiré le personnage du docteur House dans « Dr House » (2004) ?","r":["Hercule Poirot","Arsène Lupin","Sherlock Holmes","Le commissaire Maigret"],"b":2,"a":"Les clins d'œil abondent : House habite au numéro 221B, et son ami s'appelle Wilson, comme un écho à Watson.","c":"Cinéma & séries"},{"id":"1r80xdx2","t":"Comment s'appellent les grands marcheurs blindés à quatre pattes de l'Empire à l'assaut de la base rebelle de Hoth ?","r":["AT-AT","AT-ST","TIE","X-34"],"b":0,"a":"Leur démarche était animée en image par image, avec de petites maquettes articulées.","c":"Cinéma & séries"},{"id":"asn9eb4b","t":"Quel personnage de « Breaking Bad » affirme « Je suis le danger » ?","r":["Jesse Pinkman","Walter White","Gus Fring","Hank Schrader"],"b":1,"a":"Le professeur de chimie Walter White prononce ce discours devant sa femme, qui s'inquiète pour sa sécurité.","c":"Cinéma & séries"},{"id":"2airiuk1","t":"Qui a réalisé « Manon des sources », adaptation de Marcel Pagnol sortie en 1986 ?","r":["Claude Zidi","Claude Berri","Med Hondo","Jean Becker"],"b":1,"a":"Le film est la seconde partie d'un diptyque : il fait suite à « Jean de Florette », et les deux films sont tirés du roman « L'Eau des collines » de Marcel Pagnol.","c":"Cinéma & séries"}],"difficile":[{"id":"89le8ztw","t":"Qui a réalisé le film « Polisse », sorti en 2011 et consacré à une brigade de protection des mineurs ?","r":["Xavier Gens","Quentin Dupieux","Mikhaël Hers","Maïwenn"],"b":3,"a":"Le film a reçu le Prix du jury au Festival de Cannes 2011. La réalisatrice y joue aussi le rôle d'une photographe.","c":"Cinéma & séries"},{"id":"ird5rs08","t":"Qui a créé la série policière américaine « New York, unité spéciale », lancée en 1999 ?","r":["Steven Spielberg","Dick Wolf","Stephen King","Huell Howser"],"b":1,"a":"Mariska Hargitay y joue le rôle d'Olivia Benson depuis les débuts de la série.","c":"Cinéma & séries"},{"id":"i2hhryj6","t":"Dans quel film de 1960 Anthony Perkins affirme-t-il que « le meilleur ami d'un garçon, c'est sa mère » ?","r":["Sueurs froides","Les Oiseaux","La Mort aux trousses","Psychose"],"b":3,"a":"Hitchcock fit racheter le plus d'exemplaires possible du roman de Robert Bloch pour que le public ignore l'intrigue avant la sortie.","c":"Cinéma & séries"},{"id":"4i24wa9m","t":"Quelle actrice française a reçu l'Oscar de la meilleure actrice en 1960 pour « Les Chemins de la haute ville » ?","r":["Brigitte Bardot","Simone Signoret","Jeanne Moreau","Michèle Morgan"],"b":1,"a":"Elle a reçu ce prix pour un film britannique, adapté d'un roman de John Braine.","c":"Cinéma & séries"},{"id":"adgymeeo","t":"Quel réalisateur mexicain a reçu l'Oscar du meilleur réalisateur en 2014 pour « Gravity » ?","r":["Alejandro González Iñárritu","Guillermo del Toro","Steve McQueen","Alfonso Cuarón"],"b":3,"a":"Il en a reçu un second en 2019, pour « Roma ».","c":"Cinéma & séries"},{"id":"0q6bp3ex","t":"Qui a réalisé le film « Le Marginal », polar sorti en 1983 avec Jean-Paul Belmondo ?","r":["Édouard Molinaro","Pierre Schoendoerffer","Serge Bourguignon","Jacques Deray"],"b":3,"a":"Belmondo y joue un commissaire marseillais muté à Paris, où il traque un gros trafiquant de drogue.","c":"Cinéma & séries"},{"id":"5og06nex","t":"Dans « Citizen Kane » (1941), quel mot le magnat murmure-t-il juste avant de mourir, au début du film ?","r":["Xanadu","Rosebud","Susan","Charlie"],"b":1,"a":"« Citizen Kane » est le premier long métrage d'Orson Welles, qui l'a réalisé à vingt-cinq ans et y tient le rôle principal.","c":"Cinéma & séries"},{"id":"hvko2di2","t":"Qui a réalisé le film « Hunger Games : L'Embrasement », sorti en 2013 ?","r":["Kevin Smith","Francis Lawrence","Patty Jenkins","Todd Phillips"],"b":1,"a":"Jennifer Lawrence y reprend le rôle de Katniss Everdeen, dans le deuxième volet de la saga.","c":"Cinéma & séries"},{"id":"fiykm5k7","t":"Quel acteur néo-zélandais incarne Éomer, le neveu du roi Théoden, dans « Les Deux Tours » ?","r":["Bernard Hill","Karl Urban","Craig Parker","Cliff Curtis"],"b":1,"a":"Le même acteur a ensuite joué le médecin McCoy dans les films « Star Trek » à partir de 2009.","c":"Cinéma & séries"},{"id":"m8745a40","t":"Quel film allemand de Volker Schlöndorff a partagé la Palme d'or 1979 avec « Apocalypse Now » ?","r":["Das Boot","Les Ailes du désir","Le Tambour","Fitzcarraldo"],"b":2,"a":"Adapté du roman de Günter Grass, il a aussi reçu l'Oscar du meilleur film en langue étrangère.","c":"Cinéma & séries"},{"id":"lqbdafdf","t":"Qui a réalisé le film « Des hommes et des dieux », sorti en 2010 sur des moines en Algérie ?","r":["Stéphane Brizé","Xavier Beauvois","Jean-François Richet","Michel Hazanavicius"],"b":1,"a":"Le film a reçu le Grand Prix du Festival de Cannes 2010. Il s'inspire de l'histoire des moines de Tibhirine, enlevés en 1996.","c":"Cinéma & séries"},{"id":"m7gq1v47","t":"Dans « La Guerre des étoiles » (1977), quel personnage étrangle un officier à distance en lui reprochant son « manque de foi » ?","r":["L'Empereur","Grand Moff Tarkin","Dark Vador","Le comte Dooku"],"b":2,"a":"Dark Vador est joué physiquement par David Prowse, mais sa voix originale est celle de James Earl Jones.","c":"Cinéma & séries"},{"id":"v1ui6cod","t":"Dans « La Femme du boulanger » (1938), comment s'appelle la chatte que Raimu sermonne pour avoir quitté le foyer ?","r":["Minette","Mistigri","Pomponnette","Fanchette"],"b":2,"a":"Le film de Marcel Pagnol est tiré d'une nouvelle de Jean Giono, « Jean le Bleu ».","c":"Cinéma & séries"},{"id":"1yyibc9f","t":"Quel acteur britannique incarne Voldemort dans les films « Harry Potter » ?","r":["Jason Isaacs","Ralph Fiennes","Gary Oldman","Jude Law"],"b":1,"a":"Il revêt pour la première fois l'apparence du mage noir dans « Harry Potter et la Coupe de feu » (2005).","c":"Cinéma & séries"},{"id":"8ibyh5sx","t":"Dans quelle série américaine, en 1980, le monde entier se demande-t-il « Qui a tiré sur J.R. ? »","r":["Dynastie","Dallas","Falcon Crest","Magnum"],"b":1,"a":"La réponse n'a été révélée qu'en novembre 1980, des mois après le cliffhanger de mars.","c":"Cinéma & séries"},{"id":"0mwl01mw","t":"Quel général cyborg, qui tousse et manie plusieurs sabres lasers, dirige l'armée droïde dans « La Revanche des Sith » ?","r":["Dooku","Grievous","Sidious","Tarkin"],"b":1,"a":"Le personnage est entièrement numérique ; en version originale, il est doublé par Matthew Wood.","c":"Cinéma & séries"},{"id":"m7palqvs","t":"Quel acteur danois incarne Le Chiffre, l'adversaire de James Bond dans « Casino Royale » (2006) ?","r":["Nikolaj Coster-Waldau","Ulrich Thomsen","Claes Bang","Mads Mikkelsen"],"b":3,"a":"Le Chiffre, banquier du terrorisme, pleure des larmes de sang à cause d'une malformation d'une glande lacrymale.","c":"Cinéma & séries"},{"id":"hn5cxvjp","t":"En quelle année la série britannique « Doctor Who » a-t-elle été diffusée pour la première fois ?","r":["1958","1963","1968","1973"],"b":1,"a":"Le Docteur peut se régénérer, ce qui a permis à de nombreux acteurs d'incarner le rôle au fil des décennies.","c":"Cinéma & séries"},{"id":"vxe3impt","t":"Dans quel film des Monty Python (1975) des chevaliers qui disent « Ni ! » exigent-ils un buisson ?","r":["La Vie de Brian","Bandits, bandits","Le Sens de la vie","Sacré Graal"],"b":3,"a":"Faute de budget, les chevaliers marchent sans cheval, et un bruit de noix de coco imite le galop.","c":"Cinéma & séries"},{"id":"dcimeqa7","t":"Dans « Les Tontons flingueurs » (1963), quel acteur joue Raoul Volfoni ?","r":["Jean Lefebvre","Francis Blanche","Bernard Blier","Robert Dalban"],"b":2,"a":"Bernard Blier est le père du réalisateur Bertrand Blier, à qui l'on doit « Les Valseuses ».","c":"Cinéma & séries"}]},"Musique":{"facile":[{"id":"sceetcs3","t":"Quel oiseau a donné son nom de scène à Édith Piaf ?","r":["Le rossignol","Le merle","Le moineau","La mésange"],"b":2,"a":"C'est Louis Leplée, patron de cabaret, qui l'a baptisée « la Môme Piaf » en 1935, après l'avoir entendue chanter dans la rue.","c":"Musique"},{"id":"9izbbyoh","t":"Dans quel film Pixar de 1995 entend-on la chanson « Je suis ton ami » ?","r":["Monstres et Cie","Toy Story","Le Monde de Nemo","1001 pattes"],"b":1,"a":"La chanson est de Randy Newman. Toy Story est le premier long métrage entièrement réalisé en images de synthèse.","c":"Musique"},{"id":"lxtx5a91","t":"De quelle région la bourrée, danse à pas sautés, est-elle emblématique ?","r":["La Bretagne","L'Auvergne","L'Alsace","La Normandie"],"b":1,"a":"Danse du Massif central, la bourrée est aussi entrée dans les suites baroques, notamment celles de Bach.","c":"Musique"},{"id":"8zr409n6","t":"Combien de cordes compte un violoncelle ?","r":["3","4","5","6"],"b":1,"a":"Ses cordes sont accordées en quintes, une octave sous celles de l'alto : do, sol, ré, la.","c":"Musique"},{"id":"31tatx8w","t":"Quel chanteur américain, célèbre pour ses glissés et ses cris sur scène, est surnommé « le Parrain de la soul » ?","r":["Ray Charles","Otis Redding","James Brown","Marvin Gaye"],"b":2,"a":"On l'appelait aussi « Mister Dynamite » et « l'homme qui travaille le plus dur du show-business ».","c":"Musique"},{"id":"ndf1dvr1","t":"Quel instrument de la famille des bois, à anche simple, a un long tube droit de couleur noire ?","r":["Hautbois","Basson","Flûte traversière","Clarinette"],"b":3,"a":"Son nom vient de l'italien clarino, la petite trompette dont elle imitait le timbre aigu.","c":"Musique"},{"id":"y47dhgbk","t":"Dans un opéra, comment appelle-t-on le morceau chanté par un seul personnage, souvent le plus attendu ?","r":["Un chœur","Un récitatif","Un duo","Un air"],"b":3,"a":"Le récitatif, à mi-chemin entre parole et chant, fait avancer l'action entre les airs, qui expriment les sentiments.","c":"Musique"},{"id":"dkuuk5rk","t":"Quelle partie du corps est la plus sollicitée dans le waacking, aux amples mouvements circulaires ?","r":["Les bras","Les jambes","La tête","Les épaules"],"b":0,"a":"Le style s'inspire des poses des stars de l'ancien cinéma hollywoodien.","c":"Musique"},{"id":"38w06i2y","t":"Quel groupe britannique a chanté « Yellow Submarine » en 1966 ?","r":["The Rolling Stones","The Who","The Beatles","The Kinks"],"b":2,"a":"Ringo Starr en est le chanteur principal, et la chanson a donné son titre à un film d'animation de 1968.","c":"Musique"},{"id":"a5q0t7nx","t":"Combien de notes de noms différents compte la gamme de do majeur, avant que la suite ne recommence à l'octave ?","r":["5","6","7","8"],"b":2,"a":"Le mot « octave » vient du latin pour « huitième » : la huitième note reprend le nom de la première.","c":"Musique"},{"id":"r82t0ube","t":"Comment s'appelle le grand ensemble de musiciens dirigé par un chef, avec violons, cuivres et percussions ?","r":["Une chorale","Une fanfare","Un orchestre","Un duo"],"b":2,"a":"Dans la Grèce antique, l'orchestra était l'espace devant la scène où dansait et chantait le chœur.","c":"Musique"},{"id":"ravy2710","t":"Quelle héroïne Disney chante « Le Bleu Lumière » en rêvant de prendre la mer ?","r":["Raiponce","Pocahontas","Mulan","Vaiana"],"b":3,"a":"Les chansons du film ont été coécrites par Lin-Manuel Miranda, le créateur de la comédie musicale « Hamilton ».","c":"Musique"},{"id":"eq1sltdy","t":"Quelle chanteuse a popularisé le voguing auprès du grand public avec un tube en 1990 ?","r":["Whitney Houston","Janet Jackson","Cher","Madonna"],"b":3,"a":"Le clip de Vogue imite les poses des mannequins des magazines de mode, comme les danseurs des bals de Harlem.","c":"Musique"},{"id":"ydwd81em","t":"De quel pays était le guitariste de flamenco Paco de Lucía ?","r":["Mexique","Espagne","Portugal","Argentine"],"b":1,"a":"Né à Algésiras, Paco de Lucía a connu le succès en 1973 avec la rumba « Entre dos aguas ».","c":"Musique"},{"id":"g0vzkchx","t":"Quel chanteur irlandais est la voix du groupe U2 ?","r":["Sting","Bono","Bob Geldof","Van Morrison"],"b":1,"a":"Bono s'appelle en réalité Paul Hewson ; son surnom viendrait d'un magasin d'appareils auditifs de Dublin.","c":"Musique"},{"id":"ljy7wxjw","t":"Quel chanteur américain a sorti le single « Billie Jean » en 1983 ?","r":["Michael Jackson","Prince","Lionel Richie","Stevie Wonder"],"b":0,"a":"Le clip de « Billie Jean », avec son trottoir qui s'illumine sous les pas, compte parmi les premiers clips d'artistes noirs diffusés en boucle sur MTV.","c":"Musique"},{"id":"qkauf2i5","t":"Dans quel pays est née la danse classique kathak, aux clochettes de chevilles ?","r":["L'Inde","Le Pakistan","Le Népal","Le Sri Lanka"],"b":0,"a":"Ses danseurs portent des clochettes aux chevilles, les ghungroo, qui soulignent le rythme des pieds.","c":"Musique"},{"id":"k6tmemjp","t":"Quel rappeur a sorti « Without Me » en 2002 ?","r":["Eminem","50 Cent","Nelly","Ludacris"],"b":0,"a":"Le clip parodie des personnages de films et de bandes dessinées.","c":"Musique"},{"id":"h4ys0vqd","t":"Comment appelle-t-on une personne qui joue du piano ?","r":["Pianotiste","Pianiste","Pianeur","Pianier"],"b":1,"a":"Le suffixe -iste sert à nommer de nombreux musiciens : guitariste, violoniste, flûtiste ou harpiste.","c":"Musique"},{"id":"mr2495vz","t":"Qui était le batteur des Beatles au moment de leur succès mondial ?","r":["John Lennon","Ringo Starr","George Harrison","Brian Epstein"],"b":1,"a":"De son vrai nom Richard Starkey, il a rejoint le groupe en 1962.","c":"Musique"},{"id":"gf5aum2d","t":"Pour combien de dollars l'unique exemplaire de l'album « Once Upon a Time in Shaolin » du Wu-Tang Clan a-t-il été vendu en 2015 ?","r":["200 000 $","800 000 $","2 000 000 $","10 000 000 $"],"b":2,"a":"Le Wu-Tang Clan n'a pressé qu'un seul exemplaire de cet album, livré dans un coffret en argent ciselé.","c":"Musique"},{"id":"s3novmqp","t":"Que désigne le « B » de Bollywood, industrie du cinéma indien célèbre pour ses scènes dansées ?","r":["Bangalore","Bombay","Bengale","Baroda"],"b":1,"a":"Le mot mêle Bombay et Hollywood ; Bombay s'appelle aujourd'hui Mumbai.","c":"Musique"},{"id":"d1oi6lsr","t":"Dans quel pays la samba est-elle née ?","r":["Argentine","Portugal","Cuba","Brésil"],"b":3,"a":"La samba s'est formée à Rio de Janeiro et à Bahia, puis est devenue l'âme du carnaval.","c":"Musique"},{"id":"k78nhmi5","t":"Avec le rap, le graffiti et le breaking, quel art des platines est l'un des quatre piliers du hip-hop ?","r":["Le beatmaking","Le deejaying","Le scratching","Le sampling"],"b":1,"a":"Avec deux platines, le DJ peut passer d'un disque à l'autre sans jamais interrompre la danse.","c":"Musique"}],"moyen":[{"id":"vni7hl55","t":"Quel jazzman a chanté « Hello, Dolly! », numéro un des ventes aux États-Unis en 1964 ?","r":["Frank Sinatra","Nat King Cole","Ray Charles","Louis Armstrong"],"b":3,"a":"En mai 1964, ce disque a délogé les Beatles de la première place du classement américain, en pleine Beatlemania.","c":"Musique"},{"id":"k5icoapx","t":"Quel rappeur a sorti l'album « Illmatic » en 1994 ?","r":["Nas","Rakim","KRS-One","Method Man"],"b":0,"a":"Nas a grandi dans les Queensbridge Houses, cité du Queens qu'il évoque dans ses textes.","c":"Musique"},{"id":"99vjcizu","t":"La mazurka créole des Antilles descend d'une danse de salon originaire de quel pays ?","r":["Hongrie","Pologne","Russie","Autriche"],"b":1,"a":"Arrivée aux Antilles au XIXe siècle par les salons, la mazurka est devenue créole en s'enrichissant de rythmes locaux.","c":"Musique"},{"id":"sozxmeop","t":"Dans quel pays est né le kuduro, danse énergique aux mouvements saccadés ?","r":["Au Mozambique","Au Cap-Vert","Au Brésil","En Angola"],"b":3,"a":"Le kuduro est apparu à Luanda dans les années 1990, mêlant rythmes électroniques et traditions angolaises.","c":"Musique"},{"id":"js2y9dxo","t":"Quel pianiste canadien a enregistré les « Variations Goldberg » de Bach en 1955, disque qui l'a rendu célèbre ?","r":["Vladimir Horowitz","Arthur Rubinstein","Sviatoslav Richter","Glenn Gould"],"b":3,"a":"Il les a réenregistrées en 1981, peu avant sa mort, dans une version bien plus lente.","c":"Musique"},{"id":"mcddbg55","t":"Quelle chanteuse de R&B a sorti « Fallin' » en 2001 ?","r":["Mary J. Blige","Alicia Keys","Aaliyah","Ashanti"],"b":1,"a":"Le titre figure sur « Songs in A Minor », premier album de la chanteuse, pianiste de formation classique.","c":"Musique"},{"id":"4yxxt63r","t":"Quel compositeur argentin a révolutionné le tango en y mêlant jazz et musique classique, créant le « tango nuevo » ?","r":["Carlos Gardel","Juan de Dios Filiberto","Astor Piazzolla","Aníbal Troilo"],"b":2,"a":"Ses audaces lui ont valu des critiques à Buenos Aires, où certains puristes refusaient de voir dans sa musique un vrai tango.","c":"Musique"},{"id":"35bewqcr","t":"Quel rappeur français est surnommé « le Duc de Boulogne » ?","r":["Kaaris","Rohff","Booba","Kery James"],"b":2,"a":"Né Élie Yaffa, il a débuté dans le duo Lunatic.","c":"Musique"},{"id":"amew4vzn","t":"Que demande l'indication italienne « presto » sur une partition ?","r":["Jouer très doucement","Jouer très vite","Jouer en ralentissant","Jouer modérément"],"b":1,"a":"Encore plus rapide que presto, l'indication « prestissimo » demande le tempo le plus vif de la musique classique.","c":"Musique"},{"id":"r9s9nsdu","t":"Quel slameur a sorti l'album « Midi 20 » en 2006 ?","r":["Abd al Malik","Oxmo Puccino","MC Solaar","Grand Corps Malade"],"b":3,"a":"Son nom de scène fait allusion à sa grande taille et aux séquelles d'un grave accident de plongeon survenu dans sa jeunesse.","c":"Musique"},{"id":"kc5eedae","t":"De quel pays vient le groupe de metal Rammstein ?","r":["Autriche","Suède","Norvège","Allemagne"],"b":3,"a":"Son nom évoque la base aérienne de Ramstein, où un accident de meeting aérien fit de nombreuses victimes en 1988.","c":"Musique"},{"id":"kfzdwksx","t":"Quel chanteur Joaquin Phoenix incarne-t-il dans « Walk the Line », sorti en 2005 ?","r":["Elvis Presley","Johnny Cash","Roy Orbison","Jerry Lee Lewis"],"b":1,"a":"Reese Witherspoon, qui y joue June Carter, a reçu l'Oscar de la meilleure actrice pour ce rôle.","c":"Musique"},{"id":"q5buj0yu","t":"Quel compositeur norvégien a écrit la musique de scène de « Peer Gynt », la pièce d'Ibsen ?","r":["Johan Svendsen","Edvard Grieg","Christian Sinding","Carl Nielsen"],"b":1,"a":"La pièce a été créée en 1876 à Christiania, l'actuelle Oslo ; Grieg en a tiré deux suites d'orchestre.","c":"Musique"},{"id":"yhmpsn9h","t":"Quel duo a sorti le tube « Crazy » en 2006 ?","r":["The Black Eyed Peas","OutKast","Gnarls Barkley","The Neptunes"],"b":2,"a":"Au Royaume-Uni, « Crazy » a été le premier titre classé numéro un grâce aux seuls téléchargements.","c":"Musique"},{"id":"b0sqa4n8","t":"Quel chanteur a sorti « La Corrida » en 1994 ?","r":["Francis Cabrel","Jean-Jacques Goldman","Michel Jonasz","Maxime Le Forestier"],"b":0,"a":"La chanson est racontée du point de vue du taureau, ce qui en fait un plaidoyer contre la corrida.","c":"Musique"},{"id":"ugematww","t":"Quel batteur de Led Zeppelin est mort en 1980 ?","r":["Keith Moon","Ginger Baker","John Bonham","Charlie Watts"],"b":2,"a":"Après sa mort, les trois autres membres ont préféré dissoudre le groupe plutôt que de le remplacer.","c":"Musique"},{"id":"azaflmpd","t":"Quel orchestre britannique a enregistré la musique de « La Guerre des étoiles » (1977) ?","r":["Le London Symphony Orchestra","Le Royal Philharmonic Orchestra","Le Philharmonia Orchestra","Le BBC Symphony Orchestra"],"b":0,"a":"La partition de John Williams a reçu l'Oscar de la meilleure musique de film en 1978.","c":"Musique"},{"id":"46cs11bv","t":"Quel rappeur a sorti l'album « The College Dropout » en 2004 ?","r":["Common","Lupe Fiasco","Kanye West","Nelly"],"b":2,"a":"Il y raconte son abandon des études et y place le titre « Jesus Walks ».","c":"Musique"},{"id":"g3ymjn9d","t":"Quel guitariste congolais, surnommé « le sorcier de la guitare », a dirigé l'orchestre OK Jazz ?","r":["Papa Wemba","Tabu Ley Rochereau","Franco","Grand Kallé"],"b":2,"a":"L'orchestre fut fondé en 1956 et Franco en resta le chef jusqu'à sa mort en 1989.","c":"Musique"},{"id":"bp7l66vz","t":"Quelle chanteuse est surnommée « la reine du disco » ?","r":["Gloria Gaynor","Diana Ross","Chaka Khan","Donna Summer"],"b":3,"a":"Son titre « I Feel Love » (1977), produit par Giorgio Moroder, a ouvert la voie à la musique électronique de danse.","c":"Musique"},{"id":"p7rvcymj","t":"Qui a composé la musique de « Sinners », film américain de Ryan Coogler sorti en 2025 ?","r":["Jon Ekstrand","Ludwig Göransson","Joseph Trapanese","Justin Hurwitz"],"b":1,"a":"Le film mêle vampires et blues dans le Mississippi des années 1930, avec Michael B. Jordan dans un double rôle.","c":"Musique"},{"id":"cqcrpp8t","t":"Quelle symphonie de Beethoven s'achève sur un chœur chantant l'« Ode à la joie » ?","r":["La Cinquième","La Sixième","La Septième","La Neuvième"],"b":3,"a":"Le texte est un poème de Friedrich Schiller ; la mélodie est devenue l'hymne de l'Union européenne.","c":"Musique"},{"id":"r5wdk8mi","t":"Quel groupe de Los Angeles a sorti « Insane in the Brain » en 1993 ?","r":["House of Pain","Public Enemy","Cypress Hill","Beastie Boys"],"b":2,"a":"Le groupe compte notamment les rappeurs B-Real et Sen Dog.","c":"Musique"},{"id":"ov2wfp8s","t":"De quel pays est originaire Rubén Blades, auteur de « Pedro Navaja » ?","r":["Cuba","Panama","Porto Rico","Colombie"],"b":1,"a":"Chanteur et avocat, il a donné à la salsa des textes sociaux dans les années 1970.","c":"Musique"}],"difficile":[{"id":"7htm0ofs","t":"Quel groupe français a sorti l'album « Tostaky » en 1992 ?","r":["Noir Désir","Les Négresses Vertes","Louise Attaque","Mano Negra"],"b":0,"a":"Le groupe bordelais mené par Bertrand Cantat a ensuite connu un grand succès avec « Le vent l'emportera ».","c":"Musique"},{"id":"bfhc220i","t":"Quel compositeur a écrit l'opéra « Pelléas et Mélisande », créé en 1902 ?","r":["Maurice Ravel","Gabriel Fauré","Claude Debussy","Jules Massenet"],"b":2,"a":"C'est le seul opéra achevé de son auteur, tiré d'une pièce de Maurice Maeterlinck.","c":"Musique"},{"id":"hqmltala","t":"Qui a composé la musique du film « Princess Bride », de Rob Reiner, sorti en 1987 ?","r":["Mark Knopfler","Peter Gabriel","Andrew Lloyd Webber","Brian Eno"],"b":0,"a":"Le film est adapté d'un roman de William Goldman, qui en a aussi écrit le scénario.","c":"Musique"},{"id":"um5988xc","t":"Qui a composé l'opéra « Manon », d'après le roman de l'abbé Prévost, créé en 1884 ?","r":["Georges Bizet","Giacomo Puccini","Richard Strauss","Jules Massenet"],"b":3,"a":"Le livret adapte « Manon Lescaut » de l'abbé Prévost, que Puccini mettra lui aussi en musique quelques années plus tard.","c":"Musique"},{"id":"9e9mfsey","t":"Qui a écrit les paroles de « Retiens la nuit », succès de Johnny Hallyday en 1962 ?","r":["Jean-Jacques Debout","Pierre Delanoë","Eddy Mitchell","Charles Aznavour"],"b":3,"a":"Georges Garvarentz, d'origine arménienne comme lui, en a composé la musique.","c":"Musique"},{"id":"5tpod6gx","t":"Quel chef d'orchestre cubain a fondé à New York en 1940 les Afro-Cubans, pionniers du jazz latin ?","r":["Tito Puente","Xavier Cugat","Pérez Prado","Machito"],"b":3,"a":"Son orchestre a mêlé rythmes cubains et jazz bien avant l'essor de la salsa.","c":"Musique"},{"id":"6y2xy1mz","t":"Comment appelle-t-on la voix de femme la plus grave en chant lyrique ?","r":["Mezzo-soprano","Contralto","Soprano","Baryton"],"b":1,"a":"La Britannique Kathleen Ferrier fut l'une des contraltos les plus admirées du XXe siècle.","c":"Musique"},{"id":"kvjgz7gg","t":"Quel chanteur a sorti l'album « Osez Joséphine » en 1991 ?","r":["Alain Bashung","Jacques Higelin","Alain Souchon","Dominique A"],"b":0,"a":"Les textes sont de Jean Fauque, parolier fidèle du chanteur.","c":"Musique"},{"id":"prpe3rgu","t":"De quelle chanson des Animals « Le Pénitencier », de Johnny Hallyday, est-elle l'adaptation ?","r":["Hey Joe","Gloria","The House of the Rising Sun","Baby, Please Don't Go"],"b":2,"a":"« Le Pénitencier » est sorti en 1964, et reste l'un des grands succès de Johnny Hallyday.","c":"Musique"},{"id":"sch5jvpc","t":"Quel genre jamaïcain, né du remixage de morceaux de reggae, ajoute écho et réverbération aux pistes instrumentales ?","r":["Ska","Dub","Dancehall","Rocksteady"],"b":1,"a":"Des ingénieurs du son comme King Tubby et Lee « Scratch » Perry en ont fait un art à part entière.","c":"Musique"},{"id":"qq0tslro","t":"Dans quelle ville allemande le groupe Kraftwerk a-t-il été fondé ?","r":["Berlin","Munich","Hambourg","Düsseldorf"],"b":3,"a":"Le groupe y avait son studio, le Kling Klang, où il a enregistré ses albums les plus marquants.","c":"Musique"},{"id":"p6fou1c7","t":"Quels frères ont écrit les chansons de « Mary Poppins », sorti en 1964 ?","r":["Les frères Gershwin","Les frères Sherman","Les frères Warner","Les frères Gibb"],"b":1,"a":"Robert et Richard Sherman ont reçu deux Oscars pour ce film, dont celui de la meilleure chanson pour « Chem Cheminée ».","c":"Musique"},{"id":"jslzxski","t":"Quel rappeur a sorti en 1996 son premier album, « Reasonable Doubt » ?","r":["Nas","Jay-Z","Method Man","Ghostface Killah"],"b":1,"a":"Il est sorti sur Roc-A-Fella Records, le label que l'artiste avait cofondé.","c":"Musique"},{"id":"bqsxt07c","t":"Quelle chanteuse a sorti « Résiste » en 1981 ?","r":["Véronique Sanson","Jeanne Mas","France Gall","Sheila"],"b":2,"a":"La chanson figure sur l'album « Tout pour la musique », écrit et composé par Michel Berger.","c":"Musique"},{"id":"ppaj8lla","t":"Qui a composé « La Damnation de Faust », légende dramatique d'après Goethe, créée en 1846 ?","r":["Vincenzo Bellini","Hector Berlioz","Daniel-François-Esprit Auber","Mikhaïl Glinka"],"b":1,"a":"Le compositeur a utilisé la traduction française du « Faust » de Goethe par Gérard de Nerval. La création, à l'Opéra-Comique, fut un échec.","c":"Musique"},{"id":"jwfst0m7","t":"Dans « Pierre et le Loup » de Prokofiev, quel instrument représente le chat ?","r":["La flûte","Le hautbois","La clarinette","Le basson"],"b":2,"a":"Prokofiev a écrit ce conte musical en 1936 pour faire découvrir aux enfants les instruments de l'orchestre.","c":"Musique"},{"id":"z36yaypn","t":"Quel DJ canadien a sorti « Strobe » en 2009 ?","r":["Skrillex","deadmau5","Tiësto","Carl Cox"],"b":1,"a":"Il se produit coiffé d'un casque en forme de tête de souris.","c":"Musique"},{"id":"6uyob05c","t":"Comment s'appelle la pédale de droite du piano, qui laisse les cordes résonner après qu'on a lâché les touches ?","r":["La pédale douce","La pédale forte","La pédale tonale","La pédale de sourdine"],"b":1,"a":"Cette pédale soulève tous les étouffoirs d'un coup : les cordes vibrent librement et se répondent.","c":"Musique"},{"id":"pthkjbn8","t":"Quel pianiste new-yorkais d'origine portoricaine a fondé l'orchestre La Perfecta ?","r":["Larry Harlow","Eddie Palmieri","Charlie Palmieri","Papo Lucca"],"b":1,"a":"Son orchestre mêlait trombones et flûte dans un son nouveau, resté célèbre.","c":"Musique"},{"id":"lj165h5f","t":"Comment s'appelle, en français, la paire de cymbales de la batterie actionnée par une pédale ?","r":["Le ride","Le crash","Le charleston","Le tom basse"],"b":2,"a":"Son nom vient de la danse à la mode dans les années 1920 : le charleston, qu'on dansait au rythme du jazz.","c":"Musique"}]},"Arts & lettres":{"facile":[{"id":"z5kebqkd","t":"Quel dessinateur belge a créé Gaston Lagaffe, le gaffeur de la rédaction ?","r":["Peyo","Roba","Franquin","Jijé"],"b":2,"a":"Gaston apparaît en 1957 dans le journal Spirou.","c":"Arts & lettres"},{"id":"1wf02mg1","t":"Comment nomme-t-on une strophe de quatre vers ?","r":["Un tercet","Un distique","Un sizain","Un quatrain"],"b":3,"a":"Un sonnet associe deux strophes de ce type à deux strophes de trois vers.","c":"Arts & lettres"},{"id":"qk2i146q","t":"Comment appelle-t-on la branche de la philosophie qui réfléchit au bien et au mal ?","r":["La logique","L'esthétique","La métaphysique","L'éthique"],"b":3,"a":"Le mot vient du grec êthos, « manière d'être, caractère » ; la morale, son équivalent latin, vient de mores, « les mœurs ».","c":"Arts & lettres"},{"id":"a4gsnbfu","t":"Quel peintre catalan est célèbre pour ses moustaches fines et recourbées vers le haut ?","r":["Pablo Picasso","Joan Miró","Salvador Dalí","Diego Velázquez"],"b":2,"a":"Dalí s'est installé à Figueras, sa ville natale, où il a lui-même conçu un théâtre-musée dans lequel il est enterré.","c":"Arts & lettres"},{"id":"1wq68plo","t":"Dans quelle pièce de Shakespeare trouve-t-on la célèbre scène du balcon ?","r":["Roméo et Juliette","Othello","Le Songe d'une nuit d'été","La Nuit des rois"],"b":0,"a":"Le texte de Shakespeare ne parle jamais de balcon : il évoque seulement une fenêtre en hauteur, et le balcon est venu des mises en scène.","c":"Arts & lettres"},{"id":"ht61hczs","t":"Sous quelle forme Platon a-t-il rédigé presque toutes ses œuvres de philosophie ?","r":["Des traités","Des lettres","Des dialogues","Des fables"],"b":2,"a":"Socrate, personnage principal de la plupart de ces dialogues, n'a lui-même rien écrit.","c":"Arts & lettres"},{"id":"3qh009o2","t":"Dans quelle pièce de Shakespeare trouve-t-on le personnage d'Ophélie ?","r":["Macbeth","Othello","Hamlet","Le Roi Lear"],"b":2,"a":"Hamlet est la plus longue pièce de Shakespeare.","c":"Arts & lettres"},{"id":"w738akf0","t":"Comment nomme-t-on un toit plat et accessible, aménagé pour qu'on puisse s'y tenir ?","r":["Toit-terrasse","Toit en croupe","Toit en appentis","Toit en pavillon"],"b":0,"a":"Le Corbusier en a fait l'un de ses « cinq points de l'architecture moderne », avec les pilotis et la fenêtre en longueur.","c":"Arts & lettres"},{"id":"d435necs","t":"Comment appelle-t-on le béton renforcé par des barres d'acier noyées dans sa masse ?","r":["Béton ciré","Béton cellulaire","Béton désactivé","Béton armé"],"b":3,"a":"Le jardinier français Joseph Monier a déposé en 1867 un brevet pour des bacs à fleurs en ciment renforcé de fer.","c":"Arts & lettres"},{"id":"7fmotzxs","t":"De quelle couleur sont les cheveux de Tintin ?","r":["Bruns","Roux","Blonds","Noirs"],"b":1,"a":"Sa célèbre houppe se dresse pour la première fois dans Tintin au pays des Soviets, quand une voiture démarre en trombe.","c":"Arts & lettres"},{"id":"oqwd6m7x","t":"Quel roman, paru en 1832, est le premier à être signé du pseudonyme de George Sand ?","r":["Lélia","Indiana","Consuelo","Mauprat"],"b":1,"a":"Aurore Dupin avait d'abord signé J. Sand un roman écrit à deux mains avec Jules Sandeau ; elle garde ensuite le prénom George.","c":"Arts & lettres"},{"id":"g8xgro0a","t":"Quel animal, doté d'une tête humaine, le Grand Sphinx de Gizeh représente-t-il ?","r":["Un lion","Un taureau","Un aigle","Un bélier"],"b":0,"a":"Il est taillé dans un affleurement de calcaire, au pied des grandes pyramides de Gizeh.","c":"Arts & lettres"},{"id":"742s8klz","t":"Quel peintre norvégien a réalisé Le Cri, dont la première version date de 1893 ?","r":["Gustav Klimt","Egon Schiele","Paul Klee","Edvard Munch"],"b":3,"a":"Munch a décliné son Cri en plusieurs versions : deux peintures, deux pastels et des lithographies.","c":"Arts & lettres"},{"id":"c0jlbyl0","t":"En 1951, dans quelle pièce de Corneille Gérard Philipe triomphe-t-il, sous la direction de Jean Vilar ?","r":["Phèdre","Le Cid","Tartuffe","Le Misanthrope"],"b":1,"a":"Jean Vilar dirigeait alors le Théâtre national populaire, installé au palais de Chaillot, et voulait ouvrir le théâtre à un public très large.","c":"Arts & lettres"},{"id":"0osrauz8","t":"Comment s'appelle le sonneur de cloches bossu de Notre-Dame de Paris, le roman de Victor Hugo ?","r":["Claude Frollo","Quasimodo","Phœbus","Gringoire"],"b":1,"a":"Son nom vient du dimanche de Quasimodo, jour où le bébé abandonné est recueilli par l'archidiacre Frollo.","c":"Arts & lettres"},{"id":"6aucnb4k","t":"Qui a écrit le roman de fantasy « Le Seigneur des anneaux », publié en 1954 et 1955 ?","r":["J. R. R. Tolkien","Agatha Christie","Aldous Huxley","T. S. Eliot"],"b":0,"a":"Conçue comme un seul roman, l'œuvre a été publiée en trois volumes : « La Communauté de l'anneau », « Les Deux Tours » et « Le Retour du roi ».","c":"Arts & lettres"},{"id":"xtd8cfzp","t":"Comment nomme-t-on le toit arrondi, en demi-sphère, qui couvre certains grands édifices comme le Panthéon ?","r":["Une flèche","Un dôme","Un auvent","Une lucarne"],"b":1,"a":"Dôme et coupole sont deux mots proches, que l'on emploie souvent l'un pour l'autre.","c":"Arts & lettres"},{"id":"zaqax9xu","t":"« Science sans conscience n'est que ruine de l'âme » : quel écrivain de la Renaissance a écrit cette phrase ?","r":["François Rabelais","Montaigne","Érasme","Pierre de Ronsard"],"b":0,"a":"La phrase figure dans la lettre où Gargantua expose à son fils Pantagruel un vaste programme d'éducation humaniste.","c":"Arts & lettres"},{"id":"t2lmwcg0","t":"Quelle peintre Art déco, née à Varsovie, a signé en 1929 Autoportrait dans la Bugatti verte ?","r":["Suzanne Valadon","Marie Laurencin","Tamara de Lempicka","Frida Kahlo"],"b":2,"a":"Le tableau a servi de couverture à un magazine allemand et reste l'image de la femme moderne des Années folles.","c":"Arts & lettres"},{"id":"h678sci7","t":"Comment s'appelait le célèbre théâtre londonien où l'on jouait les pièces de Shakespeare ?","r":["Le Palladium","Le Savoy","Le Lyceum","Le Globe"],"b":3,"a":"Un incendie a détruit le premier Globe en 1613, quand un tir de canon lors d'Henri VIII a mis le feu au toit de chaume.","c":"Arts & lettres"},{"id":"9753y1fc","t":"Comment nomme-t-on la fente étroite percée dans un mur de château fort pour tirer à l'arc sans s'exposer ?","r":["Une meurtrière","Une lucarne","Une échauguette","Une rosace"],"b":0,"a":"Les meurtrières s'évasent souvent vers l'intérieur : l'archer peut viser large tout en restant presque invisible du dehors.","c":"Arts & lettres"},{"id":"enfw501n","t":"Comment appelle-t-on l'espace caché, sur les côtés de la scène, où attendent les artistes avant d'entrer ?","r":["Le parterre","Les coulisses","Le poulailler","Le balcon"],"b":1,"a":"Le mot vient des rainures, les coulisses, dans lesquelles glissaient autrefois les panneaux de décor.","c":"Arts & lettres"},{"id":"t5178f22","t":"Quel poète publie en 1856 le recueil Les Contemplations ?","r":["Alphonse de Lamartine","Alfred de Vigny","Victor Hugo","Théophile Gautier"],"b":2,"a":"Hugo y évoque le deuil de sa fille Léopoldine, morte noyée en 1843.","c":"Arts & lettres"},{"id":"iz8yoz3f","t":"Dans une fable de La Fontaine, quel animal flatte le corbeau pour lui faire lâcher son fromage ?","r":["Le loup","Le renard","Le chat","Le singe"],"b":1,"a":"La morale de la fable est restée proverbiale : « Apprenez que tout flatteur vit aux dépens de celui qui l'écoute. »","c":"Arts & lettres"}],"moyen":[{"id":"8iw92ewl","t":"Qui a reçu le prix Nobel de littérature en 1953 ?","r":["Winston Churchill","Bertrand Russell","T. S. Eliot","Ernest Hemingway"],"b":0,"a":"Il a été récompensé pour ses écrits historiques et biographiques ainsi que pour son art oratoire.","c":"Arts & lettres"},{"id":"y8sh91gp","t":"Quel peintre a réalisé Les Iris en 1889, pendant son séjour à l'asile de Saint-Rémy-de-Provence ?","r":["Paul Gauguin","Paul Cézanne","Claude Monet","Vincent van Gogh"],"b":3,"a":"Le tableau a été peint dans le jardin de l'asile, au cours de la première semaine du séjour de l'artiste.","c":"Arts & lettres"},{"id":"lczdrzdn","t":"Dans la bande dessinée de Bill Watterson, quel animal est Hobbes, l'ami de Calvin ?","r":["Un ours","Un lion","Un chat","Un tigre"],"b":3,"a":"Les deux héros portent les noms de deux penseurs : le théologien Jean Calvin et le philosophe anglais Thomas Hobbes.","c":"Arts & lettres"},{"id":"wez8nch1","t":"Quel écrivain britannique publie en 1932 Le Meilleur des mondes, roman d'anticipation sur une société conditionnée ?","r":["George Orwell","H. G. Wells","Aldous Huxley","Ray Bradbury"],"b":2,"a":"Le titre original, Brave New World, est emprunté à une réplique de La Tempête de Shakespeare.","c":"Arts & lettres"},{"id":"xemdrshr","t":"Quel écrivain a rédigé les Mémoires d'outre-tombe, publiés après sa mort ?","r":["Alphonse de Lamartine","François-René de Chateaubriand","Alfred de Vigny","Jean-Jacques Rousseau"],"b":1,"a":"Chateaubriand est mort en 1848 ; ses Mémoires paraissent en feuilleton dans La Presse dès la fin de cette année-là.","c":"Arts & lettres"},{"id":"nw49objs","t":"De quelle race est Snoopy, le chien des Peanuts ?","r":["Beagle","Basset","Fox-terrier","Cocker"],"b":0,"a":"Snoopy dort sur le toit de sa niche plutôt qu'à l'intérieur, une habitude devenue l'une de ses images célèbres.","c":"Arts & lettres"},{"id":"u2g2ysac","t":"Qui a écrit « La Nausée », roman de 1938 dont le héros, Antoine Roquentin, tient un journal à Bouville ?","r":["Mikhaïl Cholokhov","Jean-Paul Sartre","Simone de Beauvoir","Astrid Lindgren"],"b":1,"a":"Le titre initialement envisagé par l'auteur était « Melancholia », titre que son éditeur a fait changer.","c":"Arts & lettres"},{"id":"66pdht6t","t":"Dans quelle pièce de Shakespeare un vieux roi partage-t-il son royaume entre ses filles ?","r":["Richard III","Le Roi Lear","Henri V","Richard II"],"b":1,"a":"Sa fille cadette, Cordelia, refuse de le flatter et se trouve déshéritée, tandis que ses deux aînées le trahissent.","c":"Arts & lettres"},{"id":"gbba8eey","t":"Qui a écrit le poème « Le Bateau ivre », composé en 1871 ?","r":["Michel Verne","Guy de Maupassant","Arthur Rimbaud","Oscar Wilde"],"b":2,"a":"Le poème a été lu par son jeune auteur à Paris devant des poètes, et on le considère comme l'un des sommets de la poésie française.","c":"Arts & lettres"},{"id":"sdczlsd6","t":"Dans quel pays est né le butô, une danse apparue à la fin des années 1950 ?","r":["Corée du Sud","Chine","Inde","Japon"],"b":3,"a":"Tatsumi Hijikata et Kazuo Ohno en sont les fondateurs ; le corps y est souvent peint en blanc.","c":"Arts & lettres"},{"id":"h498ap2q","t":"Comment appelle-t-on le grand saut où la danseuse s'élance d'une jambe sur l'autre, jambes en grand écart dans les airs ?","r":["La sissonne","La glissade","Le grand jeté","Le pas de bourrée"],"b":2,"a":"Exécuté en traversant la scène, ce saut donne au danseur l'impression de voler.","c":"Arts & lettres"},{"id":"gbd2uixl","t":"Quel architecte du XVIIe siècle a donné son nom au toit à quatre pentes brisées, dit « mansarde » ?","r":["Louis Le Vau","François Mansart","Claude Perrault","Pierre Lescot"],"b":1,"a":"Il a bâti le château de Maisons, à Maisons-Laffitte, longtemps cité comme un modèle de l'architecture classique française.","c":"Arts & lettres"},{"id":"0i87zaqc","t":"Quel architecte nord-américain a dessiné le musée Guggenheim de Bilbao, aux courbes recouvertes de titane ?","r":["Norman Foster","Richard Meier","Renzo Piano","Frank Gehry"],"b":3,"a":"Inauguré en 1997, il a tant attiré de visiteurs qu'on parle d'« effet Bilbao » pour la renaissance d'une ville par un musée.","c":"Arts & lettres"},{"id":"sl809r1v","t":"Quel philosophe publie en 1788 la Critique de la raison pratique ?","r":["Hegel","Fichte","Schopenhauer","Kant"],"b":3,"a":"C'est la deuxième de ses trois Critiques : elle porte sur la morale, après la connaissance et avant le jugement esthétique.","c":"Arts & lettres"},{"id":"qo41x0bi","t":"Dans quelle région d'Italie se trouvent les carrières de marbre de Carrare, exploitées depuis l'Antiquité ?","r":["La Lombardie","La Toscane","L'Ombrie","La Vénétie"],"b":1,"a":"Michel-Ange venait lui-même y choisir les blocs de ses statues.","c":"Arts & lettres"},{"id":"ksgrlvah","t":"Dans quelle ville se trouve le Centre belge de la Bande dessinée, installé dans un bâtiment de Victor Horta ?","r":["Bruxelles","Liège","Anvers","Gand"],"b":0,"a":"Le musée occupe d'anciens magasins Art nouveau et expose de nombreux héros de la BD belge.","c":"Arts & lettres"},{"id":"2wd3jces","t":"Combien d'arcades compte le rez-de-chaussée du Colisée de Rome ?","r":["60","100","120","80"],"b":3,"a":"Les arcades du rez-de-chaussée servaient d'entrées : la plupart étaient numérotées pour guider les spectateurs.","c":"Arts & lettres"},{"id":"dyqe1mw0","t":"Quel philosophe français a fondé le positivisme et forgé le mot « sociologie » ?","r":["Émile Durkheim","Henri de Saint-Simon","Auguste Comte","Alexis de Tocqueville"],"b":2,"a":"La devise « Ordre et Progrès », inspirée de sa pensée, figure sur le drapeau du Brésil.","c":"Arts & lettres"},{"id":"mmc439z5","t":"Quel pas sauté imite la légèreté d'un félin, les genoux se repliant l'un après l'autre sous le corps ?","r":["Le pas de bourrée","Le pas de basque","Le pas de chat","Le pas de deux"],"b":2,"a":"Dans ce saut, les jambes se lèvent successivement sur les côtés, à la manière d'un chat qui bondit.","c":"Arts & lettres"},{"id":"dcs2r11x","t":"Quel super-héros Marvel est un avocat aveugle aux autres sens surdéveloppés ?","r":["Spider-Man","Punisher","Daredevil","Doctor Strange"],"b":2,"a":"Il a perdu la vue enfant, lors d'un accident avec un produit radioactif, ce qui a aiguisé ses autres sens.","c":"Arts & lettres"},{"id":"cvt2rkuy","t":"Quel philosophe grec enseignait dans un jardin d'Athènes que le bonheur naît d'un plaisir simple et mesuré ?","r":["Zénon","Diogène","Épicure","Pyrrhon"],"b":2,"a":"Le mot « épicurien » a fini par désigner, à tort, un amateur de bonne chère.","c":"Arts & lettres"},{"id":"qqgawt66","t":"Quel peintre a immortalisé par ses affiches le cabaret parisien du Moulin Rouge ?","r":["Edgar Degas","Auguste Renoir","Henri de Toulouse-Lautrec","Alfons Mucha"],"b":2,"a":"Issu de l'aristocratie, il a fait de la lithographie en couleurs un art de la rue.","c":"Arts & lettres"},{"id":"t3p0ib0s","t":"Quel philosophe publie en 1763, après l'affaire Calas, un Traité sur la tolérance ?","r":["Jean-Jacques Rousseau","Denis Diderot","Voltaire","Montesquieu"],"b":2,"a":"Voltaire se bat pour la réhabilitation de Jean Calas, condamné à tort à Toulouse ; elle est prononcée en 1765.","c":"Arts & lettres"},{"id":"9ennk5he","t":"Quel pouvoir le fruit du démon mangé par Luffy lui donne-t-il, dans One Piece ?","r":["Le vol","L'invisibilité","Un corps de feu","Un corps élastique"],"b":3,"a":"Luffy ne sait plus nager depuis qu'il a mangé ce fruit : ceux qui en mangent coulent comme des pierres.","c":"Arts & lettres"}],"difficile":[{"id":"a8uryb4e","t":"Quel artiste a gravé en 1514 Melencolia I, où un ange songeur est entouré d'instruments de mesure ?","r":["Lucas Cranach l'Ancien","Hans Holbein le Jeune","Martin Schongauer","Albrecht Dürer"],"b":3,"a":"Au mur de la gravure figure un carré magique dont la dernière ligne contient l'année 1514.","c":"Arts & lettres"},{"id":"2pv47zfu","t":"Quel poète a écrit « Le ciel est, par-dessus le toit, / Si bleu, si calme ! » ?","r":["Paul Verlaine","Arthur Rimbaud","Alfred de Musset","Gérard de Nerval"],"b":0,"a":"Le poète l'a écrit en prison, en Belgique, après avoir tiré au revolver sur Rimbaud ; il paraît dans le recueil Sagesse.","c":"Arts & lettres"},{"id":"t7ah4296","t":"Quel philosophe français, de son vrai nom Émile Chartier, écrit « Penser, c'est dire non » ?","r":["Gabriel Marcel","Jules Lagneau","Léon Brunschvicg","Alain"],"b":3,"a":"Professeur de lycée, il a eu pour élèves Simone Weil et Raymond Aron ; ses Propos sont de courts billets quotidiens.","c":"Arts & lettres"},{"id":"dnak42x5","t":"Quel écrivain romantique a coécrit le livret de Giselle, créé à l'Opéra de Paris en 1841 ?","r":["Victor Hugo","Théophile Gautier","Alfred de Musset","Gérard de Nerval"],"b":1,"a":"Il avait trouvé l'idée des Willis dans un texte de Heinrich Heine sur les légendes allemandes.","c":"Arts & lettres"},{"id":"d3ez3zid","t":"Qui a écrit « Le Spleen de Paris », recueil de poèmes en prose publié après la mort de son auteur ?","r":["Gustave Flaubert","Baháʼu'lláh","Charles Baudelaire","Karl Marx"],"b":2,"a":"Le recueil est aussi connu sous le titre « Petits poèmes en prose ».","c":"Arts & lettres"},{"id":"dkggwkq7","t":"Quel est le diamètre, en mètres, de la coupole du Panthéon de Rome ?","r":["28,5 m","43,3 m","56,8 m","37,2 m"],"b":1,"a":"Sa coupole en béton non armé est la plus grande jamais bâtie dans l'Antiquité, et elle tient toujours.","c":"Arts & lettres"},{"id":"8nrdyxt4","t":"Quel poète français reçoit en 1901 le tout premier prix Nobel de littérature ?","r":["Sully Prudhomme","Frédéric Mistral","Anatole France","Pierre Loti"],"b":0,"a":"Le choix a fait scandale : Tolstoï, que beaucoup attendaient, n'a jamais reçu le prix.","c":"Arts & lettres"},{"id":"n9ds0y8g","t":"Dans quelle pièce de Shakespeare Petruchio entreprend-il de dompter la rebelle Katharina ?","r":["Beaucoup de bruit pour rien","Comme il vous plaira","Le Marchand de Venise","La Mégère apprivoisée"],"b":3,"a":"La comédie musicale Kiss Me, Kate (1948) et le film Dix bonnes raisons de te larguer (1999) en sont des adaptations.","c":"Arts & lettres"},{"id":"9zzdscfo","t":"Qui a écrit le roman « Mansfield Park », publié en 1814 ?","r":["Samuel Taylor Coleridge","Ernst Theodor Amadeus Hoffmann","Jane Austen","Lord Byron"],"b":2,"a":"C'est le troisième roman publié par son autrice, après « Raison et Sentiments » et « Orgueil et Préjugés ».","c":"Arts & lettres"},{"id":"ridlvb6i","t":"Qui a écrit « Ozymandias », sonnet de 1818 évoquant les ruines d'une statue colossale ?","r":["Percy Bysshe Shelley","John Keats","Lord Byron","Jane Austen"],"b":0,"a":"Le nom Ozymandias désigne le pharaon Ramsès II, et le poème a été écrit lors d'un concours amical avec un autre poète.","c":"Arts & lettres"},{"id":"rka0fz5m","t":"Quel peintre du XVIIIe siècle est célèbre pour ses vues précises de Venise et de son Grand Canal ?","r":["Tiepolo","Titien","Canaletto","Le Tintoret"],"b":2,"a":"Ses vues se vendaient très bien auprès des riches voyageurs anglais du Grand Tour, et il a fini par séjourner à Londres.","c":"Arts & lettres"},{"id":"ae6s12sr","t":"Qui a peint « Nu descendant un escalier » en 1912 ?","r":["Edward Hopper","Henri Matisse","Norman Rockwell","Marcel Duchamp"],"b":3,"a":"Présenté à l'Armory Show de New York en 1913, le tableau a fait scandale et est devenu l'emblème de l'art moderne.","c":"Arts & lettres"},{"id":"wc3znnc2","t":"Quel nom porte la galerie qui tourne autour du chœur d'une église et permet aux pèlerins d'en faire le tour ?","r":["Le collatéral","Le narthex","Le triforium","Le déambulatoire"],"b":3,"a":"Des chapelles rayonnantes s'ouvrent souvent sur cette galerie, abritant parfois des reliques que venaient voir les pèlerins.","c":"Arts & lettres"},{"id":"poaz55im","t":"Comment Le Corbusier a-t-il nommé son système de mesures fondé sur les proportions du corps humain ?","r":["Le Module","L'Homme-type","Le Corbumètre","Le Modulor"],"b":3,"a":"Le système part de la silhouette d'un homme debout, le bras levé. Le Corbusier l'a utilisé pour la Cité radieuse de Marseille.","c":"Arts & lettres"},{"id":"uei3qmae","t":"Quel courant philosophique américain, porté par William James, juge une idée à ses effets concrets ?","r":["Le pragmatisme","L'utilitarisme","Le positivisme","L'empirisme"],"b":0,"a":"Le terme a été introduit par le logicien Charles Sanders Peirce, ami de William James.","c":"Arts & lettres"},{"id":"ol99nlz5","t":"Qui a écrit « La Légende de Sleepy Hollow », conte du cavalier sans tête ?","r":["James Fenimore Cooper","Stendhal","Heinrich von Kleist","Washington Irving"],"b":3,"a":"Ce conte est paru en 1820 dans le recueil « The Sketch Book ». Tim Burton en a tiré un film en 1999.","c":"Arts & lettres"},{"id":"3myj1zdh","t":"Qui a créé Babar, l'éléphant roi, dans un album publié en 1931 ?","r":["Marcel Aymé","Benjamin Rabier","Jean de Brunhoff","Samivel"],"b":2,"a":"L'histoire est née d'un conte que Cécile de Brunhoff, la femme de l'auteur, inventait pour endormir leurs fils.","c":"Arts & lettres"},{"id":"dthiipp4","t":"Quel architecte américain a conçu le musée Guggenheim de New York, en forme de spirale ?","r":["Le Corbusier","Frank Lloyd Wright","Ludwig Mies van der Rohe","Walter Gropius"],"b":1,"a":"Wright y a travaillé plus de quinze ans, et il est mort quelques mois avant l'inauguration.","c":"Arts & lettres"},{"id":"hpyo5dvu","t":"Dans quel journal Astérix fait-il ses débuts, en 1959 ?","r":["Spirou","Tintin","Vaillant","Pilote"],"b":3,"a":"Goscinny et Uderzo comptaient parmi les fondateurs de ce journal, dont Astérix occupait les pages dès le premier numéro.","c":"Arts & lettres"},{"id":"0cj3ayai","t":"Quel écrivain italien publie en 1952 Le Vicomte pourfendu, premier volet de la trilogie Nos ancêtres ?","r":["Umberto Eco","Italo Calvino","Alberto Moravia","Primo Levi"],"b":1,"a":"Né à Cuba, Calvino a passé son enfance à San Remo et a vécu à Paris de 1967 à 1980.","c":"Arts & lettres"}]},"Sport":{"facile":[{"id":"my4kxxld","t":"Dans quel sport le Canadien Wayne Gretzky s'est-il rendu célèbre ?","r":["Basket-ball","Baseball","Hockey sur glace","Football américain"],"b":2,"a":"Wayne Gretzky a appris à patiner enfant sur une patinoire que son père aménageait chaque hiver dans le jardin familial, à Brantford, en Ontario.","c":"Sport"},{"id":"k0slrg0g","t":"Quel maillot porte le meilleur grimpeur du Tour de France ?","r":["Vert à pois blancs","Jaune à pois noirs","Rouge à pois blancs","Blanc à pois rouges"],"b":3,"a":"Ce maillot à pois est apparu en 1975.","c":"Sport"},{"id":"wf89eemx","t":"Quelle remontée mécanique tire le skieur, resté debout sur ses skis, grâce à une perche ?","r":["Le télésiège","La télécabine","Le téléski","Le téléphérique"],"b":2,"a":"Les skieurs surnomment familièrement le téléski le « tire-fesses ».","c":"Sport"},{"id":"rv18ocuw","t":"Quelle nage presque tous les nageurs choisissent-ils dans les épreuves de nage libre ?","r":["Le crawl","La brasse","Le dos crawlé","Le papillon"],"b":0,"a":"Le règlement laisse libre le choix de la nage : on choisit le crawl simplement parce que c'est la plus rapide.","c":"Sport"},{"id":"4uv8g64l","t":"Dans quelle discipline l'Américaine Simone Biles a-t-elle remporté ses médailles d'or olympiques ?","r":["La gymnastique artistique","La natation","L'athlétisme","Le plongeon"],"b":0,"a":"Un saut et une figure au sol portent son nom en compétition.","c":"Sport"},{"id":"2tbrf6g5","t":"Combien de points rapporte un coup de pied de pénalité réussi au rugby à XV ?","r":["1 point","2 points","3 points","5 points"],"b":2,"a":"La pénalité est tentée après une faute adverse, souvent à l'aide d'un tee posé sur le sol.","c":"Sport"},{"id":"pqbu2lrr","t":"À quelle hauteur, en mètres, est tendu le filet lors d'un match de volley-ball féminin ?","r":["2,24 m","2,10 m","2,43 m","2,30 m"],"b":0,"a":"Au volley assis, pratiqué par des sportifs handicapés, le filet ne mesure qu'environ un mètre de haut.","c":"Sport"},{"id":"dfibbmgr","t":"Quel Suisse a remporté Wimbledon à huit reprises ?","r":["Stan Wawrinka","Marc Rosset","Roger Federer","Heinz Günthardt"],"b":2,"a":"Son dernier titre date de 2017, remporté sans perdre un set.","c":"Sport"},{"id":"bwbw3vmc","t":"En 2008, quel pilote devient le premier champion du monde noir de Formule 1 ?","r":["Felipe Massa","Fernando Alonso","Kimi Räikkönen","Lewis Hamilton"],"b":3,"a":"Il décroche le titre à Interlagos, au Brésil, en passant un rival dans les derniers virages de la toute dernière course de la saison.","c":"Sport"},{"id":"rx7cotnr","t":"Dans quelle ville proche de Milan se trouve le circuit surnommé « le Temple de la vitesse » ?","r":["Imola","Mugello","Monza","Bologne"],"b":2,"a":"Le circuit est installé dans un parc royal, et les tifosi de Ferrari y sont très nombreux.","c":"Sport"},{"id":"o6ha4vm3","t":"Quelle compétition annuelle oppose notamment la France, l'Angleterre, l'Irlande et l'Italie ?","r":["Le Rugby Championship","La Coupe du monde","La Champions Cup","Le Tournoi des Six Nations"],"b":3,"a":"Le Tournoi se dispute chaque hiver, de février à mars, et chaque équipe y affronte une seule fois toutes les autres.","c":"Sport"},{"id":"8bua1la4","t":"Quel engin d'athlétisme est une longue tige terminée par une pointe métallique, que l'on lance après une course d'élan ?","r":["Le disque","Le marteau","Le javelot","Le poids"],"b":2,"a":"En 1986, le centre de gravité du javelot masculin a été avancé pour raccourcir les jets, devenus trop longs pour la taille des stades.","c":"Sport"},{"id":"i9dazjxx","t":"De quelle couleur est la balle utilisée dans les tournois professionnels de tennis ?","r":["Blanche","Orange","Jaune","Verte"],"b":2,"a":"Wimbledon n'a adopté la balle jaune qu'en 1986 : elle se voit mieux à la télévision que la balle blanche d'autrefois.","c":"Sport"},{"id":"r3aq032c","t":"Comment surnomme-t-on le monde du rugby, d'après la forme de son ballon ?","r":["La Rondie","La Pelousie","L'Ellipsie","L'Ovalie"],"b":3,"a":"Le mot sert aussi à désigner la communauté des joueurs et supporters, bien au-delà de la France.","c":"Sport"},{"id":"vurczno6","t":"Comment appelle-t-on une voiture de course qui n'a qu'une seule place, comme une Formule 1 ?","r":["Un prototype","Une berline","Un roadster","Une monoplace"],"b":3,"a":"Le pilote d'une monoplace est installé au centre de la voiture, presque allongé, les jambes sous le nez du châssis.","c":"Sport"},{"id":"j6nye3fq","t":"Quel pays est surnommé le XV de la Rose ?","r":["Irlande","Angleterre","Écosse","Pays de Galles"],"b":1,"a":"Une rose rouge, emblème de l'Angleterre, est brodée sur le maillot blanc de l'équipe.","c":"Sport"},{"id":"dzzunr7p","t":"Dans quelle ville se tiennent, en 1896, les premiers Jeux olympiques de l'ère moderne ?","r":["Athènes","Paris","Londres","Rome"],"b":0,"a":"Les épreuves de 1896 se sont disputées dans le stade panathénaïque, reconstruit en marbre blanc pour l'occasion.","c":"Sport"},{"id":"f71dfr5o","t":"Au football, quel objet l'arbitre utilise-t-il pour arrêter le jeu ?","r":["Un drapeau","Une cloche","Un sifflet","Un mégaphone"],"b":2,"a":"L'arbitre central est aidé par deux arbitres assistants, qui signalent notamment les hors-jeu en levant leur drapeau.","c":"Sport"},{"id":"abwujo3t","t":"En 1936 à Berlin, quel athlète américain remporte quatre médailles d'or ?","r":["Carl Lewis","Jim Thorpe","Jesse Owens","Ralph Metcalfe"],"b":2,"a":"Carl Lewis égalera son exploit à Los Angeles, en 1984, en gagnant les quatre mêmes épreuves.","c":"Sport"},{"id":"t3vvcc47","t":"Quel club de Lisbonne, vêtu de vert et blanc, a pour emblème un lion ?","r":["Benfica","Belenenses","Sporting CP","Estoril"],"b":2,"a":"Ses supporters sont surnommés « Leões », c'est-à-dire les lions.","c":"Sport"},{"id":"b52rg1j0","t":"En 2022, quel joueur français reçoit le Ballon d'or ?","r":["Karim Benzema","Kylian Mbappé","Antoine Griezmann","N'Golo Kanté"],"b":0,"a":"Aucun Français ne l'avait reçu depuis Zinédine Zidane, en 1998.","c":"Sport"},{"id":"sqhtsaks","t":"En quelle année naît la ligue qui deviendra la NBA, alors appelée BAA ?","r":["1938","1955","1946","1950"],"b":2,"a":"La BAA a pris le nom de NBA en 1949, en fusionnant avec une ligue rivale, la NBL.","c":"Sport"},{"id":"71vrlii3","t":"En quelle année Valentino Rossi remporte-t-il son premier titre mondial dans la catégorie reine, alors le 500 cm3 ?","r":["2001","1997","2004","1999"],"b":0,"a":"Il est le dernier champion de l'ère des 500 cm3 deux-temps, remplacés dès l'année suivante par les MotoGP à quatre temps.","c":"Sport"},{"id":"v7a4thec","t":"Dans quelle partie de la France le rugby est-il traditionnellement le plus implanté ?","r":["Le Nord","L'Est","Le Sud-Ouest","La Bretagne"],"b":2,"a":"Toulouse, Bayonne, Biarritz, Pau ou Agen ont fait du Sud-Ouest la terre d'ovalie, où chaque village ou presque a son club.","c":"Sport"}],"moyen":[{"id":"spalvocu","t":"Quel club parisien de rugby est surnommé les « Soldats roses » ?","r":["Racing 92","Paris Université Club","Stade français","Stade toulousain"],"b":2,"a":"Le maillot rose a été porté pour la première fois en septembre 2005, lors d'un match de championnat à Perpignan.","c":"Sport"},{"id":"gyeql1lz","t":"Combien de joueurs compte une équipe de curling sur la glace ?","r":["Trois","Quatre","Cinq","Six"],"b":1,"a":"Les balayeurs frottent la glace devant la pierre : cela la réchauffe légèrement et lui permet d'aller plus loin et plus droit.","c":"Sport"},{"id":"vuszwtrn","t":"Quel club anglais joue ses matchs à domicile au stade d'Anfield ?","r":["Everton","Manchester City","Liverpool","Arsenal"],"b":2,"a":"Avant les matchs, le public d'Anfield entonne « You'll Never Walk Alone », devenu l'hymne du club.","c":"Sport"},{"id":"d5wl99db","t":"Quelle est la hauteur, en centimètres, des barrières du 3 000 m steeple masculin ?","r":["76,2 cm","91,4 cm","106,7 cm","84 cm"],"b":1,"a":"Contrairement aux haies, les barrières du steeple sont lourdes et fixes : elles ne basculent pas quand on les heurte.","c":"Sport"},{"id":"sc713737","t":"Que signifie à peu près le mot japonais « karaté » ?","r":["Poing d'acier","Voie du sabre","Main vide","Art de la guerre"],"b":2,"a":"À Okinawa, le premier idéogramme du mot signifiait d'abord « de Chine » avant d'être remplacé par celui qui veut dire « vide ».","c":"Sport"},{"id":"r2s92dhd","t":"Quel nom porte le court central de Roland-Garros ?","r":["Suzanne-Lenglen","Philippe-Chatrier","Simonne-Mathieu","René-Lacoste"],"b":1,"a":"Philippe Chatrier a présidé la Fédération française de tennis.","c":"Sport"},{"id":"te27u32d","t":"En 2014, sur quel score l'Allemagne bat-elle le Brésil, pays hôte, en demi-finale de la Coupe du monde ?","r":["5-0","6-2","7-1","4-1"],"b":2,"a":"Les Allemands mènent déjà 5-0 au bout d'une demi-heure de jeu, à Belo Horizonte.","c":"Sport"},{"id":"xzx6st04","t":"Combien de juges notent habituellement un combat de boxe professionnelle ?","r":["Deux","Trois","Quatre","Cinq"],"b":1,"a":"Quand deux juges donnent la victoire au même boxeur et le troisième à l'autre, on parle de décision partagée.","c":"Sport"},{"id":"26mx6hdx","t":"Au hockey sur glace, comment appelle-t-on l'exploit d'un joueur qui marque trois buts dans le même match ?","r":["Un grand chelem","Un coup du chapeau","Un triplé d'or","Un carton plein"],"b":1,"a":"Au Canada, les supporters lancent leurs casquettes sur la glace pour saluer cet exploit.","c":"Sport"},{"id":"dgqzouvu","t":"Comment s'appelle la grande voile colorée, gonflée comme un ballon, hissée à l'avant d'un voilier par vent arrière ?","r":["Le génois","Le foc","La grand-voile","Le spinnaker"],"b":3,"a":"Ses couleurs vives se voient de loin, sur l'eau, pendant les régates.","c":"Sport"},{"id":"rfrb1rv9","t":"En 2014, quel Italien remporte le Tour de France ?","r":["Alberto Contador","Nairo Quintana","Vincenzo Nibali","Fabio Aru"],"b":2,"a":"Il a aussi gagné le Tour d'Italie et le Tour d'Espagne, ce qui lui vaut une place parmi les vainqueurs des trois grands tours.","c":"Sport"},{"id":"t22xkz8r","t":"En 2007, quelle équipe bat la France 17-12 lors du match d'ouverture de la Coupe du monde, au Stade de France ?","r":["Irlande","Géorgie","Namibie","Argentine"],"b":3,"a":"L'Argentine a battu la France une seconde fois, 34-10, lors du match pour la troisième place.","c":"Sport"},{"id":"opgo51qt","t":"Quelle est la hauteur, en centimètres, des haies du 100 m haies féminin ?","r":["76,2 cm","91,4 cm","83,8 cm","100 cm"],"b":2,"a":"Le 100 m haies a remplacé le 80 m haies au programme olympique féminin à partir des Jeux de Munich, en 1972.","c":"Sport"},{"id":"syvne5pp","t":"De 2009 à 2020, dans quelle ville se disputait le Masters de fin de saison du circuit masculin (ATP Finals) ?","r":["Shanghai","Paris","Londres","Madrid"],"b":2,"a":"Les matchs se jouaient à l'O2 Arena, une salle couverte au bord de la Tamise. Le tournoi a déménagé à Turin en 2021.","c":"Sport"},{"id":"5u9yt8vf","t":"Au rugby, comment appelle-t-on le regroupement spontané de joueurs autour d'un ballon posé au sol ?","r":["Le maul","La mêlée ordonnée","Le ruck","La chandelle"],"b":2,"a":"Dans un ruck, les joueurs n'ont pas le droit de prendre le ballon à la main : ils doivent le récupérer avec les pieds ou attendre qu'il sorte.","c":"Sport"},{"id":"6dmjsctu","t":"Quel surnom a reçu l'équipe américaine de basket des Jeux de Barcelone, en 1992, avec Michael Jordan et Magic Johnson ?","r":["Magic Team","Golden Team","Dream Team","Super Team"],"b":2,"a":"C'était la première fois que les joueurs professionnels de la NBA pouvaient participer au tournoi olympique de basket.","c":"Sport"},{"id":"ekv280ka","t":"Qui a remporté le classement général du Tour de France 1971 ?","r":["Ferdinand Bracke","Lucien Van Impe","Freddy Maertens","Eddy Merckx"],"b":3,"a":"Ce fut sa troisième victoire dans le Tour, sur les cinq qu'il obtiendra au total.","c":"Sport"},{"id":"9u6pxlo0","t":"À quelle distance du but se tire un jet de penalty au handball ?","r":["7 mètres","6 mètres","9 mètres","5 mètres"],"b":0,"a":"Le tireur ne peut pas marcher sur la ligne : il doit tirer sans la franchir, face au seul gardien.","c":"Sport"},{"id":"6wv3088q","t":"Quel boxeur se faisait appeler « The Greatest », « le plus grand » ?","r":["Joe Frazier","Sugar Ray Leonard","Muhammad Ali","Joe Louis"],"b":2,"a":"Ali clamait « I am the greatest » dès sa victoire contre Sonny Liston, et le surnom ne l'a plus quitté.","c":"Sport"},{"id":"copp44yt","t":"Quelle épreuve, aujourd'hui disparue, a figuré au programme des Jeux olympiques de 1900 à 1920 ?","r":["Le bras de fer","Le tir à la corde","Le lancer de troncs","La pétanque"],"b":1,"a":"En 1908 à Londres, les trois médailles sont revenues à des équipes de policiers britanniques.","c":"Sport"},{"id":"erd7oh8a","t":"En 1960, quelle sélection remporte à Paris la toute première édition du Championnat d'Europe de football ?","r":["Yougoslavie","Tchécoslovaquie","Hongrie","URSS"],"b":3,"a":"Viktor Ponedelnik marque le but vainqueur en prolongation, au Parc des Princes.","c":"Sport"},{"id":"697c7012","t":"En 1900, quelle ville accueille les deuxièmes Jeux olympiques modernes, en marge d'une exposition universelle ?","r":["Londres","Saint-Louis","Paris","Stockholm"],"b":2,"a":"Ce sont les premiers Jeux auxquels des femmes ont participé.","c":"Sport"},{"id":"qrnkc2pl","t":"Comment s'appelle, depuis 2005, le championnat de France de première division de rugby à XV ?","r":["Top 16","Pro D2","Top 14","Super 12"],"b":2,"a":"Son nom vient du nombre de clubs qui y participent, quatorze, après une saison 2004-2005 jouée à seize sous le nom de Top 16.","c":"Sport"},{"id":"6tbila2b","t":"En 1970, quel pays conserve définitivement le trophée Jules-Rimet après un troisième titre mondial ?","r":["Italie","Brésil","Uruguay","Allemagne"],"b":1,"a":"Le trophée a été volé à Rio en 1983 et n'a jamais été retrouvé.","c":"Sport"}],"difficile":[{"id":"1ta370by","t":"Quel boxeur redevient champion du monde des poids lourds en 1994, à 45 ans ?","r":["Larry Holmes","George Foreman","Evander Holyfield","Ken Norton"],"b":1,"a":"George Foreman a ensuite fait fortune en prêtant son nom à un gril électrique vendu à des millions d'exemplaires.","c":"Sport"},{"id":"5qtypjvh","t":"Quelle sélection de football surnomme-t-on les « Fennecs » ?","r":["Tunisie","Maroc","Égypte","Algérie"],"b":3,"a":"Le fennec, petit renard du désert aux très grandes oreilles, est l'animal emblème de l'Algérie.","c":"Sport"},{"id":"0d017n3p","t":"Quelle fondeuse norvégienne remporte trois médailles d'or aux Jeux olympiques de Vancouver, en 2010 ?","r":["Therese Johaug","Justyna Kowalczyk","Marit Bjørgen","Charlotte Kalla"],"b":2,"a":"Elle ajoute à Vancouver une médaille d'argent et une de bronze, avant de briller encore à Sotchi et à PyeongChang.","c":"Sport"},{"id":"u58tiuou","t":"Dans quel pays se trouve Nazaré, célèbre pour ses vagues géantes que les surfeurs viennent affronter ?","r":["Espagne","Irlande","France","Portugal"],"b":3,"a":"Un profond canyon sous-marin y concentre la houle de l'Atlantique et fait gonfler les vagues au pied du phare.","c":"Sport"},{"id":"agfbp12a","t":"Qui a remporté le classement général du Tour de France 1964 ?","r":["Jacques Anquetil","Raymond Poulidor","Roger Walkowiak","Jean Stablinski"],"b":0,"a":"Son duel avec Raymond Poulidor sur les pentes du Puy de Dôme est resté célèbre.","c":"Sport"},{"id":"19wl3xec","t":"Depuis 2020, quel nom porte la Fed Cup, compétition féminine par équipes nationales ?","r":["Hopman Cup","Laver Cup","Billie Jean King Cup","United Cup"],"b":2,"a":"La compétition a été rebaptisée en l'honneur de l'Américaine, pionnière de l'égalité des gains entre hommes et femmes.","c":"Sport"},{"id":"fhw1hzdw","t":"En 2012 à Londres, quelle équipe la France bat-elle en finale du tournoi olympique de handball masculin ?","r":["Croatie","Islande","Hongrie","Suède"],"b":3,"a":"Les Français l'ont emporté 22-21 et se sont offert un doublé olympique après 2008.","c":"Sport"},{"id":"h846n232","t":"En 1993, quelle marque française prend les trois premières places des 24 Heures du Mans ?","r":["Matra","Renault","Peugeot","Citroën"],"b":2,"a":"Ce triplé suit la victoire de 1992 : la marque au lion a ainsi gagné deux années de suite avec ses prototypes à moteur V10.","c":"Sport"},{"id":"mtagbtbd","t":"Quel nageur, champion olympique à Paris en 1924, a ensuite incarné Tarzan au cinéma ?","r":["Mark Spitz","Johnny Weissmuller","Matt Biondi","Don Schollander"],"b":1,"a":"Johnny Weissmuller a remporté cinq titres olympiques en natation, en 1924 puis en 1928.","c":"Sport"},{"id":"lztt87ir","t":"Quel pays remporte le tournoi de hockey sur glace des Jeux olympiques d'Anvers, en 1920 ?","r":["États-Unis","Suède","Canada","Tchécoslovaquie"],"b":2,"a":"Ce tournoi a lieu aux Jeux d'été, quatre ans avant les premiers Jeux d'hiver de Chamonix.","c":"Sport"},{"id":"b445bwzo","t":"En 1996 à Atlanta, quel Français devient champion olympique du saut à la perche ?","r":["Pierre Quinon","Jean Galfione","Renaud Lavillenie","Romain Mesnil"],"b":1,"a":"Trois sauteurs avaient franchi la même barre : il l'emporte grâce à son plus petit nombre d'essais manqués.","c":"Sport"},{"id":"c4qteb61","t":"Sur le drapeau olympique, de quelle couleur est l'anneau placé en haut à gauche ?","r":["Noir","Bleu","Rouge","Vert"],"b":1,"a":"La rangée du haut aligne le bleu, le noir et le rouge ; celle du bas, le jaune et le vert.","c":"Sport"},{"id":"u0wz98kh","t":"En 1995, quelle Française remporte l'Open d'Australie en simple dames ?","r":["Mary Pierce","Amélie Mauresmo","Nathalie Tauziat","Julie Halard"],"b":0,"a":"Mary Pierce est née à Montréal, au Canada. Elle possédait les nationalités française, canadienne et américaine.","c":"Sport"},{"id":"28kmm7ba","t":"En 1903, combien de coureurs parviennent jusqu'à l'arrivée du premier Tour de France ?","r":["15 coureurs","44 coureurs","33 coureurs","21 coureurs"],"b":3,"a":"Les étapes étaient si longues que les coureurs roulaient souvent de nuit.","c":"Sport"},{"id":"y0sui4ai","t":"En 1993, quel club français remporte l'Euroligue, face à Trévise ?","r":["Pau-Orthez","ASVEL Villeurbanne","SIG Strasbourg","Limoges CSP"],"b":3,"a":"Limoges a battu Benetton Trévise à Athènes : c'est un des rares titres européens du basket français.","c":"Sport"},{"id":"z8bamrqw","t":"Quel pivot américain est célèbre pour son « sky hook », un crochet à une main devenu inarrêtable ?","r":["Kareem Abdul-Jabbar","Wilt Chamberlain","Bill Russell","Hakeem Olajuwon"],"b":0,"a":"Il a joué aux Bucks de Milwaukee puis aux Lakers de Los Angeles.","c":"Sport"},{"id":"0b3dsf1z","t":"Quel attaquant brésilien surnommait-on « O Fenômeno », le phénomène ?","r":["Ronaldinho","Romário","Ronaldo","Rivaldo"],"b":2,"a":"Le Brésilien Ronaldo a joué pour le FC Barcelone, l'Inter Milan, le Real Madrid et l'AC Milan.","c":"Sport"},{"id":"up9ayehh","t":"Quel pilote américain d'origine italienne est champion du monde de Formule 1 en 1978 sur Lotus ?","r":["Dan Gurney","Mario Andretti","Peter Revson","Phil Hill"],"b":1,"a":"Né en 1940 dans l'actuelle Croatie, il a aussi gagné les 500 Miles d'Indianapolis en 1969.","c":"Sport"},{"id":"syieis9f","t":"En 2017, quelle équipe la France bat-elle en finale de la Coupe Davis, à Villeneuve-d'Ascq ?","r":["La Croatie","La Serbie","La Belgique","L'Argentine"],"b":2,"a":"La finale se jouait au stade Pierre-Mauroy, où évolue aussi le club de football du LOSC.","c":"Sport"},{"id":"0n8ifa29","t":"Quel Australien est le seul joueur à avoir réalisé deux fois le Grand Chelem calendaire en simple, en 1962 puis en 1969 ?","r":["Ken Rosewall","Lew Hoad","Rod Laver","Roy Emerson"],"b":2,"a":"La Rod Laver Arena, à Melbourne, porte son nom.","c":"Sport"}]},"Cuisine":{"facile":[{"id":"mwmgub4g","t":"Comment appelle-t-on au Japon les fines tranches de poisson cru servies sans riz ?","r":["Sashimi","Maki","Tempura","Yakitori"],"b":0,"a":"Le sashimi se sert souvent sur un lit de radis blanc râpé, qui rafraîchit la bouche entre deux bouchées.","c":"Cuisine"},{"id":"4tpyuk3e","t":"Quelle ville a été proclamée « capitale mondiale de la gastronomie » par le critique Curnonsky ?","r":["Paris","Lyon","Dijon","Strasbourg"],"b":1,"a":"Ses mères cuisinières, comme Eugénie Brazier, ont fait la réputation de la ville.","c":"Cuisine"},{"id":"4bu1fao0","t":"Quel verbe désigne la cuisson d'une saucisse posée sur une grille, au-dessus des braises ?","r":["Pocher","Braiser","Frire","Griller"],"b":3,"a":"Les marques quadrillées qu'on dessine parfois sur la viande viennent des barreaux brûlants de la grille.","c":"Cuisine"},{"id":"iutjar2u","t":"Quel vêtement le cuisinier noue-t-il autour de la taille pour protéger ses habits ?","r":["Le foulard","Le tablier","Le gilet","L'écharpe"],"b":1,"a":"En cuisine, le tablier se porte souvent avec un torchon glissé dans le cordon, toujours à portée de main.","c":"Cuisine"},{"id":"7o0stduu","t":"Quelle viande, hachée et servie crue, compose le steak tartare ?","r":["Veau","Agneau","Bœuf","Porc"],"b":2,"a":"Il est souvent assaisonné de câpres, d'oignon, de cornichons et d'un jaune d'œuf cru posé dessus.","c":"Cuisine"},{"id":"mu83eao3","t":"Quel ustensile de cuisine permet d'ouvrir une boîte de conserve en métal ?","r":["Tire-bouchon","Décapsuleur","Ouvre-boîte","Casse-noix"],"b":2,"a":"Les premières conserves en fer-blanc s'ouvraient au marteau et au burin : l'ouvre-boîte n'est apparu que plusieurs décennies après elles.","c":"Cuisine"},{"id":"t7xmjdbr","t":"Comment appelle-t-on la récolte des raisins destinés à faire du vin ?","r":["La moisson","Les vendanges","La cueillette","Le glanage"],"b":1,"a":"Dans certains vignobles, dont la Champagne, les raisins sont encore cueillis à la main pour ne pas abîmer les grappes.","c":"Cuisine"},{"id":"wy3m3tq6","t":"Que fait-on à une farine ou à un sucre glace pour ôter les grumeaux avant de l'utiliser ?","r":["Pétrir","Tamiser","Râper","Mixer"],"b":1,"a":"Tamiser aère aussi la farine, qui se mêle ensuite aux autres ingrédients sans former de paquets.","c":"Cuisine"},{"id":"kmmx5ack","t":"En quelle année le piment d'Espelette obtient-il son appellation d'origine contrôlée ?","r":["1920","1950","1980","2000"],"b":3,"a":"Après la récolte, les piments sont enfilés en cordes que l'on suspend aux façades des maisons basques pour les faire sécher.","c":"Cuisine"},{"id":"7ovzthmk","t":"De quel pays vient le parmesan, fromage à pâte dure qu'on râpe sur les pâtes ?","r":["Suisse","Italie","Espagne","Grèce"],"b":1,"a":"Son nom italien, Parmigiano Reggiano, vient des provinces de Parme et de Reggio d'Émilie, où il est produit.","c":"Cuisine"},{"id":"0lrl0edp","t":"Quelle maison parisienne, fondée en 1862 rue Royale, est célèbre pour ses macarons ?","r":["Fauchon","Lenôtre","Ladurée","Dalloyau"],"b":2,"a":"La maison est née d'une boulangerie ouverte par Louis-Ernest Ladurée, avant de devenir un salon de thé.","c":"Cuisine"},{"id":"oyknic68","t":"En quelle année l'américain Nabisco commercialise-t-il le biscuit Oreo ?","r":["1912","1889","1938","1955"],"b":0,"a":"Il est né à New York, dans l'usine de Nabisco du quartier de Chelsea.","c":"Cuisine"},{"id":"ubohtsuv","t":"Quel poisson à chair rose est le plus souvent servi fumé, avec des blinis ou des toasts ?","r":["Le saumon","Le hareng","Le maquereau","Le cabillaud"],"b":0,"a":"Le saumon sauvage doit sa chair rose aux petits crustacés dont il se nourrit, riches en pigments.","c":"Cuisine"},{"id":"am02kr1s","t":"Quelle marmite lourde, souvent en fonte émaillée, mijote plats et ragoûts avec son couvercle ?","r":["La cocotte","La sauteuse","La poêle","Le wok"],"b":0,"a":"En fonte, elle garde longtemps la chaleur, au four comme sur le feu.","c":"Cuisine"},{"id":"p1u54x5z","t":"Comment les Allemands appellent-ils le chou fermenté que les Alsaciens nomment choucroute ?","r":["Sauerkraut","Spätzle","Bratwurst","Strudel"],"b":0,"a":"Le mot allemand signifie « chou aigre » : c'est la fermentation lactique qui lui donne son acidité.","c":"Cuisine"},{"id":"td6b3vz9","t":"Les champs de lavande donnent un miel réputé : de quelle région française vient-il surtout ?","r":["L'Alsace","La Bretagne","La Normandie","La Provence"],"b":3,"a":"Les apiculteurs déplacent leurs ruches au plus près des champs en fleurs, en plein été : c'est la transhumance.","c":"Cuisine"},{"id":"90x4y3h4","t":"Quel dessert aux fruits est recouvert d'une pâte sableuse émiettée, faite de beurre, de sucre et de farine ?","r":["Le clafoutis","Le crumble","Le chausson","La charlotte"],"b":1,"a":"Le crumble serait né en Angleterre pendant la Seconde Guerre mondiale, quand le rationnement rendait la pâte à tarte trop coûteuse.","c":"Cuisine"},{"id":"cc9j1epw","t":"Avec quel légume fait-on les chips classiques ?","r":["Carotte","Pomme de terre","Betterave","Courgette"],"b":1,"a":"Selon la légende, les chips naissent en 1853 dans un restaurant de l'État de New York, d'un client qui trouvait les frites trop épaisses.","c":"Cuisine"},{"id":"i3phyrm8","t":"Quel fromage auvergnat à pâte pressée non cuite porte le même nom qu'un département ?","r":["Le salers","Le laguiole","Le cantal","Le bleu d'Auvergne"],"b":2,"a":"C'est l'un des plus anciens fromages de France, dit-on : on le fabriquait déjà à l'époque gallo-romaine.","c":"Cuisine"},{"id":"wrcq6vbb","t":"De quel pays viennent les tacos, galettes de maïs garnies et repliées ?","r":["L'Espagne","L'Argentine","Le Pérou","Le Mexique"],"b":3,"a":"Les tortillas de maïs existaient bien avant l'arrivée des Espagnols au XVIe siècle.","c":"Cuisine"},{"id":"xf2v3cl5","t":"Quel degré de cuisson désigne une viande à peine saisie, rouge et presque crue à cœur ?","r":["Saignant","À point","Bleu","Bien cuit"],"b":2,"a":"Pour un steak bleu, quelques dizaines de secondes par face suffisent : l'intérieur reste froid ou à peine tiède.","c":"Cuisine"},{"id":"iqkslnss","t":"Comment appelle-t-on un mélange de légumes coupés en petits dés, souvent servi froid avec de la mayonnaise ?","r":["Une ratatouille","Une jardinière","Une macédoine","Une piperade"],"b":2,"a":"Le mot viendrait de la Macédoine antique, région où se mêlaient de nombreux peuples, comme les légumes dans le plat.","c":"Cuisine"},{"id":"r6is6kxt","t":"Quel légume orange compose la garniture de la pumpkin pie, tarte servie à Thanksgiving aux États-Unis ?","r":["La carotte","La citrouille","La patate douce","Le panais"],"b":1,"a":"Aux États-Unis, la purée de citrouille se vend en boîte, toute prête, pour garnir cette tarte épicée à la cannelle et à la muscade.","c":"Cuisine"},{"id":"8hbm9jcj","t":"Quelle plante aromatique parfume le thé traditionnellement servi au Maroc ?","r":["Verveine","Menthe","Sauge","Thym"],"b":1,"a":"Au Maroc, le thé se verse de haut pour le faire mousser dans les petits verres.","c":"Cuisine"}],"moyen":[{"id":"berdjknc","t":"Quel fromage crémeux italien entre dans la crème du tiramisu ?","r":["La ricotta","Le mascarpone","La mozzarella","Le gorgonzola"],"b":1,"a":"Tiramisù signifie « tire-moi vers le haut » en italien.","c":"Cuisine"},{"id":"zx8vhtyh","t":"Que signifie « émincer » un légume ?","r":["Le réduire en purée","Le couper en tranches fines","Le peler à vif","Le couper en gros cubes"],"b":1,"a":"On émince oignons, champignons ou poivrons pour qu'ils cuisent vite et de façon régulière.","c":"Cuisine"},{"id":"a1yneh4i","t":"Quel auteur des « Trois Mousquetaires » a laissé un « Grand Dictionnaire de cuisine », publié après sa mort ?","r":["Victor Hugo","Alexandre Dumas","Émile Zola","Honoré de Balzac"],"b":1,"a":"Grand gourmand, Dumas y rassemble recettes et souvenirs de table ; l'ouvrage paraît en 1873, trois ans après sa mort.","c":"Cuisine"},{"id":"xzb5cyzd","t":"Quel pain plat, cuit dans un four tandoor, accompagne les currys indiens ?","r":["Le naan","La pita","La tortilla","Le lavash"],"b":0,"a":"Naan vient du mot persan qui signifie « pain ».","c":"Cuisine"},{"id":"prfw0y79","t":"La bisque est un potage velouté préparé à base de quoi ?","r":["Champignons","Poissons de roche","Crustacés","Légumes verts"],"b":2,"a":"Homard, langoustine ou écrevisse : on fait souvent revenir leurs carapaces pour donner tout son goût à la bisque.","c":"Cuisine"},{"id":"mvnz9nfq","t":"Dans quelle ville américaine le pharmacien John Pemberton a-t-il inventé le Coca-Cola en 1886 ?","r":["Atlanta","New York","Chicago","La Nouvelle-Orléans"],"b":0,"a":"La boisson fut d'abord vendue comme tonique, au verre, à la fontaine d'une pharmacie.","c":"Cuisine"},{"id":"pb3quikw","t":"Quel gâteau japonais en forme de poisson est fourré de pâte de haricots rouges ?","r":["Le dorayaki","Le dango","Le taiyaki","Le daifuku"],"b":2,"a":"Son nom signifie « daurade grillée » : la daurade est un poisson de bon augure au Japon.","c":"Cuisine"},{"id":"qaa20d6x","t":"De quel pays viennent les pierogi, raviolis pochés fourrés notamment de pommes de terre et de fromage ?","r":["Russie","Hongrie","Pologne","Roumanie"],"b":2,"a":"On les sert aussi sucrés, garnis de fruits rouges, et en Pologne on les mange traditionnellement à Noël.","c":"Cuisine"},{"id":"5tl3snz1","t":"De quel pays viennent les suya, brochettes de bœuf épicées saupoudrées d'un mélange à base de cacahuètes pilées ?","r":["Le Kenya","Le Sénégal","La Côte d'Ivoire","Le Nigeria"],"b":3,"a":"Ce mélange d'épices s'appelle le yaji ; les brochettes se vendent surtout le soir.","c":"Cuisine"},{"id":"0e6bsrme","t":"Quel fromage de la montagne vosgienne, à croûte orangée lavée, se déguste volontiers avec du cumin ?","r":["Le maroilles","Le munster","Le livarot","Le langres"],"b":1,"a":"Son nom viendrait du latin monasterium : ce sont des moines qui l'auraient fait connaître dans la vallée.","c":"Cuisine"},{"id":"savy9wmi","t":"De quelle céréale sont faites les nouilles udon japonaises, épaisses et blanches ?","r":["Le riz","Le blé","Le sarrasin","Le maïs"],"b":1,"a":"Les soba, des nouilles plus fines et plus sombres, sont faites de sarrasin.","c":"Cuisine"},{"id":"1nest9fq","t":"Quelle cuisson, venue d'Espagne, saisit viandes, poissons et légumes sur une plaque métallique très chaude ?","r":["La cuisson à la papillote","La cuisson à la plancha","La cuisson en cocotte","La cuisson au bain-marie"],"b":1,"a":"On l'utilise avec très peu de matière grasse, ce qui en fait une cuisson réputée légère.","c":"Cuisine"},{"id":"wmhumqdt","t":"Dans quelle ville italienne est né le panettone, brioche haute aux fruits confits servie à Noël ?","r":["Turin","Rome","Naples","Milan"],"b":3,"a":"On le laisse refroidir la tête en bas, suspendu, pour qu'il ne s'affaisse pas.","c":"Cuisine"},{"id":"uyz5j1rv","t":"Comment appelle-t-on de tout petits dés de légumes, réguliers, qui servent de base à une farce ou à une sauce ?","r":["La julienne","La chiffonnade","La brunoise","La paysanne"],"b":2,"a":"Les légumes en brunoise cuisent vite et fondent dans la sauce ou la farce.","c":"Cuisine"},{"id":"5a8q8nui","t":"Quel dessert italien consiste à verser un espresso chaud sur une boule de glace à la vanille ?","r":["Le semifreddo","La granita","L'affogato","La cassata"],"b":2,"a":"Affogato signifie « noyé » en italien : la glace est noyée dans le café.","c":"Cuisine"},{"id":"zz7hu1k1","t":"Quel fin biscuit aux amandes effilées, courbé sur un rouleau à la sortie du four, doit son nom à un élément de toiture ?","r":["Langue de chat","Palmier","Cigarette russe","Tuile"],"b":3,"a":"On le courbe tant qu'il est encore chaud et souple : en refroidissant, il durcit et garde sa forme arrondie.","c":"Cuisine"},{"id":"vaax08jk","t":"Dans quelle ville le chef Yotam Ottolenghi, né à Jérusalem, a-t-il ouvert ses restaurants ?","r":["New York","Tel-Aviv","Paris","Londres"],"b":3,"a":"Il a écrit avec Sami Tamimi un livre de cuisine intitulé « Jerusalem », hommage à leur ville natale.","c":"Cuisine"},{"id":"mqyev0vp","t":"Combien de litres de sève d'érable faut-il en moyenne pour obtenir un litre de sirop d'érable ?","r":["10 L","20 L","40 L","100 L"],"b":2,"a":"La sève est récoltée à la fin de l'hiver, quand les nuits gèlent et que les jours se réchauffent.","c":"Cuisine"},{"id":"o5tlu3tv","t":"Combien de desserts compte la tradition provençale de Noël ?","r":["Sept","Neuf","Douze","Treize"],"b":3,"a":"Le chiffre rappelle Jésus et ses douze apôtres ; on y trouve des fruits secs, des nougats et la pompe à l'huile.","c":"Cuisine"},{"id":"hcxqkj09","t":"Quelle île de Charente-Maritime produit une pomme de terre primeur protégée par une AOP ?","r":["Oléron","Île de Ré","Île d'Aix","Île Madame"],"b":1,"a":"L'île de Ré est aussi connue pour ses ânes en culotte, vêtus autrefois de pantalons de toile contre les insectes.","c":"Cuisine"},{"id":"mvp8wa21","t":"Quel fromage du Jura est traversé en son milieu par une fine ligne sombre de cendre ?","r":["Le morbier","Le mont-d'or","La cancoillotte","Le bleu de Gex"],"b":0,"a":"À l'origine, la cendre séparait le caillé du matin de celui du soir, que les fromagers moulaient ensemble.","c":"Cuisine"},{"id":"2r0ht176","t":"En quelle année la société Heinz a-t-elle commencé à vendre son ketchup ?","r":["1776","1926","1876","1956"],"b":2,"a":"Le mot ketchup viendrait d'une sauce de poisson fermenté d'Asie du Sud-Est : la tomate n'est arrivée dans la recette que bien plus tard.","c":"Cuisine"},{"id":"m8pdpaby","t":"De quel lait est faite la mozzarella di bufala de Campanie ?","r":["De bufflonne","De vache","De chèvre","De brebis"],"b":0,"a":"La mozzarella est une pâte filée : le caillé, plongé dans l'eau chaude, est étiré puis façonné à la main.","c":"Cuisine"},{"id":"4gctdlvl","t":"Comment appelle-t-on l'écumoire en fils métalliques tissés en toile, qui sort les aliments d'un bain de friture ?","r":["Une mandoline","Une louche","Une araignée","Une passette"],"b":2,"a":"Très utilisée en cuisine asiatique, l'araignée accompagne souvent le wok pour sortir beignets et nouilles.","c":"Cuisine"}],"difficile":[{"id":"hy9ht4bf","t":"Quel roi de Pologne, exilé en Lorraine au XVIIIe siècle, est lié à la naissance du baba, gâteau levé imbibé de sirop ?","r":["Auguste II le Fort","Jean III Sobieski","Casimir III le Grand","Stanislas Leszczynski"],"b":3,"a":"Selon la tradition, il aurait baptisé son gâteau Ali Baba, du nom du héros des Mille et Une Nuits, son livre préféré.","c":"Cuisine"},{"id":"x5ngb1mq","t":"De quelle région de l'Inde vient la dosa, grande crêpe fine de riz et de lentilles fermentés ?","r":["Pendjab","Cachemire","Bengale","Inde du Sud"],"b":3,"a":"Garnie de pommes de terre aux épices, elle devient la masala dosa. On la sert avec du sambar et du chutney de noix de coco.","c":"Cuisine"},{"id":"ct2f8559","t":"De quel pays vient le bulgogi, émincé de bœuf mariné dans de la sauce soja et grillé ?","r":["Japon","Corée du Sud","Chine","Thaïlande"],"b":1,"a":"Son nom coréen signifie « viande au feu » ; on le grille souvent à table puis on l'enroule dans une feuille de laitue.","c":"Cuisine"},{"id":"laqhbypk","t":"Quel ustensile conique à mailles très fines sert à filtrer sauces et bouillons ?","r":["La passoire","Le chinois","L'écumoire","Le tamis"],"b":1,"a":"Sa forme pointue rappelle un chapeau conique asiatique, d'où son nom.","c":"Cuisine"},{"id":"qftuiufr","t":"La cuisine « jerk », marinade très épicée pour griller le poulet ou le porc, est emblématique de quelle île ?","r":["Cuba","Jamaïque","Haïti","Barbade"],"b":1,"a":"Le jerk tire sa chaleur du piment scotch bonnet et son parfum du piment de la Jamaïque, une baie aux notes de girofle et de cannelle.","c":"Cuisine"},{"id":"pg47j3og","t":"Quelle ville produit les quernons d'ardoise, chocolats bleus imitant l'ardoise ?","r":["Nantes","Angers","Tours","Saumur"],"b":1,"a":"La couleur rappelle les ardoisières de Trélazé, près de la ville, qui ont couvert les toits de toute la région.","c":"Cuisine"},{"id":"nsf9zshu","t":"Quel ingrédient colore en noir certaines pâtes et certains risottos italiens ?","r":["La truffe noire","L'encre de seiche","L'olive noire","Le charbon végétal"],"b":1,"a":"En Espagne, la même encre teint l'arroz negro, un riz aux fruits de mer de la région de Valence.","c":"Cuisine"},{"id":"9rg1xxgs","t":"De quel pays la Vegemite, pâte salée à base d'extrait de levure que l'on tartine sur du pain beurré, est-elle originaire ?","r":["Nouvelle-Zélande","Afrique du Sud","Canada","Australie"],"b":3,"a":"Elle a été créée en 1922 par le chimiste Cyril Callister, à Melbourne, à partir de levure de bière.","c":"Cuisine"},{"id":"ks749w95","t":"Quelle presqu'île de la rade de Brest est célèbre pour ses fraises ?","r":["Quiberon","Plougastel","Crozon","Rhuys"],"b":1,"a":"Un ingénieur-marin, Frézier, rapporta du Chili en 1714 des plants de fraisier, dont est née la fraise moderne.","c":"Cuisine"},{"id":"clthcno7","t":"Qui a remporté la première saison de Top Chef, diffusée sur M6 en 2010 ?","r":["Jean Imbert","Naoëlle D'Hainaut","Mallory Gabsi","Romain Tischenko"],"b":3,"a":"L'émission est adaptée du concours américain Top Chef.","c":"Cuisine"},{"id":"njjdgess","t":"Sous quel autre nom connaît-on le fruit du dragon, à peau rose et chair piquetée de graines noires ?","r":["Ramboutan","Carambole","Pitaya","Litchi"],"b":2,"a":"Il pousse sur des cactus grimpants originaires d'Amérique, dont les fleurs ne s'ouvrent que la nuit.","c":"Cuisine"},{"id":"9csn6opk","t":"De quel pays viennent les buuz, raviolis cuits à la vapeur, farcis de mouton haché, servis en masse pour le Nouvel An lunaire ?","r":["Le Kazakhstan","L'Ouzbékistan","La Mongolie","La Corée du Sud"],"b":2,"a":"On les prépare en grandes quantités avant la fête du Nouvel An lunaire, qu'on appelle là-bas Tsagaan Sar, la « Lune blanche ».","c":"Cuisine"},{"id":"8znl5lnr","t":"Quel restaurant parisien, qui domine la Seine face à Notre-Dame, numérote chaque canard qu'il sert ?","r":["La Tour d'Argent","Le Grand Véfour","Lasserre","Maxim's"],"b":0,"a":"Chaque client reçoit une carte portant le numéro de son canard.","c":"Cuisine"},{"id":"gexj9qg9","t":"Quel fromage AOP du pays de Bray est souvent façonné en forme de cœur ?","r":["Le neufchâtel","Le livarot","Le pont-l'évêque","Le camembert"],"b":0,"a":"La légende veut que des jeunes filles normandes l'aient offert en cœur aux soldats anglais pendant la guerre de Cent Ans.","c":"Cuisine"},{"id":"omeqaqyt","t":"Quel nom japonais le chimiste Kikunae Ikeda a-t-il donné en 1908 à la saveur du glutamate ?","r":["Umami","Kokumi","Shibui","Amai"],"b":0,"a":"Ikeda l'a découverte dans le bouillon d'algue kombu ; l'umami est reconnu comme cinquième saveur de base.","c":"Cuisine"},{"id":"i0kanab3","t":"Dans quel pays est né le havarti, fromage à pâte pressée aux petits trous irréguliers ?","r":["Suède","Pays-Bas","Norvège","Danemark"],"b":3,"a":"Sa recette a été mise au point au XIXe siècle sur une ferme nommée Havarti.","c":"Cuisine"},{"id":"3otdmhwu","t":"Quelle molécule donne leur piquant aux piments ?","r":["La pipérine","L'allicine","La capsaïcine","Le gingérol"],"b":2,"a":"L'échelle de Scoville mesure cette molécule, que les oiseaux ne ressentent pas, ce qui aide les piments à disséminer leurs graines.","c":"Cuisine"},{"id":"2m77pv3k","t":"De quelle cuisine régionale chinoise viennent les dim sum, petites bouchées cuites à la vapeur ?","r":["La cuisine sichuanaise","La cuisine cantonaise","La cuisine pékinoise","La cuisine hunanaise"],"b":1,"a":"On les sert dans des paniers de bambou avec du thé, lors d'un repas que l'on appelle « yum cha ».","c":"Cuisine"},{"id":"2sx5svn4","t":"Quelle vallée de Haute-Savoie, proche de la Suisse, a donné son nom à un fromage et à une race bovine ?","r":["La vallée du Giffre","La vallée de Chamonix","Le val d'Abondance","La vallée de l'Arve"],"b":2,"a":"La vache d'abondance, rousse à tête blanche, est originaire de cette même vallée.","c":"Cuisine"},{"id":"6xg2yqjc","t":"Quelle ville bretonne, sur la baie du Mont-Saint-Michel, est célèbre pour ses huîtres creuses dégustées sur le port ?","r":["Saint-Malo","Dinard","Cancale","Paimpol"],"b":2,"a":"Le port de la Houle, à Cancale, accueille des étals où l'on déguste les huîtres face à la baie.","c":"Cuisine"}]},"Jeux & pop culture":{"facile":[{"id":"ofbnc74i","t":"Quel vêtement traditionnel japonais, en forme de T, se croise sur le devant et se tient par une ceinture ?","r":["Le hanbok","Le kimono","Le qipao","Le sari"],"b":1,"a":"Un kimono se croise toujours le pan gauche sur le pan droit : l'inverse est réservé à l'habillage des défunts.","c":"Jeux & pop culture"},{"id":"kvmrlpqy","t":"Dans quelle série deux agents du FBI enquêtent-ils sur des dossiers classés « paranormaux » ?","r":["Lost","X-Files","Heroes","Prison Break"],"b":1,"a":"La série, créée par Chris Carter en 1993, avait pour slogan « La vérité est ailleurs ».","c":"Jeux & pop culture"},{"id":"1zjgclcd","t":"Quel accessoire, passé sur les épaules, retient un pantalon à la place d'une ceinture ?","r":["Foulard","Gilet","Bretelles","Nœud papillon"],"b":2,"a":"Les bretelles se fixent au pantalon par des boutons ou par des pinces métalliques.","c":"Jeux & pop culture"},{"id":"dagq3x5y","t":"Quelle coiffe de laine feutrée, ronde et plate, est associée au Béarn et au Pays basque ?","r":["Le chapeau melon","Le bonnet phrygien","Le béret","La casquette"],"b":2,"a":"Un musée du Béret existe à Nay, dans les Pyrénées-Atlantiques.","c":"Jeux & pop culture"},{"id":"gbejk2jh","t":"Quel sport pratique-t-on dans la série de jeux Tony Hawk's Pro Skater ?","r":["Le surf","Le BMX","Le roller","Le skateboard"],"b":3,"a":"Tony Hawk, qui prête son nom à la série, est un skateur américain célèbre pour avoir réussi le premier « 900 », une rotation de deux tours et demi.","c":"Jeux & pop culture"},{"id":"4ph54q7z","t":"De quelle couleur est la salopette de Mario dans ses jeux récents ?","r":["Rouge","Bleue","Verte","Jaune"],"b":1,"a":"Mario doit sa moustache aux limites des premiers graphismes : il était plus simple de dessiner une moustache qu'une bouche avec si peu de pixels.","c":"Jeux & pop culture"},{"id":"a3ssdxv0","t":"Dans Mario Kart, quel objet glissant peut-on laisser derrière soi pour faire déraper ses poursuivants ?","r":["Une étoile","Une peau de banane","Un champignon","Une pièce"],"b":1,"a":"Dans la série, un pilote touché par une carapace ou qui roule sur une peau de banane perd de précieuses secondes en tournoyant.","c":"Jeux & pop culture"},{"id":"0hgbrv4b","t":"Comment s'appelle le héros en tunique verte de la série The Legend of Zelda ?","r":["Zelda","Ganon","Link","Navi"],"b":2,"a":"Beaucoup de gens croient que le héros s'appelle Zelda, alors que c'est le nom de la princesse.","c":"Jeux & pop culture"},{"id":"m5tpo1oc","t":"Quelle entreprise édite le navigateur web Safari ?","r":["Google","Apple","Microsoft","Mozilla"],"b":1,"a":"Safari est fondé sur le moteur WebKit, dérivé du moteur KHTML.","c":"Jeux & pop culture"},{"id":"nwdh0q6m","t":"De combien de fragments se compose la Triforce dans la série Zelda ?","r":["Deux","Quatre","Trois","Cinq"],"b":2,"a":"Ces trois fragments incarnent le courage, la sagesse et la puissance.","c":"Jeux & pop culture"},{"id":"xvld2b9f","t":"En quelle année est sortie la Nintendo Switch ?","r":["2015","2016","2017","2018"],"b":2,"a":"Hybride, elle se joue branchée à la télévision ou en mode portable.","c":"Jeux & pop culture"},{"id":"4xhb7583","t":"Quel chanteur américain est surnommé « le Roi de la pop » ?","r":["Prince","Elvis Presley","Michael Jackson","Stevie Wonder"],"b":2,"a":"Son album Thriller compte parmi les plus vendus de l'histoire de la musique.","c":"Jeux & pop culture"},{"id":"cv7pwse4","t":"Quel vêtement tricoté porte-t-on aux pieds, sous les souliers, pour avoir chaud ?","r":["Des gants","Des chaussettes","Un bonnet","Une écharpe"],"b":1,"a":"Les premières chaussettes tricotées à la main se sont répandues en Europe au Moyen Âge, bien avant les machines à tricoter.","c":"Jeux & pop culture"},{"id":"bgg0n15j","t":"La famille Grimaldi règne sur quelle principauté ?","r":["Andorre","Liechtenstein","Luxembourg","Monaco"],"b":3,"a":"Selon la tradition, François Grimaldi aurait pris le rocher de Monaco en 1297 déguisé en moine, d'où les moines du blason.","c":"Jeux & pop culture"},{"id":"8wku8na2","t":"Combien de badges d'arène faut-il généralement réunir pour défier la Ligue Pokémon ?","r":["Quatre","Six","Huit","Dix"],"b":2,"a":"Dans les premiers jeux, chaque badge est remis par un champion d'arène vaincu.","c":"Jeux & pop culture"},{"id":"9ub4apc3","t":"Dans quel jeu un joueur aux yeux bandés cherche-t-il à attraper les autres et à deviner qui il a touché ?","r":["Colin-maillard","Cache-cache","Chat perché","Un, deux, trois, soleil"],"b":0,"a":"En anglais, on l'appelle « blind man's buff ».","c":"Jeux & pop culture"},{"id":"258ix3sg","t":"Quel sac, muni de deux bretelles, se porte sur le dos par les écoliers et les randonneurs ?","r":["La pochette","La besace","Le sac à dos","Le cabas"],"b":2,"a":"Les écoliers d'autrefois portaient un cartable de cuir à la main ou sur le dos, bien avant les modèles en toile.","c":"Jeux & pop culture"},{"id":"3xfmbo3p","t":"Combien d'espèces de Pokémon la première génération comptait-elle ?","r":["100","150","151","251"],"b":2,"a":"Le 151e, Mew, a été ajouté en toute fin de développement des premiers jeux, sortis en 1996 au Japon.","c":"Jeux & pop culture"},{"id":"8r24n6w6","t":"Quel jouet articulé, dont chaque membre est relié à une croix de bois par des cordelettes, s'anime d'en haut ?","r":["La marionnette à fils","La marotte","La poupée gigogne","Le pantin à ressort"],"b":0,"a":"Le mot « marionnette » vient de Marion, un diminutif de Marie.","c":"Jeux & pop culture"},{"id":"eb47zi6u","t":"Quel est le prénom du fils cadet du roi Charles III et de la princesse Diana ?","r":["Harry","Andrew","Edward","George"],"b":0,"a":"Son prénom officiel est Henry ; Harry n'en est que le diminutif usuel.","c":"Jeux & pop culture"},{"id":"xistxj5t","t":"Dans Koh-Lanta, comment s'appelle le moment où les aventuriers votent pour éliminer l'un des leurs ?","r":["Le tribunal","Le jugement","Le verdict","Le conseil"],"b":3,"a":"Le jeu tient son nom d'une île de Thaïlande où a été tournée la première saison.","c":"Jeux & pop culture"},{"id":"p3smurl2","t":"Dans quel pays la télévision en couleur a-t-elle commencé à émettre régulièrement en 1954 ?","r":["France","États-Unis","Royaume-Uni","Japon"],"b":1,"a":"Les premiers postes couleur coûtaient très cher et peu de foyers pouvaient s'en offrir.","c":"Jeux & pop culture"},{"id":"j594lqgg","t":"Dans quel jeu d'adresse faut-il retirer des baguettes d'un tas sans faire bouger les autres ?","r":["Le Jenga","Le Mölkky","Le bilboquet","Le mikado"],"b":3,"a":"Son nom est un mot japonais qui désignait l'empereur du Japon.","c":"Jeux & pop culture"},{"id":"72cu8pq8","t":"Quel jouet fait de deux cônes réunis se lance et se rattrape avec une corde tendue entre deux baguettes ?","r":["Le yo-yo","Le bilboquet","La toupie","Le diabolo"],"b":3,"a":"Il a connu une vogue énorme en France au début du XXe siècle.","c":"Jeux & pop culture"}],"moyen":[{"id":"a9ny0s5s","t":"Quel animateur a lancé le talk-show « Ciel, mon mardi ! » sur TF1 en 1988 ?","r":["Thierry Ardisson","Jean-Luc Delarue","Christophe Dechavanne","Arthur"],"b":2,"a":"L'émission, en direct, mêlait débats de société et témoignages du public.","c":"Jeux & pop culture"},{"id":"ewvt9j7n","t":"Quel animateur a longtemps présenté Motus, jeu de lettres de France 2 ?","r":["Julien Lepers","Thierry Beccaro","Laurent Ruquier","Patrice Laffont"],"b":1,"a":"Motus est l'adaptation française du jeu américain Lingo, où l'on devine un mot lettre après lettre.","c":"Jeux & pop culture"},{"id":"9kj5f26y","t":"Dans quelle ville de Californie le parc Disneyland a-t-il ouvert ses portes en 1955 ?","r":["Los Angeles","Burbank","San Diego","Anaheim"],"b":3,"a":"Walt Disney y avait acheté des orangeraies pour bâtir son parc.","c":"Jeux & pop culture"},{"id":"amocnq9h","t":"Quel appareil optique du XVIIe siècle projetait des images peintes sur verre, ancêtre du projecteur de cinéma ?","r":["La chambre noire","Le praxinoscope","La lanterne magique","Le stéréoscope"],"b":2,"a":"On l'attribue souvent au Néerlandais Christiaan Huygens ; elle servit longtemps aux spectacles de fantasmagorie.","c":"Jeux & pop culture"},{"id":"qnciifhy","t":"Combien de jours la première saison de Loft Story a-t-elle duré sur M6, au printemps 2001 ?","r":["50 jours","70 jours","100 jours","30 jours"],"b":1,"a":"Les candidats vivaient filmés en permanence dans une maison de la banlieue parisienne.","c":"Jeux & pop culture"},{"id":"6hduffp3","t":"Que signifie le sigle GIF, format d'images souvent animées ?","r":["Graphic Image Format","General Image File","Global Interchange Format","Graphics Interchange Format"],"b":3,"a":"Le format a été créé en 1987 par Steve Wilhite, chez CompuServe.","c":"Jeux & pop culture"},{"id":"x8dzsfzn","t":"Dans le sigle GAFA, quelle entreprise désigne la seconde lettre A, celle de la fin ?","r":["Apple","Airbnb","Alibaba","Amazon"],"b":3,"a":"Le sigle est devenu GAFAM quand on y a ajouté Microsoft.","c":"Jeux & pop culture"},{"id":"jee5z2ne","t":"Quel chercheur britannique a inventé le World Wide Web en 1989, au CERN ?","r":["Vint Cerf","Bob Kahn","Marc Andreessen","Tim Berners-Lee"],"b":3,"a":"Le CERN a rendu le Web libre de droits en 1993, ce qui a favorisé sa diffusion mondiale.","c":"Jeux & pop culture"},{"id":"hapaj9xv","t":"En quelle année la PlayStation 4 est-elle sortie, en Amérique du Nord comme en Europe ?","r":["2011","2012","2013","2014"],"b":2,"a":"Elle succède à la PlayStation 3, lancée en 2006.","c":"Jeux & pop culture"},{"id":"dd1u5wku","t":"Quel humoriste a lancé en 2006, sur Canal+, un « Comedy Club » portant son prénom, tremplin pour jeunes comiques ?","r":["Gad Elmaleh","Dany Boon","Jamel Debbouze","Kev Adams"],"b":2,"a":"Il a aussi fondé le festival Marrakech du rire, créé en 2011.","c":"Jeux & pop culture"},{"id":"50ihb9xx","t":"Dans quelle ville se déroule le feuilleton « Plus belle la vie » ?","r":["Toulon","Marseille","Nice","Montpellier"],"b":1,"a":"L'action se déroule dans le Mistral, un quartier inventé pour la série.","c":"Jeux & pop culture"},{"id":"u4pa7jf0","t":"Comment appelle-t-on la marionnette qu'on enfile comme un gant pour l'animer avec les doigts ?","r":["Marionnette à fils","Marionnette à gaine","Marionnette à tringle","Marionnette sur table"],"b":1,"a":"Guignol est une marionnette à gaine : l'index du marionnettiste tient la tête, le pouce et le majeur font les bras.","c":"Jeux & pop culture"},{"id":"5emrspqr","t":"Combien de jetons portant la lettre E compte un jeu de Scrabble en français ?","r":["10","12","15","20"],"b":2,"a":"Lettre la plus fréquente du français, le E ne rapporte qu'un point.","c":"Jeux & pop culture"},{"id":"qm478jfv","t":"Combien de petites facettes colorées compte en tout un Rubik's Cube classique de 3 × 3 × 3 ?","r":["48","54","64","72"],"b":1,"a":"Il a été démontré en 2010 qu'on peut toujours résoudre le cube en vingt mouvements au plus.","c":"Jeux & pop culture"},{"id":"1cohgnsj","t":"Sur quelle chaîne le concours de pâtisserie Le Meilleur Pâtissier est-il né en France, en 2012 ?","r":["TF1","M6","France 2","France 3"],"b":1,"a":"L'émission est adaptée de The Great British Bake Off, concours de pâtisserie très populaire au Royaume-Uni.","c":"Jeux & pop culture"},{"id":"nhecgglx","t":"Dans un message en français, que signifie l'abréviation « PTDR » ?","r":["Pété de rire","Pas trop de risque","Pour toi, de rien","Prêt tout de suite"],"b":0,"a":"PTDR est une surenchère de MDR, « mort de rire », l'équivalent français du LOL anglais.","c":"Jeux & pop culture"},{"id":"uh2tm00b","t":"Dans la série « Dix pour cent », quel métier exercent les héros ?","r":["Agents d'acteurs","Avocats d'affaires","Producteurs de films","Directeurs de casting"],"b":0,"a":"Dans chaque épisode, une vedette du cinéma français joue son propre rôle, comme Isabelle Adjani ou Jean Dujardin.","c":"Jeux & pop culture"},{"id":"l4krwdtk","t":"Comment s'appelle la propriété de Memphis où a vécu Elvis Presley ?","r":["Neverland","Graceland","Rosewood","Highgrove"],"b":1,"a":"La demeure a été ouverte au public en 1982 et attire encore de nombreux fans.","c":"Jeux & pop culture"},{"id":"30f2954w","t":"Quel journaliste a présenté le journal de 13 heures de TF1 de 1988 à 2020 ?","r":["Patrick Poivre d'Arvor","Claire Chazal","Bruno Masure","Jean-Pierre Pernaut"],"b":3,"a":"Il a fait du 13 heures un rendez-vous tourné vers les régions et le quotidien.","c":"Jeux & pop culture"},{"id":"5dwt3st2","t":"Combien de jetons, jaunes et rouges réunis, contient une boîte de Puissance 4 ?","r":["36 jetons","40 jetons","42 jetons","48 jetons"],"b":2,"a":"Le jeu a été commercialisé aux États-Unis par Milton Bradley sous le nom de Connect Four.","c":"Jeux & pop culture"},{"id":"jc1hj3tj","t":"Dans quel jeu télévisé américain les candidats doivent-ils formuler leurs réponses sous forme de questions ?","r":["Jeopardy!","Wheel of Fortune","Family Feud","The Price Is Right"],"b":0,"a":"En 2011, l'ordinateur Watson d'IBM y a battu deux champions humains.","c":"Jeux & pop culture"},{"id":"7ntdkj4j","t":"Quelle plateforme de partage de vidéos, fondée en France en 2005, a longtemps concurrencé YouTube ?","r":["Vimeo","Dailymotion","Metacafe","Veoh"],"b":1,"a":"Elle a été fondée à Paris, par Benjamin Bejbaum et Olivier Poitrey.","c":"Jeux & pop culture"},{"id":"ut4wreqh","t":"Quelle créatrice, surnommée « la reine du tricot », a ouvert sa boutique rue de Grenelle, à Paris, en 1968 ?","r":["Agnès b.","Nina Ricci","Sonia Rykiel","Madeleine Vionnet"],"b":2,"a":"Ses pulls rayés et ses coutures apparentes ont marqué la mode parisienne des années 1970.","c":"Jeux & pop culture"},{"id":"9z1jwnjd","t":"Dans « Les Simpson », où Homer travaille-t-il ?","r":["Dans une centrale nucléaire","Dans une brasserie","Dans une usine automobile","Dans une mine de charbon"],"b":0,"a":"Son poste de responsable de la sécurité contraste avec son incompétence, un ressort comique de nombreux épisodes.","c":"Jeux & pop culture"}],"difficile":[{"id":"m8a20gbg","t":"Sous quel nom Mario est-il apparu dans le jeu d'arcade Donkey Kong, en 1981 ?","r":["Mister Plombier","Jumpman","Petit Moustachu","Super Jim"],"b":1,"a":"Il a été rebaptisé Mario d'après Mario Segale, le propriétaire de l'entrepôt américain de Nintendo.","c":"Jeux & pop culture"},{"id":"sc1zxlmk","t":"Quel Pokémon porte le numéro 1 dans le Pokédex national ?","r":["Pikachu","Mew","Salamèche","Bulbizarre"],"b":3,"a":"Ce Pokémon de type Plante et Poison porte un bulbe sur le dos, qui s'épanouit en fleur chez Florizarre.","c":"Jeux & pop culture"},{"id":"0u11zs6e","t":"Dans Minecraft, quel boss se fabrique avec du sable des âmes et trois têtes de squelettes du Nether ?","r":["Le Warden","Le Wither","Le Ravageur","L'Ender Dragon"],"b":1,"a":"Il laisse une étoile du Nether, ingrédient indispensable pour fabriquer un phare.","c":"Jeux & pop culture"},{"id":"hexps88x","t":"Que signifie le sigle HTTP, le protocole qui transporte les pages web ?","r":["High Tech Transfer Protocol","HyperText Transmission Process","HyperText Terminal Program","HyperText Transfer Protocol"],"b":3,"a":"Ce protocole a été conçu par l'équipe de Tim Berners-Lee au CERN, en même temps que les premières pages web.","c":"Jeux & pop culture"},{"id":"sdkq57zs","t":"Comment s'appelle la formule de Scrabble où tous les joueurs jouent le même tirage, très pratiquée en club en France ?","r":["Le duplicate","Le classique","Le joker","Le topping"],"b":0,"a":"En duplicate, chacun cherche le meilleur coup possible : le hasard du tirage est le même pour tous.","c":"Jeux & pop culture"},{"id":"iranw1jh","t":"Quel est le vrai prénom du chanteur Bruno Mars ?","r":["Paul","Peter","Philip","Patrick"],"b":1,"a":"Il a choisi « Bruno » en référence au catcheur Bruno Sammartino, comme son père le surnommait enfant.","c":"Jeux & pop culture"},{"id":"z7cyzgc3","t":"Quel couturier a présenté en 1965 une collection de robes inspirées des tableaux de Piet Mondrian ?","r":["Pierre Cardin","André Courrèges","Paco Rabanne","Yves Saint Laurent"],"b":3,"a":"Ces robes aux aplats de couleurs primaires cernés de noir rendaient hommage à un peintre néerlandais.","c":"Jeux & pop culture"},{"id":"ls19hze5","t":"Dans la série « Malcolm », comment s'appelle le frère aîné envoyé en école militaire ?","r":["Reese","Dewey","Francis","Jamie"],"b":2,"a":"Malcolm, joué par Frankie Muniz, s'adresse souvent directement aux téléspectateurs en regardant la caméra.","c":"Jeux & pop culture"},{"id":"kcs8zocc","t":"En quelle année Margarete Steiff a-t-elle fondé son entreprise de jouets à Giengen ?","r":["1850","1865","1912","1880"],"b":3,"a":"Son premier succès fut un petit éléphant de feutre, conçu à l'origine comme pelote à épingles.","c":"Jeux & pop culture"},{"id":"q2fydqc6","t":"Dans quelle ville du Nord est basé Ankama, le studio créateur de Dofus ?","r":["Lille","Roubaix","Tourcoing","Valenciennes"],"b":1,"a":"Dofus est sorti en 2004 et a donné naissance à une série animée et à des bandes dessinées.","c":"Jeux & pop culture"},{"id":"n7ybpdao","t":"Quelle marque de voiture le lieutenant Columbo conduit-il dans la série qui porte son nom ?","r":["Citroën","Renault","Peugeot","Simca"],"b":2,"a":"Son cabriolet cabossé, un modèle des années 1950, est presque aussi célèbre que son imperméable froissé.","c":"Jeux & pop culture"},{"id":"uf8ttmot","t":"Quel prénom portait le boxeur Muhammad Ali à sa naissance ?","r":["Clarence","Calvin","Cornelius","Cassius"],"b":3,"a":"Il a adopté le nom de Muhammad Ali en 1964, juste après son titre mondial contre Sonny Liston.","c":"Jeux & pop culture"},{"id":"nriu54op","t":"Quel ancien Beatle a été fait chevalier par la reine Élisabeth II en 1997 ?","r":["Ringo Starr","George Harrison","Paul McCartney","John Lennon"],"b":2,"a":"Les Beatles avaient déjà reçu l'ordre de l'Empire britannique en 1965 ; la chevalerie est venue plus tard, à titre individuel.","c":"Jeux & pop culture"},{"id":"zc9c1v43","t":"En quelle année est sorti le tout premier The Legend of Zelda, au Japon ?","r":["1984","1985","1987","1986"],"b":3,"a":"La version américaine de la cartouche était dorée.","c":"Jeux & pop culture"},{"id":"dvvg2c6m","t":"Quelle chaîne privée française a cessé d'émettre en avril 1992 ?","r":["TV6","La Sept","Canal+","La Cinq"],"b":3,"a":"Son ancien canal a ensuite été repris par Arte le soir et par la Cinquième, future France 5, en journée.","c":"Jeux & pop culture"},{"id":"xoltlt1d","t":"Quel studio américain a créé le jeu de stratégie Age of Empires, sorti en 1997 ?","r":["Westwood Studios","Ensemble Studios","Firaxis","Relic Entertainment"],"b":1,"a":"Ensemble Studios, installé à Dallas, a aussi créé Age of Mythology.","c":"Jeux & pop culture"},{"id":"0fn5bhi0","t":"Dans quel pays est né l'acteur Christoph Waltz ?","r":["Allemagne","Suisse","Autriche","Belgique"],"b":2,"a":"Christoph Waltz a remporté deux Oscars du meilleur second rôle, tous deux dans des films de Quentin Tarantino.","c":"Jeux & pop culture"},{"id":"5fwy8yjv","t":"En quelle année Atari a-t-il lancé la console Jaguar ?","r":["1991","1992","1993","1995"],"b":2,"a":"Atari la présentait comme une console 64 bits, un argument très discuté.","c":"Jeux & pop culture"},{"id":"vf1qcru8","t":"Sur quelle chaîne le magazine de la mer « Thalassa » a-t-il été lancé en 1975 ?","r":["TF1","Antenne 2","FR3","La Cinq"],"b":2,"a":"Thalassa tient son nom du mot grec qui désigne la mer.","c":"Jeux & pop culture"},{"id":"zxhu0mws","t":"Quel outil, brandi par Gordon Freeman, est l'arme de mêlée emblématique de Half-Life ?","r":["Clé à molette","Pied-de-biche","Marteau","Hache"],"b":1,"a":"Le scientifique Gordon Freeman s'en sert aussi pour briser des caisses et trouver des munitions ou des soins.","c":"Jeux & pop culture"}]},"Autour de la fête":{"facile":[{"id":"54wtca6i","t":"En quelle année a eu lieu à New York le premier défilé de Thanksgiving organisé par les grands magasins Macy's ?","r":["1894","1924","1954","1984"],"b":1,"a":"Les premiers figurants étaient des animaux du zoo de Central Park ; les ballons géants ne sont apparus qu'en 1927.","c":"Autour de la fête"},{"id":"9zvr8u3a","t":"Quel signe du zodiaque correspond à une naissance le 25 janvier ?","r":["Capricorne","Verseau","Poissons","Bélier"],"b":1,"a":"Le Verseau est représenté par un personnage qui verse de l'eau d'une cruche, d'où son nom.","c":"Autour de la fête"},{"id":"nxeq8bsb","t":"Quel monument parisien s'est mis à scintiller sous un feu d'artifice géant à minuit, le soir du passage à l'an 2000 ?","r":["L'Arc de triomphe","La tour Eiffel","Le Sacré-Cœur","Notre-Dame de Paris"],"b":1,"a":"Le scintillement de la tour, prévu au départ pour les fêtes de l'an 2000, a tant plu qu'il a été rendu permanent.","c":"Autour de la fête"},{"id":"sycvb6ir","t":"Comment appelle-t-on les engagements que l'on prend en début d'année, comme faire plus de sport ?","r":["Des commandements","Des résolutions","Des prédictions","Des inventaires"],"b":1,"a":"Cette habitude de se fixer des objectifs pour l'année neuve est très ancienne : les Babyloniens faisaient déjà des promesses à leurs dieux.","c":"Autour de la fête"},{"id":"wj7am955","t":"Quel gâteau roulé en forme de tronc d'arbre est servi en dessert le soir du réveillon ?","r":["La galette","La bûche","Le paris-brest","Le baba"],"b":1,"a":"La bûche rappelle la grosse bûche que l'on brûlait autrefois dans la cheminée pendant les longues nuits d'hiver.","c":"Autour de la fête"},{"id":"9jkxosrn","t":"En quelle année l'âge de la majorité est-il passé de 21 à 18 ans en France ?","r":["1968","1974","1981","1964"],"b":1,"a":"Cette loi a été l'une des premières réformes du septennat de Valéry Giscard d'Estaing.","c":"Autour de la fête"},{"id":"dbrf6346","t":"En quelle année a été lancée l'application de rencontres Tinder ?","r":["2002","2008","2012","2016"],"b":2,"a":"Son geste emblématique, glisser vers la droite pour dire oui, a été repris par de nombreuses autres applications.","c":"Autour de la fête"},{"id":"kn3agws0","t":"Combien de mètres mesure la Sky Tower d'Auckland, d'où partent les fusées du réveillon néo-zélandais ?","r":["228 m","278 m","328 m","428 m"],"b":2,"a":"Les plus téméraires peuvent sauter du haut de la tour, retenus par des câbles.","c":"Autour de la fête"},{"id":"p2x0oan8","t":"Quelle ville américaine du Nevada est célèbre pour ses chapelles de mariages express ?","r":["Los Angeles","Las Vegas","Miami","Chicago"],"b":1,"a":"Certaines de ses chapelles proposent des cérémonies célébrées par un sosie d'Elvis Presley.","c":"Autour de la fête"},{"id":"rj52zzuh","t":"À quel doigt porte-t-on traditionnellement l'alliance en France ?","r":["L'index gauche","Le majeur droit","L'annulaire gauche","Le pouce droit"],"b":2,"a":"Les Romains croyaient qu'une veine, la vena amoris, reliait ce doigt directement au cœur.","c":"Autour de la fête"},{"id":"lwf4txue","t":"Quel fruit les enfants tentent-ils d'attraper avec les dents, dans une bassine d'eau, lors d'un jeu d'Halloween ?","r":["La poire","La pomme","L'orange","La prune"],"b":1,"a":"Ce jeu, venu des îles Britanniques, aurait servi autrefois à deviner qui se marierait dans l'année.","c":"Autour de la fête"},{"id":"awu0k8od","t":"Dans La Chenille, que pose chaque danseur sur les épaules de la personne devant lui ?","r":["Les pieds","Les coudes","Les mains","Le menton"],"b":2,"a":"La file de danseurs serpente à travers la salle, parfois jusqu'à sortir de la piste.","c":"Autour de la fête"},{"id":"t65s947x","t":"Comment appelle-t-on la célébration des 50 ans d'un événement ?","r":["Le centenaire","Le bicentenaire","Le cinquantenaire","Le tricentenaire"],"b":2,"a":"On parle de centenaire pour cent ans et de bicentenaire pour deux cents : tous ces mots viennent du latin.","c":"Autour de la fête"},{"id":"qosh7hyx","t":"Quel signe du zodiaque correspond à une naissance le 25 juin ?","r":["Gémeaux","Cancer","Lion","Vierge"],"b":1,"a":"Le Cancer est symbolisé par un crabe, celui que la déesse Héra aurait envoyé contre Héraclès.","c":"Autour de la fête"},{"id":"g556hgxo","t":"Combien de mois s'écoulent avant qu'un bébé fête son premier anniversaire ?","r":["6","9","12","18"],"b":2,"a":"Le mot « anniversaire » vient du latin anniversarius, « qui revient chaque année ».","c":"Autour de la fête"},{"id":"s3uzmzu7","t":"Combien de temps une mesure de valse compte-t-elle ?","r":["2","3","4","6"],"b":1,"a":"Née en Autriche et en Allemagne, la valse a longtemps passé pour audacieuse : on y dansait enlacés, ce que bien des salons jugeaient indécent.","c":"Autour de la fête"},{"id":"b7zlwggd","t":"Quels prêtres celtes sont associés aux rites de Samhain, ancêtre d'Halloween ?","r":["Les augures","Les druides","Les flamines","Les mages"],"b":1,"a":"Les druides ne laissaient pas d'écrits : leur savoir se transmettait oralement, parfois au prix de vingt ans d'apprentissage selon César.","c":"Autour de la fête"},{"id":"01c70k9q","t":"De quelle couleur est traditionnellement la robe de la mariée en France ?","r":["Rouge","Bleue","Blanche","Noire"],"b":2,"a":"La mode de la robe blanche s'est répandue après le mariage de la reine Victoria en 1840, qui avait choisi cette couleur.","c":"Autour de la fête"},{"id":"pxtewduu","t":"Selon la légende, dans quoi le vampire dort-il pendant la journée ?","r":["Une grotte","Un cercueil","Un puits","Une armoire"],"b":1,"a":"Dans le roman de Bram Stoker, Dracula fait transporter en Angleterre des caisses remplies de terre de son pays natal pour s'y reposer.","c":"Autour de la fête"},{"id":"rcb2b5r7","t":"Comment appelle-t-on les 50 ans de mariage ?","r":["Les noces d'or","Les noces d'argent","Les noces de diamant","Les noces de perle"],"b":0,"a":"Les noces de diamant, à soixante ans de mariage, viennent ensuite dans la tradition française.","c":"Autour de la fête"},{"id":"dq4hio0u","t":"Quel signe du zodiaque correspond à une naissance le 14 août ?","r":["Cancer","Lion","Vierge","Gémeaux"],"b":1,"a":"Le Lion couvre environ du 23 juillet au 22 août.","c":"Autour de la fête"},{"id":"r16r2aw1","t":"Chez combien de nains Blanche-Neige trouve-t-elle refuge dans la forêt, dans le conte des frères Grimm ?","r":["Cinq","Sept","Neuf","Douze"],"b":1,"a":"Les nains n'ont pas de prénoms dans le conte des Grimm ; ils furent nommés dans le film de Disney de 1937.","c":"Autour de la fête"},{"id":"zxb0sk2t","t":"En France, comment appelle-t-on le jour du saint dont on porte le prénom ?","r":["Sa naissance","Son baptême","Son jubilé","Sa fête"],"b":3,"a":"Les calendriers français indiquent un prénom pour chaque jour : on souhaite « bonne fête » aux Nicolas le 6 décembre.","c":"Autour de la fête"},{"id":"0t5kbfam","t":"Quel animal symbole du Christ prend la forme d'une figurine en beurre ou en sucre sur la table de Pâques polonaise ?","r":["Un lapin","Un agneau","Un poussin","Un coq"],"b":1,"a":"On le retrouve dans le panier que l'on fait bénir le Samedi saint, la święconka.","c":"Autour de la fête"}],"moyen":[{"id":"00pbcv7r","t":"Dans le métier de DJ, comment appelle-t-on le geste de frotter un vinyle d'avant en arrière pour produire un son rythmique ?","r":["Le sampling","Le scratch","Le mixage","Le remix"],"b":1,"a":"Le scratch est né dans le hip-hop new-yorkais des années 1970.","c":"Autour de la fête"},{"id":"heewj09n","t":"Le mot « Noël » vient du latin natalis : à quoi ce mot latin se rapporte-t-il ?","r":["À la lumière","À l'hiver","À la naissance","À la nouveauté"],"b":2,"a":"Les Romains appelaient dies natalis le jour anniversaire de la naissance, qu'ils fêtaient déjà avec des offrandes.","c":"Autour de la fête"},{"id":"9o7uozut","t":"Quel objet lumineux place-t-on à la fenêtre la nuit de Noël en Irlande, pour accueillir la Sainte Famille et les voyageurs ?","r":["Une lanterne","Une étoile de papier","Un sapin miniature","Une bougie"],"b":3,"a":"En 1990, la présidente Mary Robinson a allumé une lumière à la fenêtre de sa résidence pour penser aux Irlandais exilés.","c":"Autour de la fête"},{"id":"kwaied5r","t":"Dans le film « Casablanca », sorti en 1942, quelle actrice joue Ilsa, l'amour perdu de Rick ?","r":["Greta Garbo","Lauren Bacall","Rita Hayworth","Ingrid Bergman"],"b":3,"a":"Face à elle, Humphrey Bogart incarne Rick Blaine, patron d'un café de Casablanca pendant la Seconde Guerre mondiale.","c":"Autour de la fête"},{"id":"bvl778nl","t":"Au Seollal, le Nouvel An coréen, que font traditionnellement les enfants devant leurs aînés pour recevoir de l'argent ?","r":["Une chanson","Une profonde révérence","Un poème récité","Une danse"],"b":1,"a":"Cette révérence se nomme sebae, et l'argent remis en retour par les aînés s'appelle sebaetdon.","c":"Autour de la fête"},{"id":"u8kne4q2","t":"Quel ballet de Tchaïkovski, créé en 1892, est joué dans de nombreux théâtres à l'approche des fêtes ?","r":["Le Lac des cygnes","Casse-Noisette","La Belle au bois dormant","Giselle"],"b":1,"a":"Son héroïne, la petite Clara, reçoit un casse-noisette en cadeau le soir de Noël.","c":"Autour de la fête"},{"id":"0z6zgvc8","t":"Quelle déesse romaine est la mère de Cupidon ?","r":["Vénus","Junon","Minerve","Diane"],"b":0,"a":"Le vendredi tire son nom de Vénus : dies Veneris en latin.","c":"Autour de la fête"},{"id":"tlip0eeg","t":"Quelle femme, surnommée « la reine de la nuit », a ouvert des boîtes à Paris puis à New York ?","r":["Régine","Line Renaud","Dalida","Mireille Mathieu"],"b":0,"a":"Elle a aussi chanté : « Les Petits Papiers », écrit pour elle par Serge Gainsbourg, date de 1965.","c":"Autour de la fête"},{"id":"ooyc2yvw","t":"Comment s'appelle, dans les légendes bretonnes, le serviteur de la Mort qui conduit une charrette grinçante ?","r":["Le Korrigan","L'Ankou","Le Lutin","Le Gobelin"],"b":1,"a":"Dans la tradition, entendre grincer son essieu annonce un décès prochain.","c":"Autour de la fête"},{"id":"a21086hb","t":"Quelles nouilles mange-t-on au Japon le 31 décembre, car leur longueur évoque une longue vie ?","r":["Les udon","Les soba","Les ramen","Les somen"],"b":1,"a":"Ce repas porte le nom de toshikoshi soba, « soba du passage d'une année à l'autre ».","c":"Autour de la fête"},{"id":"48uj6jpb","t":"Quelle saga de films d'horreur met en scène Ghostface, un tueur dont le masque s'inspire du tableau « Le Cri » ?","r":["Scream","Destination finale","Souviens-toi… l'été dernier","Massacre à la tronçonneuse"],"b":0,"a":"Le premier « Scream », sorti en 1996, a été réalisé par Wes Craven, déjà père de Freddy Krueger.","c":"Autour de la fête"},{"id":"6f9ff2rg","t":"Quel couple légendaire tombe amoureux après avoir bu par erreur un philtre d'amour ?","r":["Roméo et Juliette","Lancelot et Guenièvre","Abélard et Héloïse","Tristan et Iseut"],"b":3,"a":"Le philtre était destiné à Iseut et au roi Marc, son futur époux ; la mère d'Iseut l'avait confié à la servante Brangien, qui le leur servit par erreur.","c":"Autour de la fête"},{"id":"w9j90jjw","t":"Quel signe du zodiaque correspond à une naissance le 3 octobre ?","r":["Vierge","Scorpion","Balance","Sagittaire"],"b":2,"a":"La Balance est le seul signe du zodiaque occidental représenté par un objet et non par un être vivant.","c":"Autour de la fête"},{"id":"0vy75p6y","t":"Quelle pierre précieuse verte est associée au mois de naissance de mai ?","r":["Le péridot","L'émeraude","Le jade","Le saphir"],"b":1,"a":"Cléopâtre aimait tant les émeraudes qu'elle aurait fait exploiter des mines égyptiennes pour s'en parer.","c":"Autour de la fête"},{"id":"ej4kosh2","t":"Quel ancien Beatles a chanté en 1971 « Happy Xmas (War Is Over) » ?","r":["Paul McCartney","George Harrison","Ringo Starr","John Lennon"],"b":3,"a":"Il l'a enregistrée avec Yoko Ono, dans le prolongement de leur campagne pour la paix « War Is Over! ».","c":"Autour de la fête"},{"id":"ww0bneds","t":"Dans quelle ville est née la papillote, chocolat de Noël enveloppé d'un papier qui contient une petite blague ?","r":["Bordeaux","Lille","Nancy","Lyon"],"b":3,"a":"On raconte qu'un apprenti confiseur glissait des mots doux dans les chocolats pour sa bien-aimée, d'où le papier imprimé.","c":"Autour de la fête"},{"id":"ydu6mycl","t":"Quel groupe new-yorkais a chanté « Le Freak » en 1978 ?","r":["Sister Sledge","Kool & the Gang","Chic","Earth, Wind & Fire"],"b":2,"a":"Le titre aurait été inspiré par un refus d'entrée au Studio 54 un soir de réveillon, d'après l'un de ses fondateurs.","c":"Autour de la fête"},{"id":"hula1h07","t":"Dans quel pays les « Silvesterchläuse », coiffés et couverts de grelots, vont-ils de ferme en ferme à la Saint-Sylvestre ?","r":["Autriche","Suisse","Allemagne","Liechtenstein"],"b":1,"a":"Dans l'Appenzell, on les voit aussi le 13 janvier, Saint-Sylvestre de l'ancien calendrier julien.","c":"Autour de la fête"},{"id":"ey9sp7yx","t":"Quel personnage accompagne saint Nicolas pour punir les enfants désobéissants dans l'est de la France ?","r":["Le Croque-mitaine","Le Marchand de sable","Le Père Fouettard","Le Bonhomme Sept-Heures"],"b":2,"a":"Une légende en fait un aubergiste criminel que saint Nicolas aurait condamné à l'accompagner pour toujours.","c":"Autour de la fête"},{"id":"zbcd8nwz","t":"Comment nomme-t-on l'annonce publique, affichée en mairie, d'un mariage à venir ?","r":["Les arrhes","Les accordailles","Les bans","Les épousailles"],"b":2,"a":"Autrefois, les bans étaient proclamés à l'église pour que chacun puisse signaler un empêchement au mariage.","c":"Autour de la fête"},{"id":"fftrd94u","t":"Quel signe du zodiaque correspond à une naissance le 10 octobre ?","r":["Vierge","Balance","Scorpion","Lion"],"b":1,"a":"La Balance est le seul signe du zodiaque occidental représenté par un objet.","c":"Autour de la fête"},{"id":"erna5fqd","t":"Dans les dessins animés, comment s'appelle la fiancée de Popeye ?","r":["Olive","Betty","Daisy","Minnie"],"b":0,"a":"Popeye est né en 1929 dans une bande dessinée américaine avant de devenir une vedette du dessin animé.","c":"Autour de la fête"},{"id":"ehzibmw7","t":"Que mange-t-on traditionnellement pour son anniversaire en Chine, pour souhaiter de vivre très vieux ?","r":["Des raviolis","Des nouilles longues","Du riz gluant","Des gâteaux de lune"],"b":1,"a":"Il ne faut surtout pas couper la nouille : plus elle est longue et mangée d'un seul trait, plus la vie sera longue.","c":"Autour de la fête"},{"id":"7xs6gtuw","t":"Quel groupe chante « September », tube funk et disco de 1978 qui fait lever tout un bal ?","r":["Chic","Bee Gees","Earth, Wind & Fire","Sister Sledge"],"b":2,"a":"Ses cuivres éclatants et son refrain sur le 21 septembre en font un classique des pistes de danse.","c":"Autour de la fête"}],"difficile":[{"id":"09d3v8zl","t":"Quel groupe britannique a chanté « Come On Eileen » en 1982 ?","r":["Dexys Midnight Runners","Madness","Culture Club","Duran Duran"],"b":0,"a":"Le titre a été numéro un aux États-Unis en 1983, et le clip montre le groupe en salopettes.","c":"Autour de la fête"},{"id":"ip5g7aei","t":"Quelle nymphe, condamnée à ne répéter que les derniers mots entendus, aime en vain Narcisse ?","r":["Écho","Daphné","Calypso","Aréthuse"],"b":0,"a":"Héra l'avait punie pour l'avoir distraite par ses bavardages ; consumée de chagrin, il ne reste d'elle que sa voix.","c":"Autour de la fête"},{"id":"i5p3wgc7","t":"Sous quel titre français est sorti en 1989 « National Lampoon's Christmas Vacation », avec Chevy Chase ?","r":["Super Noël","Frère Noël","Le sapin a les boules","Elfe"],"b":2,"a":"Chevy Chase y reprend le rôle de Clark Griswold, père de famille maladroit qu'il jouait déjà dans « Bonjour les vacances… ».","c":"Autour de la fête"},{"id":"dx8py32w","t":"Quelle tenue de base portent les fêtards des fêtes de Bayonne ?","r":["Du rouge avec un foulard blanc","Du bleu avec un foulard jaune","Du blanc avec une ceinture bleue","Du blanc avec un foulard rouge"],"b":3,"a":"Les fêtes de Bayonne durent cinq jours et commencent par la remise des clés de la ville au roi Léon.","c":"Autour de la fête"},{"id":"hfvm42vi","t":"Quel conteur a écrit « Le Sapin », l'histoire d'un jeune arbre impatient d'être décoré pour Noël ?","r":["Charles Perrault","Jacob Grimm","Hans Christian Andersen","Wilhelm Hauff"],"b":2,"a":"Andersen a aussi écrit « La Petite Fille aux allumettes », dont l'histoire se déroule le soir du Nouvel An.","c":"Autour de la fête"},{"id":"1v18fndh","t":"En 2012, on a célébré le 600e anniversaire de la naissance de quelle figure de l'histoire de France ?","r":["Jeanne d'Arc","Aliénor d'Aquitaine","Catherine de Médicis","Blanche de Castille"],"b":0,"a":"Jeanne d'Arc est née à Domrémy, en Lorraine, où sa maison natale se visite encore.","c":"Autour de la fête"},{"id":"oi7gabko","t":"Dans quel conte d'Andersen une jeune fille est-elle condamnée à danser sans pouvoir s'arrêter ?","r":["La Petite Sirène","Le Vilain Petit Canard","La Reine des neiges","Les Souliers rouges"],"b":3,"a":"Ce conte de 1845 a inspiré un célèbre film britannique de 1948.","c":"Autour de la fête"},{"id":"u0dpdc0n","t":"Dans le roman de l'abbé Prévost, pour quelle jeune femme le chevalier des Grieux gâche-t-il sa vie ?","r":["Manon Lescaut","Julie d'Étange","Virginie","Cécile Volanges"],"b":0,"a":"Le roman a inspiré deux opéras célèbres : Manon de Massenet et Manon Lescaut de Puccini.","c":"Autour de la fête"},{"id":"33mgezxf","t":"De quelle île caribéenne le limbo est-il originaire ?","r":["La Jamaïque","Cuba","Trinidad","La Barbade"],"b":2,"a":"Il est devenu un grand classique des animations de soirée et des villages de vacances.","c":"Autour de la fête"},{"id":"thmhriai","t":"Comment s'appelle en Belgique la brioche de Noël en forme de petit Jésus emmailloté ?","r":["Le craquelin","La cramique","Le cougnou","Le pistolet"],"b":2,"a":"On l'appelle aussi cougnolle ou cougnole ; elle est souvent décorée d'un petit sujet en terre cuite ou en sucre.","c":"Autour de la fête"},{"id":"5asfianm","t":"Dans quel pays lâche-t-on des lanternes célestes dans le ciel du village de Pingxi, lors de la fête des Lanternes ?","r":["Japon","Taïwan","Vietnam","Corée du Sud"],"b":1,"a":"On y écrit des vœux sur les lanternes avant de les laisser monter.","c":"Autour de la fête"},{"id":"3xmn9jww","t":"Quel titre, composé en 1893 par deux sœurs institutrices américaines, a donné la mélodie de « Happy Birthday to You » ?","r":["Good Night to All","Good Morning to All","Hello Everyone","Welcome to All"],"b":1,"a":"Patty et Mildred Hill l'avaient écrite pour que les enfants d'une classe se disent bonjour le matin ; les paroles d'anniversaire sont venues plus tard.","c":"Autour de la fête"},{"id":"svj5gyi9","t":"Quel jour la Russie célèbre-t-elle sa victoire de 1945 sur l'Allemagne nazie ?","r":["8 mai","9 mai","7 mai","22 juin"],"b":1,"a":"La capitulation allemande fut signée tard dans la soirée du 8 mai : à Moscou, il était déjà le 9.","c":"Autour de la fête"},{"id":"4t5f845f","t":"Dans quelle langue souhaite-t-on la bonne année en disant « S Novym godom » ?","r":["Le polonais","Le tchèque","Le russe","Le bulgare"],"b":2,"a":"En Russie, le Nouvel An est la plus grande fête de l'année : on y dresse le sapin, et Ded Moroz apporte les cadeaux.","c":"Autour de la fête"},{"id":"6mazdxor","t":"Dans « Le Rouge et le Noir » de Stendhal, quelle femme Julien Sorel séduit-il alors qu'il est précepteur de ses enfants ?","r":["Mme Arnoux","Mme de Rênal","Mme de Mortsauf","Mme de Tourvel"],"b":1,"a":"Stendhal s'est inspiré d'un fait divers réel, l'affaire Berthet, jugée à Grenoble.","c":"Autour de la fête"},{"id":"rbftwhfy","t":"Dans « Psychose » (1960) d'Alfred Hitchcock, comment s'appelle le motel tenu par Norman ?","r":["Overlook Motel","Crane Motel","Bates Motel","Phoenix Motel"],"b":2,"a":"La série « Bates Motel », diffusée de 2013 à 2017, imagine la jeunesse de Norman et de sa mère.","c":"Autour de la fête"},{"id":"qz29oqh4","t":"Aux États-Unis, comment appelle-t-on le petit gâteau qu'on laisse un bébé détruire à pleines mains à son premier anniversaire ?","r":["Cupcake","Layer cake","Smash cake","Pound cake"],"b":2,"a":"Cette tradition est devenue très populaire avec les séances photo de bébés, où l'on immortalise le gâteau réduit en miettes.","c":"Autour de la fête"},{"id":"48joz8hs","t":"Comment appelle-t-on les noces célébrées après neuf ans de mariage ?","r":["Noces de faïence","Noces de cuivre","Noces de verre","Noces de bois"],"b":0,"a":"Fragile, la faïence rappelle qu'un couple s'entretient comme un service de table.","c":"Autour de la fête"},{"id":"qy81wdqh","t":"Quel acteur d'origine hongroise a incarné le comte Dracula au cinéma en 1931 ?","r":["Boris Karloff","Béla Lugosi","Peter Lorre","Lon Chaney"],"b":1,"a":"Il est resté associé au rôle jusqu'à sa mort et fut, dit-on, enterré avec sa cape.","c":"Autour de la fête"},{"id":"1nao5rao","t":"Votre anniversaire tombe un lundi cette année. Si aucun 29 février ne s'intercale, quel jour tombera-t-il l'an prochain ?","r":["Lundi","Mardi","Mercredi","Dimanche"],"b":1,"a":"Quand un 29 février s'intercale, l'anniversaire saute deux jours : c'est pourquoi le calendrier se répète rarement à l'identique d'une année à l'autre.","c":"Autour de la fête"}]}},"mots":{"Culture générale":[{"id":"691wyaxh","t":"Quel outil indique, grâce à une petite bulle, qu'une étagère est bien horizontale ?","m":"NIVEAU","aff":"niveau","a":"La bulle flotte dans une fiole légèrement bombée remplie d'alcool, un liquide qui ne gèle pas.","c":"Culture générale"},{"id":"8bjbod4m","t":"Les Cajuns de Louisiane descendent de colons français venus de quelle région du Canada actuel ?","m":"ACADIE","aff":"Acadie","a":"Le mot « cajun » est une déformation d'« Acadien ».","c":"Culture générale"},{"id":"c22jqsnp","t":"Quelle déesse égyptienne est représentée sous les traits d'une chatte ?","m":"BASTET","aff":"Bastet","a":"Son sanctuaire de Bubastis, dans le delta du Nil, a livré d'innombrables chats momifiés.","c":"Culture générale"},{"id":"69h3cu3g","t":"Selon la légende, quel animal a allaité Romulus et Rémus ?","m":"LOUVE","aff":"louve","a":"Une célèbre statue de bronze, la Louve capitoline, conservée à Rome, représente l'animal nourrissant les jumeaux.","c":"Culture générale"},{"id":"7y9jy8gu","t":"Quel mois de l'année doit son nom au dieu romain Janus ?","m":"JANVIER","aff":"Janvier","a":"Janus, dieu des portes et des commencements, était représenté avec deux visages, l'un tourné vers le passé, l'autre vers l'avenir.","c":"Culture générale"},{"id":"ksy79fsu","t":"Comment dit-on « chaussures » en espagnol ?","m":"ZAPATOS","aff":"zapatos","a":"Le « zapateado » est une danse flamenca frappée du talon, dont le nom vient de « zapato », la chaussure.","c":"Culture générale"},{"id":"cpy6foa4","t":"De quelle matière est faite la mine d'un crayon à papier ?","m":"GRAPHITE","aff":"Graphite","a":"On parle encore de « mine de plomb » par habitude, alors que le plomb n'a jamais servi à fabriquer les crayons.","c":"Culture générale"},{"id":"v5q11kmb","t":"Quelle compagnie aérienne australienne a un kangourou pour emblème ?","m":"QANTAS","aff":"Qantas","a":"Son nom vient de Queensland and Northern Territory Aerial Services, société fondée en 1920 à Winton.","c":"Culture générale"},{"id":"io10bisv","t":"Comment surnomme-t-on la créature qui vivrait dans le loch Ness, en Écosse ?","m":"NESSIE","aff":"Nessie","a":"La « photographie du chirurgien » de 1934, la plus célèbre, a été reconnue comme un canular en 1994.","c":"Culture générale"},{"id":"eg51ciu7","t":"Quel médecin est spécialiste des bébés et des enfants ?","m":"PEDIATRE","aff":"pédiatre","a":"Le mot vient du grec « pais, paidos », l'enfant, que l'on retrouve aussi dans « pédagogie ».","c":"Culture générale"},{"id":"9wfw3ke0","t":"Quelle déesse grecque des moissons et de l'agriculture est la mère de Perséphone ?","m":"DEMETER","aff":"Déméter","a":"Les Romains l'honoraient sous le nom de Cérès, d'où vient le mot « céréale ».","c":"Culture générale"},{"id":"uvjavhmb","t":"Que veut dire « sobrino » en espagnol ?","m":"NEVEU","aff":"Neveu","a":"Au pluriel, « sobrinos » désigne les neveux et les nièces, comme « hijos » désigne fils et filles.","c":"Culture générale"}],"Histoire":[{"id":"4baekb7n","t":"Quel titre porte le souverain du Japon ?","m":"EMPEREUR","aff":"Empereur","a":"La famille impériale japonaise se réclame de la plus ancienne lignée héréditaire au monde encore sur le trône.","c":"Histoire"},{"id":"fgoa2ivm","t":"Comment appelle-t-on le bassin public où les lavandières lavaient le linge, au village ?","m":"LAVOIR","aff":"lavoir","a":"Le lavoir était aussi un lieu de rencontre où l'on échangeait les nouvelles du village.","c":"Histoire"},{"id":"hbwoggon","t":"Quel accessoire de faux cheveux les courtisans de Louis XIV portaient-ils sur la tête ?","m":"PERRUQUE","aff":"perruque","a":"Louis XIII, devenu chauve, contribua à lancer la mode des perruques ; Louis XIV ne les adopta qu'à partir des années 1670, quand sa chevelure s'éclaircit.","c":"Histoire"},{"id":"qk62r3v1","t":"Comment appelait-on le grand domaine agricole d'un riche Romain à la campagne ?","m":"VILLA","aff":"villa","a":"Le mot a traversé les siècles : le français « ville » vient du latin villa, qui désignait d'abord un domaine rural.","c":"Histoire"},{"id":"00glaco1","t":"Que fabriquait le vannier, artisan des campagnes d'autrefois ?","m":"PANIERS","aff":"paniers","a":"Le vannier tressait surtout l'osier, les jeunes rameaux souples d'un saule cultivé exprès.","c":"Histoire"},{"id":"x1aksem8","t":"Quel roi des Huns est resté dans l'histoire sous le surnom de « fléau de Dieu » ?","m":"ATTILA","aff":"Attila","a":"La tradition veut que l'herbe ne repoussait pas là où son cheval était passé.","c":"Histoire"},{"id":"f7yvg5oc","t":"Avant le réfrigérateur, quel meuble isolé, garni de pains de glace, gardait les aliments au frais ?","m":"GLACIERE","aff":"glacière","a":"L'hiver, on découpait la glace des étangs pour la conserver dans des bâtiments souterrains, eux aussi appelés glacières.","c":"Histoire"},{"id":"oc69jypp","t":"Comment s'appelait la grande unité de l'armée romaine, forte de plusieurs milliers de soldats ?","m":"LEGION","aff":"légion","a":"Une légion se divisait en dix cohortes, elles-mêmes composées de centuries.","c":"Histoire"},{"id":"bvzqkzms","t":"Dans quel sanctuaire du Péloponnèse, dédié à Zeus, se déroulaient les plus prestigieux jeux de la Grèce antique ?","m":"OLYMPIE","aff":"Olympie","a":"Une trêve sacrée suspendait les guerres pour laisser athlètes et spectateurs voyager.","c":"Histoire"},{"id":"7dz5yjc5","t":"Quelle machine à roue, actionnée à la main ou au pied, servait à filer la laine dans les foyers d'autrefois ?","m":"ROUET","aff":"rouet","a":"Gandhi fit du rouet le symbole de l'indépendance indienne : filer soi-même son coton, c'était refuser les tissus anglais.","c":"Histoire"},{"id":"5hxilpe9","t":"Quel chapeau à deux pointes est indissociable de la silhouette de Napoléon Ier ?","m":"BICORNE","aff":"bicorne","a":"Napoléon portait souvent son bicorne « en bataille », pointes sur les épaules, pour être reconnu de loin.","c":"Histoire"},{"id":"2arhsyxf","t":"Dans une cité de la Grèce antique, comment appelait-on la place publique où l'on se réunissait et commerçait ?","m":"AGORA","aff":"agora","a":"À Athènes, Socrate aimait discuter avec les passants sur l'agora, au milieu des marchands.","c":"Histoire"}],"Géographie":[{"id":"vkvixhm1","t":"Quel peuple d'éleveurs d'Afrique de l'Est est célèbre pour ses tuniques rouges et ses danses sautées ?","m":"MASAI","aff":"Masaï","a":"Ils vivent surtout dans le sud du Kenya et le nord de la Tanzanie, et parlent le maa.","c":"Géographie"},{"id":"2l9nbkb0","t":"Dans quelle ville italienne la coupole de Brunelleschi couronne-t-elle la cathédrale Santa Maria del Fiore ?","m":"FLORENCE","aff":"Florence","a":"Achevée en 1436, la coupole fut bâtie sans charpente de soutien, un exploit technique pour l'époque.","c":"Géographie"},{"id":"zdkaym4o","t":"Quelle ville des Andes péruviennes fut la capitale de l'empire inca ?","m":"CUSCO","aff":"Cusco","a":"Son nom, en quechua, est souvent traduit par « nombril ».","c":"Géographie"},{"id":"kyoogeju","t":"Comment appelle-t-on une vaste région très sèche, où il ne pleut presque jamais ?","m":"DESERT","aff":"désert","a":"Un désert n'est pas forcément chaud : l'Antarctique, glacé, est aussi considéré comme un désert, faute de précipitations.","c":"Géographie"},{"id":"azs9ppsm","t":"Quelle ville de l'Aube a un centre ancien dessiné en forme de bouchon de champagne ?","m":"TROYES","aff":"Troyes","a":"Le centre de la préfecture de l'Aube est aussi connu pour ses maisons à pans de bois.","c":"Géographie"},{"id":"0y2l1vup","t":"Quelle ville est la préfecture du Haut-Rhin ?","m":"COLMAR","aff":"Colmar","a":"Auguste Bartholdi, sculpteur de la statue de la Liberté, y est né en 1834.","c":"Géographie"},{"id":"xvvdijtv","t":"Quel pays est associé au kilt, jupe à carreaux masculine, et à la cornemuse ?","m":"ECOSSE","aff":"Écosse","a":"Chaque motif de tartan est traditionnellement associé à un clan ou à une famille.","c":"Géographie"},{"id":"9643etxk","t":"Quelle est la plus petite région de la France métropolitaine par sa superficie ?","m":"CORSE","aff":"Corse","a":"Sur le continent, la plus petite est l'Île-de-France, avec environ 12 000 km².","c":"Géographie"},{"id":"phz9nlpa","t":"Le drapeau noir et blanc appelé Gwenn-ha-du est l'emblème de quelle région ?","m":"BRETAGNE","aff":"Bretagne","a":"Son nom signifie « blanc et noir » en breton ; ses mouchetures d'hermine rappellent les armoiries des ducs de Bretagne.","c":"Géographie"},{"id":"krbarwfj","t":"Quelle ville est le chef-lieu de la région Nouvelle-Aquitaine ?","m":"BORDEAUX","aff":"Bordeaux","a":"La Nouvelle-Aquitaine est née en 2016 de la fusion de l'Aquitaine, du Limousin et de Poitou-Charentes.","c":"Géographie"},{"id":"qnl501n0","t":"Comment s'appelle le chauffage traditionnel coréen par le sol ?","m":"ONDOL","aff":"ondol","a":"Des conduits d'air chaud passent sous le sol des maisons et chauffent la pièce où l'on vit, assis ou couché.","c":"Géographie"},{"id":"4v73xjnc","t":"Quel pays a une feuille d'érable rouge au centre de son drapeau ?","m":"CANADA","aff":"Canada","a":"Ce drapeau, adopté en 1965, a remplacé un pavillon qui portait l'Union Jack.","c":"Géographie"}],"Sciences":[{"id":"jcyb128a","t":"Quelle glande, à l'avant du cou, produit des hormones qui règlent le métabolisme ?","m":"THYROIDE","aff":"thyroïde","a":"Elle a la forme d'un papillon et a besoin d'iode pour fonctionner.","c":"Sciences"},{"id":"ac9ybhp9","t":"Quel métal liquide contenaient les anciens thermomètres médicaux ?","m":"MERCURE","aff":"mercure","a":"C'est Daniel Gabriel Fahrenheit qui a construit en 1714 le premier thermomètre à mercure.","c":"Sciences"},{"id":"mgiy6ioc","t":"Quelle planète porte le nom du dieu romain de la mer ?","m":"NEPTUNE","aff":"Neptune","a":"Son symbole astronomique est le trident, l'attribut du dieu des mers.","c":"Sciences"},{"id":"yooqhdj9","t":"Quelle glande est dérégulée dans la maladie de Basedow ?","m":"THYROIDE","aff":"thyroïde","a":"Elle porte le nom du médecin allemand Karl von Basedow, qui l'a décrite en 1840.","c":"Sciences"},{"id":"a9atft69","t":"Quel gaz, une fois inhalé, rend la voix aiguë et comique ?","m":"HELIUM","aff":"hélium","a":"Le son va bien plus vite dans l'hélium que dans l'air, ce qui change le timbre de la voix.","c":"Sciences"},{"id":"n2hewakq","t":"Quel astre nous éclaire et nous réchauffe pendant la journée ?","m":"SOLEIL","aff":"Soleil","a":"Sans le Soleil, il n'y aurait ni plantes ni vent ni pluie : son énergie met en mouvement l'air et l'eau de la Terre.","c":"Sciences"},{"id":"cvdichec","t":"Que désigne le suffixe « -algie », comme dans « névralgie » ?","m":"DOULEUR","aff":"douleur","a":"Le mot « nostalgie » est bâti sur la même racine grecque : la douleur du retour.","c":"Sciences"},{"id":"vsye32sh","t":"Quelle charge électrique porte le proton ?","m":"POSITIVE","aff":"Positive","a":"Le proton est près de 2 000 fois plus lourd que l'électron, alors que leurs charges ont exactement la même valeur, de signe opposé.","c":"Sciences"},{"id":"mu0ckv0w","t":"Comment appelle-t-on la partie centrale de la Terre ?","m":"NOYAU","aff":"noyau","a":"Personne n'a jamais foré jusqu'au centre de la Terre : on le connaît grâce aux ondes des séismes qui le traversent.","c":"Sciences"},{"id":"5ogugw63","t":"Comment s'appelle la fine membrane qui vibre au passage des sons, entre l'oreille externe et l'oreille moyenne ?","m":"TYMPAN","aff":"tympan","a":"Le mot vient du grec tumpanon, le tambour : la membrane tendue vibre comme une peau de tambour.","c":"Sciences"},{"id":"6q7gz789","t":"Comment appelle-t-on une substance sans principe actif, donnée dans un essai pour être comparée à un vrai médicament ?","m":"PLACEBO","aff":"Placebo","a":"Placebo est un mot latin qui signifie « je plairai » : l'effet vient de la confiance du patient, non de la substance.","c":"Sciences"},{"id":"0ov01ylf","t":"Comment s'appelle l'assistant vocal d'Amazon, intégré à ses enceintes Echo ?","m":"ALEXA","aff":"Alexa","a":"Alexa est apparue avec l'enceinte connectée Echo, lancée par Amazon fin 2014.","c":"Sciences"}],"Nature":[{"id":"w4e9liz2","t":"Quel petit rongeur transporte sa nourriture dans de grandes poches situées dans ses joues ?","m":"HAMSTER","aff":"Hamster","a":"Ces poches, les abajoues, sont si extensibles qu'elles peuvent s'étirer jusqu'aux épaules de l'animal une fois remplies.","c":"Nature"},{"id":"rr4bai61","t":"Comment appelle-t-on le petit de l'aigle ?","m":"AIGLON","aff":"Aiglon","a":"Le fils de Napoléon Ier fut surnommé l'Aiglon, titre d'une pièce d'Edmond Rostand jouée par Sarah Bernhardt.","c":"Nature"},{"id":"xsux3mi6","t":"Quelle herbe aromatique est la base du pistou et du pesto ?","m":"BASILIC","aff":"Basilic","a":"Le pistou provençal se fait avec basilic, ail et huile d'olive, sans pignons, contrairement au pesto génois.","c":"Nature"},{"id":"dw315vz4","t":"Quels insectes vivent en colonies dans une fourmilière ?","m":"FOURMIS","aff":"fourmis","a":"Une fourmilière peut abriter plusieurs reines, et certaines espèces relient entre elles des nids voisins en vastes supercolonies.","c":"Nature"},{"id":"xubtojbp","t":"Comment appelle-t-on la femelle du loup ?","m":"LOUVE","aff":"louve","a":"Selon la légende, une louve aurait allaité Romulus et Rémus, les jumeaux fondateurs de Rome.","c":"Nature"},{"id":"bhdnur6i","t":"Sous quel nom vend-on souvent le calmar chez le poissonnier ?","m":"ENCORNET","aff":"encornet","a":"Les anneaux de calamar frits, servis en beignets, sont découpés dans le manteau de l'animal.","c":"Nature"},{"id":"nup9ua0r","t":"Comment appelle-t-on l'œuf du pou, collé à la base des cheveux ?","m":"LENTE","aff":"Lente","a":"La femelle fixe chaque œuf au cheveu avec une substance très résistante, ce qui le rend difficile à retirer sans peigne fin.","c":"Nature"},{"id":"6wb4878i","t":"Quel arbre était réputé sacré chez les Gaulois quand le gui y pousse ?","m":"CHENE","aff":"chêne","a":"Selon Pline l'Ancien, les druides coupaient le gui du chêne avec une serpe d'or.","c":"Nature"},{"id":"31213p7r","t":"Parmi ces sources d'énergie, laquelle est une énergie fossile ?","m":"CHARBON","aff":"charbon","a":"Le charbon s'est formé pendant des millions d'années à partir de végétaux enfouis, ce qui le rend impossible à renouveler à l'échelle humaine.","c":"Nature"},{"id":"2uo4z1se","t":"Quel est le plus grand oiseau du monde ?","m":"AUTRUCHE","aff":"autruche","a":"Incapable de voler, elle court en revanche très vite, et pond les plus gros œufs de tous les oiseaux vivants.","c":"Nature"},{"id":"p48gg3s8","t":"Chez le canard colvert, de quelle couleur est la tête du mâle ?","m":"VERTE","aff":"Verte","a":"La femelle colvert, toute brune, est bien plus discrète que le mâle : un camouflage utile quand elle couve au sol.","c":"Nature"},{"id":"004pf4a9","t":"Lequel de ces vertébrés est apparu le premier sur Terre ?","m":"POISSON","aff":"poisson","a":"Les premiers poissons nagent dans les mers depuis plus de 500 millions d'années.","c":"Nature"}],"Cinéma & séries":[{"id":"lqb3qhs8","t":"Comment s'appelle la statuette dorée remise chaque année à Hollywood pour récompenser les meilleurs films ?","m":"OSCAR","aff":"Oscar","a":"Son nom officiel est « Academy Award of Merit » ; le surnom « Oscar » a fini par s'imposer.","c":"Cinéma & séries"},{"id":"eiy1fda4","t":"Sur un tournage, quel appareil enregistre les images du film ?","m":"CAMERA","aff":"caméra","a":"Les frères Lumière ont conçu un appareil, le cinématographe, qui servait à la fois à filmer et à projeter les images.","c":"Cinéma & séries"},{"id":"356ei6y3","t":"Quelle est la planète d'origine de Thanos dans l'univers cinématographique Marvel ?","m":"TITAN","aff":"Titan","a":"Dans les films, Thanos affirme que sa planète a été ravagée par la surpopulation, ce qui motive son plan.","c":"Cinéma & séries"},{"id":"6sn9v1tl","t":"Dans les films d'Astérix, quel Gaulois répète « Ils sont fous, ces Romains ! » ?","m":"OBELIX","aff":"Obélix","a":"La réplique vient des albums de Goscinny et Uderzo. Les traductions l'ont adaptée, comme l'italien « Sono pazzi questi Romani ».","c":"Cinéma & séries"},{"id":"90ynm550","t":"Dans quel pays a été tournée une grande partie des scènes de la planète Tatooine du premier « Star Wars » ?","m":"TUNISIE","aff":"Tunisie","a":"Le nom de Tatooine vient de Tataouine, une ville du sud tunisien proche des lieux de tournage.","c":"Cinéma & séries"},{"id":"lnn8tzzu","t":"Comment appelle-t-on la brève apparition d'une personnalité dans un film, sans rôle important ?","m":"CAMEO","aff":"caméo","a":"Stan Lee en avait fait sa marque de fabrique dans les films de super-héros Marvel.","c":"Cinéma & séries"},{"id":"s9ichls5","t":"Comment s'appelle la famille moldue chez qui grandit Harry Potter ?","m":"DURSLEY","aff":"Dursley","a":"Les Dursley habitent au 4, Privet Drive, à Little Whinging, dans le Surrey.","c":"Cinéma & séries"},{"id":"2o8m3w58","t":"Dans quel film Q, très jeune, demande-t-il à Bond s'il s'attendait à un stylo explosif ?","m":"SKYFALL","aff":"Skyfall","a":"Skyfall est le premier film de Daniel Craig où Q apparaît ; il y est joué par Ben Whishaw, bien plus jeune que ses prédécesseurs.","c":"Cinéma & séries"},{"id":"1jwx51ni","t":"Quel personnage du « Seigneur des anneaux » répète « Mon précieux » en parlant de l'Anneau ?","m":"GOLLUM","aff":"Gollum","a":"Gollum s'appelait Sméagol avant que l'Anneau ne le transforme.","c":"Cinéma & séries"},{"id":"ixm6dp6c","t":"Comment appelle-t-on la grande image imprimée qui annonce un film sur les murs et dans les halls de cinéma ?","m":"AFFICHE","aff":"affiche","a":"Certaines affiches de cinéma anciennes sont devenues des objets de collection qui se vendent très cher aux enchères.","c":"Cinéma & séries"},{"id":"nwbkgdgx","t":"Qui s'écrie « Ils prennent les hobbits à Isengard ! » en voyant les Uruk-hai fuir avec Merry et Pippin ?","m":"LEGOLAS","aff":"Legolas","a":"Isengard est la forteresse de Saroumane, dominée par la tour d'Orthanc.","c":"Cinéma & séries"},{"id":"vvzdv6pq","t":"Dans quelle ville de la Côte d'Azur se tient chaque année le plus célèbre festival de cinéma de France ?","m":"CANNES","aff":"Cannes","a":"Les stars y montent les marches du Palais des festivals, sur la Croisette, le célèbre boulevard du bord de mer.","c":"Cinéma & séries"}],"Musique":[{"id":"g3ymjn9d","t":"Quel guitariste congolais, surnommé « le sorcier de la guitare », a dirigé l'orchestre OK Jazz ?","m":"FRANCO","aff":"Franco","a":"L'orchestre fut fondé en 1956 et Franco en resta le chef jusqu'à sa mort en 1989.","c":"Musique"},{"id":"paud39sk","t":"Combien de musiciens compte un trio ?","m":"TROIS","aff":"Trois","a":"En jazz, le trio le plus classique réunit un piano, une contrebasse et une batterie.","c":"Musique"},{"id":"91lpol1d","t":"Comment s'appelle, en tango argentin, la posture d'enlacement des deux danseurs ?","m":"ABRAZO","aff":"abrazo","a":"En espagnol, ce mot veut aussi dire « accolade ».","c":"Musique"},{"id":"5c1recsx","t":"Quel petit instrument métallique en forme de U donne une note de référence quand on le fait vibrer ?","m":"DIAPASON","aff":"diapason","a":"Il a été inventé en 1711 par un trompettiste anglais, John Shore.","c":"Musique"},{"id":"n8xsk1ud","t":"Quel instrument de percussion en métal, rond et plat, se frappe par paire dans une fanfare ?","m":"CYMBALES","aff":"Cymbales","a":"Les célèbres cymbales Zildjian sont nées à Constantinople, au XVIIe siècle.","c":"Musique"},{"id":"7vi5y56j","t":"Quelle était la nationalité de Jacques Brel ?","m":"BELGE","aff":"Belge","a":"Né à Schaerbeek, près de Bruxelles, en 1929, Brel s'installe à Paris en 1953.","c":"Musique"},{"id":"kqmbcfat","t":"Comment appelle-t-on le spectacle où des chanteurs racontent une histoire en chantant, accompagnés par un orchestre ?","m":"OPERA","aff":"opéra","a":"L'opéra est né en Italie vers 1600, et l'un des premiers chefs-d'œuvre du genre est l'« Orfeo » de Monteverdi.","c":"Musique"},{"id":"w9cbbslb","t":"Quel est le prénom de naissance d'Eminem ?","m":"MARSHALL","aff":"Marshall","a":"Son nom de scène vient de ses initiales, M&M, prononcées à l'anglaise.","c":"Musique"},{"id":"s37qacsu","t":"Quel instrument à cordes pincées, au long manche, est emblématique de la musique grecque et du sirtaki ?","m":"BOUZOUKI","aff":"Bouzouki","a":"Mikis Theodorakis l'a placé au cœur de la musique de « Zorba le Grec », en 1964.","c":"Musique"},{"id":"gbgko9w9","t":"Lequel de ces instruments fait partie de la famille des cordes frottées ?","m":"VIOLON","aff":"violon","a":"Son archet est tendu de crins de cheval, frottés de colophane pour accrocher les cordes.","c":"Musique"},{"id":"hedgecr5","t":"Quel chanteur est l'auteur de « Papaoutai » ?","m":"STROMAE","aff":"Stromae","a":"Paul Van Haver a trouvé son nom de scène en inversant les syllabes de « maestro ».","c":"Musique"},{"id":"qh8u0jr6","t":"Quelle danse folklorique polonaise, à trois temps et très rapide, est la plus tournoyante de la famille des mazurkas ?","m":"OBEREK","aff":"oberek","a":"Le kujawiak, lent et nostalgique, et l'oberek, endiablé, sont deux visages opposés du même répertoire de danses à trois temps.","c":"Musique"}],"Arts & lettres":[{"id":"w4w2bf3o","t":"Dans la tragédie de Shakespeare, quel prince tient dans sa main le crâne du bouffon Yorick ?","m":"HAMLET","aff":"Hamlet","a":"La scène se passe dans un cimetière, où deux fossoyeurs plaisantent en creusant une tombe.","c":"Arts & lettres"},{"id":"jl2fq071","t":"Comment s'appelle le renne médecin de l'équipage de Luffy dans One Piece ?","m":"CHOPPER","aff":"Chopper","a":"Tony Tony Chopper a mangé un fruit du démon qui lui permet de se transformer en humain.","c":"Arts & lettres"},{"id":"vk3o1w9o","t":"De quel pays vient Anne Teresa De Keersmaeker, fondatrice de la compagnie Rosas ?","m":"BELGIQUE","aff":"Belgique","a":"Sa pièce « Rosas danst Rosas » a fait connaître la compagnie dès 1983.","c":"Arts & lettres"},{"id":"ob47rbrj","t":"Quel fabuliste grec de l'Antiquité a inspiré une grande partie des Fables de La Fontaine ?","m":"ESOPE","aff":"Ésope","a":"On ne sait presque rien de sa vie : la légende a largement brodé autour de ce fabuliste qui aurait vécu au VIe siècle avant notre ère.","c":"Arts & lettres"},{"id":"mfrbmyhr","t":"Comment nomme-t-on une sculpture qui représente seulement la tête, le cou et les épaules d'une personne ?","m":"BUSTE","aff":"buste","a":"Les Romains faisaient sculpter des bustes de leurs empereurs et de leurs ancêtres, exposés dans les maisons et les lieux publics.","c":"Arts & lettres"},{"id":"n2r7v4ns","t":"Quelle forme a la grande structure de verre qui sert d'entrée au musée du Louvre, dans la cour Napoléon ?","m":"PYRAMIDE","aff":"pyramide","a":"Inaugurée en 1989, elle laisse entrer la lumière dans le hall souterrain qui accueille les visiteurs.","c":"Arts & lettres"},{"id":"n5cnurjo","t":"Quel mot japonais désigne l'auteur d'une bande dessinée de ce pays ?","m":"MANGAKA","aff":"Mangaka","a":"Le mot « manga » a été popularisé au XIXe siècle par les carnets de croquis d'Hokusai.","c":"Arts & lettres"},{"id":"o9dkasuo","t":"Comment appelle-t-on une situation où l'on doit choisir entre deux options aussi difficiles l'une que l'autre ?","m":"DILEMME","aff":"Dilemme","a":"Le mot vient du grec et évoque une double prémisse : quel que soit le choix, il mène à une conclusion embarrassante.","c":"Arts & lettres"},{"id":"aoifg9ie","t":"Comment appelle-t-on l'art d'assembler de petits cubes de pierre ou de verre pour décorer un sol ou un mur ?","m":"MOSAIQUE","aff":"mosaïque","a":"Les mosaïques byzantines de Ravenne scintillent grâce à des tesselles dorées posées à des angles variés.","c":"Arts & lettres"},{"id":"sr777gp2","t":"Sur quoi le chef Abraracourcix se fait-il porter par deux guerriers du village ?","m":"BOUCLIER","aff":"bouclier","a":"Ses porteurs, souvent malmenés, le font régulièrement tomber, au grand dam du chef.","c":"Arts & lettres"},{"id":"6453m2f2","t":"Dans quel musée parisien est exposée la Vénus de Milo ?","m":"LOUVRE","aff":"Louvre","a":"Découverte en 1820 sur l'île grecque de Milo, elle est offerte à Louis XVIII, qui la donne au Louvre.","c":"Arts & lettres"},{"id":"vdwiqav8","t":"Quel petit guerrier gaulois, rusé et moustachu, est le héros de la série créée par Goscinny et Uderzo ?","m":"ASTERIX","aff":"Astérix","a":"Astérix est traduit en plusieurs dizaines de langues, et même en latin.","c":"Arts & lettres"}],"Sport":[{"id":"zvwja4nx","t":"Quelle médaille olympique récompense la deuxième place d'une épreuve ?","m":"ARGENT","aff":"Argent","a":"Aux premiers Jeux modernes, en 1896, le vainqueur recevait une médaille d'argent et le deuxième une médaille de bronze.","c":"Sport"},{"id":"t4qm8nj8","t":"De quel pays vient la capoeira, art martial mêlé de danse et de musique ?","m":"BRESIL","aff":"Brésil","a":"Elle est née chez les esclaves africains du Brésil, qui la dissimulaient derrière des chants et des danses.","c":"Sport"},{"id":"6efvanle","t":"Quel pays d'Amérique du Nord est représenté par l'équipe de rugby surnommée les Canucks ?","m":"CANADA","aff":"Canada","a":"Le mot « Canuck » est un surnom familier des Canadiens, en anglais.","c":"Sport"},{"id":"jn6lg2fu","t":"Au rugby, comment appelle-t-on l'action de marquer en aplatissant le ballon dans l'en-but adverse ?","m":"ESSAI","aff":"essai","a":"Le mot vient de l'anglais « try » : à l'origine, l'essai ne rapportait aucun point et donnait seulement le droit de tenter un coup de pied au but.","c":"Sport"},{"id":"gyeql1lz","t":"Combien de joueurs compte une équipe de curling sur la glace ?","m":"QUATRE","aff":"Quatre","a":"Les balayeurs frottent la glace devant la pierre : cela la réchauffe légèrement et lui permet d'aller plus loin et plus droit.","c":"Sport"},{"id":"lubbolrd","t":"De quel pays le krav-maga, méthode de self-défense, est-il issu ?","m":"ISRAEL","aff":"Israël","a":"Imi Lichtenfeld, originaire de Bratislava, en pose les bases avant de l'enseigner à l'armée israélienne.","c":"Sport"},{"id":"5jgpmo18","t":"Quel fruit mange-t-on traditionnellement avec de la crème pendant le tournoi de Wimbledon ?","m":"FRAISES","aff":"Fraises","a":"Les organisateurs en servent plusieurs tonnes chaque année, accompagnées de crème, durant les deux semaines du tournoi.","c":"Sport"},{"id":"h4xu39z4","t":"Selon la formule de Muhammad Ali, il vole comme un papillon et pique comme quoi ?","m":"ABEILLE","aff":"abeille","a":"Cette formule résume son style : un jeu de jambes léger et des coups rapides.","c":"Sport"},{"id":"kjc0qud4","t":"Quelle discipline du ski alpin atteint les vitesses les plus élevées ?","m":"DESCENTE","aff":"descente","a":"En descente, les skieurs dépassent couramment les 120 km/h, et portent des combinaisons très moulantes pour mieux fendre l'air.","c":"Sport"},{"id":"g5rhrd1q","t":"Au rugby à XV, combien de joueurs forment la première ligne de la mêlée ?","m":"TROIS","aff":"Trois","a":"La première ligne, c'est le talonneur encadré de deux piliers : des postes si spécialisés qu'ils ont leurs propres remplaçants.","c":"Sport"},{"id":"0qsr6evt","t":"Comment appelle-t-on une personne qui fait du vélo ?","m":"CYCLISTE","aff":"Cycliste","a":"Le mot « vélo » est l'abréviation de « vélocipède », formé sur le latin velox, « rapide », et pes, pedis, « pied ».","c":"Sport"},{"id":"h6ywb2g3","t":"Dans quel pays se trouve le club de football du Benfica ?","m":"PORTUGAL","aff":"Portugal","a":"Le Benfica joue à Lisbonne, au stade de la Luz, et a pour emblème un aigle.","c":"Sport"}],"Cuisine":[{"id":"cw1fgeas","t":"De quel pays viennent les gigantes plaki, grosses fèves blanches cuites au four dans une sauce tomate à l'aneth ?","m":"GRECE","aff":"Grèce","a":"Leur nom signifie « géants » en grec, à cause de la taille des fèves.","c":"Cuisine"},{"id":"peeuubae","t":"De quel pays le chorizo, saucisson rouge au paprika, est-il originaire ?","m":"ESPAGNE","aff":"Espagne","a":"Le chorizo doit sa couleur rouge et son goût fumé au pimentón, le paprika espagnol.","c":"Cuisine"},{"id":"i4f23ypr","t":"Dans une brigade de cuisine classique, comment appelle-t-on le cuisinier chargé des sauces ?","m":"SAUCIER","aff":"saucier","a":"La brigade classique, codifiée par Escoffier, attribue un poste à chaque spécialité.","c":"Cuisine"},{"id":"4yh32s53","t":"Quel geste mêle farine et eau, et développe le gluten, pour faire du pain ?","m":"PETRIR","aff":"Pétrir","a":"Le gluten forme un réseau élastique qui retient les gaz et fait alvéoler la mie.","c":"Cuisine"},{"id":"7zmeoocd","t":"Comment nomme-t-on les restaurants traditionnels lyonnais, à la cuisine généreuse et aux nappes à carreaux ?","m":"BOUCHONS","aff":"bouchons","a":"Les bouchons servent des plats comme la salade lyonnaise, le tablier de sapeur ou la cervelle de canut.","c":"Cuisine"},{"id":"0wld1hql","t":"Quel légume est surnommé « l'asperge du pauvre » ?","m":"POIREAU","aff":"poireau","a":"Le poireau est aussi une plante très ancienne : les Romains l'appréciaient déjà dans leurs soupes.","c":"Cuisine"},{"id":"n6iezepv","t":"Combien d'étoiles un restaurant peut-il décrocher, au maximum, dans le guide Michelin ?","m":"TROIS","aff":"Trois","a":"Une étoile signale une très bonne table, deux une table excellente, trois une cuisine exceptionnelle.","c":"Cuisine"},{"id":"am02kr1s","t":"Quelle marmite lourde, souvent en fonte émaillée, mijote plats et ragoûts avec son couvercle ?","m":"COCOTTE","aff":"cocotte","a":"En fonte, elle garde longtemps la chaleur, au four comme sur le feu.","c":"Cuisine"},{"id":"8ewiy7aj","t":"Quelle soupe onctueuse de crustacés se prépare avec les carapaces broyées de homards ou de langoustines ?","m":"BISQUE","aff":"bisque","a":"La bisque se finit traditionnellement à la crème.","c":"Cuisine"},{"id":"1l67v1br","t":"Quel poisson salé est la base de la brandade de Nîmes ?","m":"MORUE","aff":"morue","a":"Son nom vient du provençal brandado, « remuée », car on bat la préparation à la cuillère.","c":"Cuisine"},{"id":"rl5730x0","t":"De quelle île d'Italie viennent les cannoli, tubes de pâte frits fourrés de ricotta sucrée ?","m":"SICILE","aff":"Sicile","a":"Ils sont traditionnels au moment du carnaval, avec des écorces d'orange confites ou des pépites de chocolat.","c":"Cuisine"},{"id":"4gctdlvl","t":"Comment appelle-t-on l'écumoire en fils métalliques tissés en toile, qui sort les aliments d'un bain de friture ?","m":"ARAIGNEE","aff":"araignée","a":"Très utilisée en cuisine asiatique, l'araignée accompagne souvent le wok pour sortir beignets et nouilles.","c":"Cuisine"}],"Jeux & pop culture":[{"id":"2xadaj0c","t":"Dans quel quartier de Tokyo la mode de rue colorée et excentrique des jeunes est-elle célèbre ?","m":"HARAJUKU","aff":"Harajuku","a":"Le dimanche, la rue Takeshita attire des jeunes aux styles très variés, du lolita au punk, qui y posent pour les photographes.","c":"Jeux & pop culture"},{"id":"erw9kqof","t":"De quel pays vient le Mölkky, jeu de lancer de quilles en bois numérotées ?","m":"FINLANDE","aff":"Finlande","a":"Il faut atteindre exactement 50 points : si l'on dépasse, on retombe à 25.","c":"Jeux & pop culture"},{"id":"uudhtjw2","t":"Quel jeu d'enfant se joue avec de petits os de mouton, lancés en l'air et rattrapés ?","m":"OSSELETS","aff":"osselets","a":"Les Grecs et les Romains y jouaient déjà, avec des astragales.","c":"Jeux & pop culture"},{"id":"kpk6vft1","t":"Quelle princesse Mario doit-il sauver dans la plupart de ses aventures ?","m":"PEACH","aff":"Peach","a":"Peach s'appelait Toadstool dans les premières versions occidentales avant que son nom japonais ne s'impose.","c":"Jeux & pop culture"},{"id":"bhq09l93","t":"Dans Minecraft, quel minerai bleu clair permet de fabriquer des outils et des armures très résistants ?","m":"DIAMANT","aff":"diamant","a":"Le diamant se trouve surtout dans les couches les plus profondes du monde, et il faut au moins une pioche en fer pour l'extraire.","c":"Jeux & pop culture"},{"id":"apmpuf1l","t":"Quelle plateforme française d'écoute de musique en ligne a d'abord porté le nom Blogmusik ?","m":"DEEZER","aff":"Deezer","a":"Née à Paris, elle compte parmi les grands services de musique en ligne d'Europe.","c":"Jeux & pop culture"},{"id":"drkihlx3","t":"Quel oiseau vert est la mascotte de l'application d'apprentissage des langues Duolingo ?","m":"CHOUETTE","aff":"chouette","a":"Duolingo a été fondé à Pittsburgh par Luis von Ahn, qui avait aussi coinventé les tests CAPTCHA.","c":"Jeux & pop culture"},{"id":"k8a441w8","t":"Comment s'appelle la gamme Lego aux grosses briques, conçue pour les tout-petits ?","m":"DUPLO","aff":"Duplo","a":"Lancée à la fin des années 1960, la gamme a des briques deux fois plus grandes que les briques classiques, trop grosses pour être avalées.","c":"Jeux & pop culture"},{"id":"ey8pbxxr","t":"À quel jeu de cartes simple, entre deux joueurs, gagne la carte la plus forte à chaque tour, avant de rafler le tas ?","m":"BATAILLE","aff":"bataille","a":"Si deux cartes sont égales, une nouvelle « bataille » s'engage.","c":"Jeux & pop culture"},{"id":"p5dgzrn3","t":"Comment s'appelle le gentil dinosaure orange de « L'Île aux enfants » ?","m":"CASIMIR","aff":"Casimir","a":"L'émission, née en 1974, était inspirée de l'américaine Sesame Street.","c":"Jeux & pop culture"},{"id":"xi3hr7nl","t":"Quelle plateforme de vidéos a pour logo un rectangle rouge avec un triangle blanc ?","m":"YOUTUBE","aff":"YouTube","a":"Le triangle du logo évoque le bouton « lecture » que l'on trouve sur les lecteurs de vidéos.","c":"Jeux & pop culture"},{"id":"0yau3kdv","t":"Quelle entreprise japonaise a créé la série de jeux de combat Street Fighter ?","m":"CAPCOM","aff":"Capcom","a":"Street Fighter II, sorti en 1991, a lancé la grande mode des jeux de combat en salle d'arcade.","c":"Jeux & pop culture"}],"Autour de la fête":[{"id":"n9pyyd4j","t":"Durant quel mois se déroule le Gion Matsuri, grande fête de Kyoto aux chars monumentaux ?","m":"JUILLET","aff":"Juillet","a":"Ses défilés de chars, les yamaboko, sont classés au patrimoine culturel immatériel de l'humanité.","c":"Autour de la fête"},{"id":"p3nf30fu","t":"Quels animaux tirent le traîneau du Père Noël ?","m":"RENNES","aff":"rennes","a":"Les rennes sont les seuls cervidés dont les mâles et les femelles portent des bois.","c":"Autour de la fête"},{"id":"drfqyk31","t":"Quel morceau d'étoffe légère couvre souvent la tête et le visage de la mariée pendant la cérémonie ?","m":"VOILE","aff":"voile","a":"À la fin de la cérémonie, le marié soulève traditionnellement le voile de la mariée avant de l'embrasser.","c":"Autour de la fête"},{"id":"utzqw16x","t":"Dans le roman « Sacrées sorcières » de Roald Dahl, en quel animal les sorcières transforment-elles le jeune héros ?","m":"SOURIS","aff":"souris","a":"Dans ce roman, Roald Dahl décrit des sorcières chauves qui cachent leur crâne sous une perruque et dissimulent leurs pieds sans orteils.","c":"Autour de la fête"},{"id":"yftbpdzz","t":"Dans un mariage chinois traditionnel, de quelle couleur est la robe de la mariée ?","m":"ROUGE","aff":"Rouge","a":"En Chine, le rouge est la couleur de la chance et de la joie, alors que le blanc y est traditionnellement associé au deuil.","c":"Autour de la fête"},{"id":"hb3awx8p","t":"Dans quel jeu dansé doit-on passer sous une barre placée de plus en plus bas, en se cambrant en arrière ?","m":"LIMBO","aff":"limbo","a":"Le limbo est associé aux Caraïbes ; il est souvent pratiqué sur des plages, avec une barre parfois enflammée.","c":"Autour de la fête"},{"id":"ikg6qb88","t":"Quel philosophe médiéval a vécu un amour célèbre avec Héloïse ?","m":"ABELARD","aff":"Abélard","a":"Leur tombeau commun se trouve au Père-Lachaise, à Paris.","c":"Autour de la fête"},{"id":"8f3wt3bg","t":"Quel fruit, enrobé de caramel et piqué sur un bâtonnet, se vend souvent à Halloween aux États-Unis ?","m":"POMME","aff":"pomme","a":"En France, sa version au sucre rouge s'appelle la pomme d'amour et se vend dans les fêtes foraines.","c":"Autour de la fête"},{"id":"pwajuf4o","t":"Dans « La Belle au bois dormant » de Perrault, à quoi la princesse se pique-t-elle le doigt ?","m":"FUSEAU","aff":"fuseau","a":"Selon le conte, la princesse et tout le château s'endorment pour cent ans.","c":"Autour de la fête"},{"id":"34avph4b","t":"Comment dit-on « anniversaire » en anglais ?","m":"BIRTHDAY","aff":"Birthday","a":"Le mot associe « birth », la naissance, et « day », le jour.","c":"Autour de la fête"},{"id":"b4xnprk5","t":"Dans quel pays mange-t-on à Noël la risalamande, riz au lait où une amande entière cachée fait gagner un cadeau ?","m":"DANEMARK","aff":"Danemark","a":"Ce dessert se sert froid avec une sauce aux cerises ; celui qui trouve l'amande reçoit le « cadeau de l'amande ».","c":"Autour de la fête"},{"id":"a3e6r5er","t":"De quelle couleur sont les enveloppes garnies d'argent que l'on offre aux enfants pour le Nouvel An chinois ?","m":"ROUGES","aff":"Rouges","a":"On y glisse de préférence des billets neufs, et l'on évite les sommes contenant le chiffre quatre, réputé porter malheur.","c":"Autour de la fête"}]},"filet":{"Culture générale":[{"id":"09aa4w6j","t":"En quelle année le canal de Panama est-il ouvert à la navigation ?","v":1914,"u":"","annee":true,"a":"Les États-Unis ont repris le chantier abandonné par la France, dont les travaux, dirigés par Lesseps, avaient échoué.","c":"Culture générale"},{"id":"k394hq15","t":"En quelle année le dernier vol commercial du Concorde a-t-il eu lieu ?","v":2003,"u":"","annee":true,"a":"Les Concorde d'Air France et de British Airways ont cessé leurs vols réguliers en 2003 ; le prix du carburant et la baisse de fréquentation pesaient.","c":"Culture générale"},{"id":"aq4xprap","t":"En quelle année a été découverte la pierre de Rosette, qui a permis de déchiffrer les hiéroglyphes ?","v":1799,"u":"","annee":true,"a":"Elle a été trouvée par des soldats français pendant l'expédition d'Égypte. Elle est conservée au British Museum, à Londres.","c":"Culture générale"},{"id":"y3ji7o5s","t":"En quelle année la profession de sage-femme a-t-elle été ouverte aux hommes en France ?","v":1982,"u":"","annee":true,"a":"Jusque-là, seules des femmes pouvaient exercer ce métier, dont le nom lui-même est resté au féminin.","c":"Culture générale"},{"id":"iz65lfrg","t":"En quelle année la phrase « La langue de la République est le français » entre-t-elle dans la Constitution ?","v":1992,"u":"","annee":true,"a":"Cet ajout date de la révision liée au traité de Maastricht, deux ans avant la loi Toubon.","c":"Culture générale"},{"id":"6dhrafur","t":"En quelle année l'ONG Médecins sans frontières a-t-elle reçu le prix Nobel de la paix ?","v":1999,"u":"","annee":true,"a":"L'organisation a été récompensée pour son action médicale auprès des populations en danger, partout dans le monde.","c":"Culture générale"},{"id":"xznhseor","t":"En quelle année a été fondée l'Académie royale espagnole, chargée de veiller sur la langue ?","v":1713,"u":"","annee":true,"a":"Elle a été fondée à Madrid sur le modèle de l'Académie française, créée en 1635.","c":"Culture générale"},{"id":"r7o36ski","t":"Combien de pieds compte un mile terrestre anglo-saxon ?","v":5280,"u":"pieds","a":"Le mot mile vient du latin mille passuum, « mille pas » : la distance qu'une légion romaine parcourait en mille doubles pas.","c":"Culture générale"},{"id":"qmpfvlga","t":"En France, à combien de milliards équivaut un billion ?","v":1000,"u":"milliards","a":"En anglais américain, « billion » vaut un milliard : le même mot ne désigne pas le même nombre des deux côtés de l'Atlantique.","c":"Culture générale"},{"id":"79dnoidt","t":"Combien de chiffres compte un numéro de Sécurité sociale français, clé de contrôle comprise ?","v":15,"u":"chiffres","a":"Le premier chiffre indique le sexe, les suivants l'année et le mois de naissance.","c":"Culture générale"},{"id":"bxujt283","t":"En France, le calendrier grégorien est adopté en 1582 : quel quantième du mois suit le 9 décembre ?","v":20,"u":"","a":"Dix jours disparurent d'un coup afin de rattraper le retard accumulé par le calendrier julien sur les saisons.","c":"Culture générale"},{"id":"841r9a6b","t":"Combien de livres anglo-saxonnes compte un stone, unité qui sert encore à dire son poids au Royaume-Uni ?","v":14,"u":"livres","a":"Au Royaume-Uni et en Irlande, on dit volontiers son poids en stones et en livres plutôt qu'en kilogrammes.","c":"Culture générale"},{"id":"5x4l1mv8","t":"Combien de feuilles compte une ramette de papier pour imprimante ?","v":500,"u":"feuilles","a":"Le mot « rame » viendrait de l'arabe rizma, « paquet », passé en français par l'espagnol resma.","c":"Culture générale"},{"id":"6lfi3y10","t":"Combien de lettres compte l'alphabet grec ?","v":24,"u":"lettres","a":"Les Grecs ont emprunté leur alphabet aux Phéniciens et y ont ajouté des lettres pour noter les voyelles.","c":"Culture générale"}],"Histoire":[{"id":"memirtqf","t":"En quelle année Paris accueille-t-elle sa première Exposition universelle ?","v":1855,"u":"","annee":true,"a":"Elle se tint notamment au palais de l'Industrie, bâti pour l'occasion sur les Champs-Élysées.","c":"Histoire"},{"id":"yqxldl7h","t":"En quelle année les Français élisent-ils pour la première fois leur président au suffrage universel direct sous la Ve République ?","v":1965,"u":"","annee":true,"a":"Le général de Gaulle, mis en ballottage au premier tour, l'emporte au second face à François Mitterrand.","c":"Histoire"},{"id":"lxuq5ld4","t":"En quelle année commencent les fouilles officielles de Pompéi, ensevelie par le Vésuve ?","v":1748,"u":"","annee":true,"a":"Au XIXe siècle, l'archéologue Giuseppe Fiorelli eut l'idée de couler du plâtre dans les vides laissés par les corps dans la cendre.","c":"Histoire"},{"id":"2qnmv5xq","t":"En quelle année les premiers omnibus à chevaux circulent-ils à Paris ?","v":1828,"u":"","annee":true,"a":"Le nom vient du latin omnibus, « pour tous » ; l'idée serait née à Nantes, devant la boutique d'un chapelier nommé Omnès.","c":"Histoire"},{"id":"3gwvopgu","t":"En quelle année les États-Unis achètent-ils l'Alaska à la Russie ?","v":1867,"u":"","annee":true,"a":"Le secrétaire d'État William Seward a conclu l'achat, d'abord moqué sous le nom de « folie de Seward ».","c":"Histoire"},{"id":"a3bqld6h","t":"En quelle année la république de Gênes cède-t-elle la Corse à la France, par le traité de Versailles ?","v":1768,"u":"","annee":true,"a":"L'année suivante, les troupes de Pascal Paoli sont battues à Ponte-Novo, et Napoléon Bonaparte naît à Ajaccio.","c":"Histoire"},{"id":"4egteks7","t":"En quelle année ouvre le canal Érié, qui relie l'Hudson aux Grands Lacs ?","v":1825,"u":"","annee":true,"a":"Il a fait de New York le premier grand port du pays, en ouvrant l'intérieur du continent aux marchandises.","c":"Histoire"},{"id":"gcrrr15k","t":"En 1522, combien de survivants de l'expédition de Magellan reviennent en Espagne à bord de la Victoria ?","v":18,"u":"survivants","a":"Revenus en septembre 1522, les rescapés constatèrent qu'ils avaient perdu un jour : le tour du monde vers l'ouest décale le calendrier.","c":"Histoire"},{"id":"ja4uzfqs","t":"Combien de maréchaux d'Empire Napoléon Ier a-t-il nommés en tout ?","v":26,"u":"maréchaux","a":"Le maréchal Bernadotte devint roi de Suède en 1818 : ses descendants règnent encore sur ce pays.","c":"Histoire"},{"id":"ci83z5gm","t":"Combien de clauses compte la Magna Carta, accordée en 1215 par Jean sans Terre ?","v":63,"u":"clauses","a":"Le pape Innocent III l'annula quelques semaines après sa signature, mais elle fut ensuite plusieurs fois réédictée.","c":"Histoire"},{"id":"q5kvm7g5","t":"Quel âge Napoléon a-t-il le jour de la bataille de Waterloo, le 18 juin 1815 ?","v":45,"u":"ans","a":"Après Waterloo, Napoléon est exilé à Sainte-Hélène, une île de l'Atlantique Sud où il meurt en 1821.","c":"Histoire"},{"id":"01m16wyu","t":"En 1982, à combien d'heures la durée légale du travail hebdomadaire est-elle abaissée en France ?","v":39,"u":"heures","a":"Elle passe ensuite à 35 heures avec les lois Aubry, adoptées en 1998 et 2000.","c":"Histoire"},{"id":"bo0jbaul","t":"Combien de délégués ont signé la Déclaration d'indépendance des États-Unis ?","v":56,"u":"signataires","a":"John Hancock, président du Congrès, signa en très grand : son nom désigne depuis une signature en anglais américain.","c":"Histoire"},{"id":"clk9ikeb","t":"Combien de jours dure le siège de Léningrad par l'armée allemande, de septembre 1941 à janvier 1944 ?","v":872,"u":"jours","a":"Le ravitaillement de la ville passait en hiver par la « route de la vie », une piste tracée sur le lac Ladoga gelé.","c":"Histoire"}],"Géographie":[{"id":"6h4arq3c","t":"En quelle année le volcan Tambora, en Indonésie, a-t-il connu sa gigantesque éruption ?","v":1815,"u":"","annee":true,"a":"L'année suivante, 1816, fut surnommée « l'année sans été » en Europe et en Amérique du Nord : les cendres avaient refroidi le climat.","c":"Géographie"},{"id":"0bvf6d7j","t":"En quelle année l'Empire State Building a-t-il été achevé à New York ?","v":1931,"u":"","annee":true,"a":"Le gratte-ciel a été construit en un peu plus d'un an, à un rythme de chantier exceptionnel pour l'époque.","c":"Géographie"},{"id":"8qvcdcd0","t":"En quelle année a commencé la construction de la tour penchée de Pise ?","v":1173,"u":"","annee":true,"a":"La tour a commencé à pencher pendant le chantier, qui s'est étalé sur près de deux siècles.","c":"Géographie"},{"id":"j40nupio","t":"En quelle année le canal du Midi a-t-il été achevé ?","v":1681,"u":"","annee":true,"a":"Pierre-Paul Riquet, qui l'avait conçu, est mort en 1680, quelques mois avant la fin des travaux.","c":"Géographie"},{"id":"92dh2anz","t":"En quelle année le canal Saint-Martin, à Paris, a-t-il été inauguré ?","v":1825,"u":"","annee":true,"a":"Voulu par Napoléon Ier pour alimenter Paris en eau, le canal Saint-Martin passe en partie sous terre, sous le boulevard Richard-Lenoir.","c":"Géographie"},{"id":"bq304767","t":"En quelle année Mayotte est-elle devenue un département français ?","v":2011,"u":"","annee":true,"a":"Mayotte est le 101e département français et le cinquième d'outre-mer.","c":"Géographie"},{"id":"x20ofeee","t":"En quelle année le Tower Bridge de Londres a-t-il été inauguré ?","v":1894,"u":"","annee":true,"a":"Malgré son allure médiévale, le pont cache une charpente d'acier sous son habillage de pierre.","c":"Géographie"},{"id":"0b53mx4n","t":"Depuis 2011, combien de départements la France compte-t-elle, outre-mer compris ?","v":101,"u":"départements","a":"Mayotte est devenue le 101e département en 2011, après un référendum.","c":"Géographie"},{"id":"a1fjppft","t":"Combien de pointes compte la feuille d'érable du drapeau canadien ?","v":11,"u":"pointes","a":"Une feuille d'érable stylisée a été choisie car elle restait lisible sur un drapeau agité par le vent.","c":"Géographie"},{"id":"n1wg809l","t":"Quelle hauteur, en mètres, les tours de Notre-Dame de Paris atteignent-elles ?","v":69,"u":"m","a":"La tour sud abrite le bourdon Emmanuel, la plus grosse cloche de la cathédrale.","c":"Géographie"},{"id":"mbxp5mh7","t":"Quelle est la hauteur du Salto Ángel, chute d'eau du Venezuela, en mètres ?","v":979,"u":"m","a":"Il porte le nom de l'aviateur américain Jimmie Angel, qui le fit connaître au monde en le survolant en 1933.","c":"Géographie"},{"id":"pba3qmog","t":"À quelle altitude, en mètres, culmine la barre des Écrins, dans les Alpes ?","v":4102,"u":"m","a":"L'Anglais Edward Whymper fit partie de la cordée qui en réussit la première ascension en 1864, un an avant celle du Cervin.","c":"Géographie"},{"id":"jo7cj9v0","t":"Combien de provinces l'Espagne compte-t-elle ?","v":50,"u":"provinces","a":"Le découpage en provinces, hérité de 1833, s'inspirait des départements français.","c":"Géographie"},{"id":"vgbplv9j","t":"Quelle est la hauteur, en mètres, du rocher de Gibraltar ?","v":426,"u":"m","a":"Il abrite des macaques de Barbarie, seuls singes vivant en liberté en Europe.","c":"Géographie"}],"Sciences":[{"id":"a48s8uyy","t":"En quelle année Wilhelm Röntgen a-t-il découvert les rayons X ?","v":1895,"u":"","annee":true,"a":"L'une des premières radiographies montrait la main de son épouse, avec sa bague. Röntgen reçut en 1901 le tout premier prix Nobel de physique.","c":"Sciences"},{"id":"oucmkqim","t":"En quelle année James Watson et Francis Crick ont-ils publié la structure en double hélice de l'ADN ?","v":1953,"u":"","annee":true,"a":"Ils ont reçu le prix Nobel de médecine en 1962, avec Maurice Wilkins.","c":"Sciences"},{"id":"hh4osqcr","t":"En quelle année Ray Tomlinson envoie-t-il le premier courrier électronique entre deux ordinateurs ?","v":1971,"u":"","annee":true,"a":"Tomlinson ne se souvenait plus du contenu de ce premier message, qu'il décrivait comme une suite de caractères sans intérêt.","c":"Sciences"},{"id":"z0acalx9","t":"En quelle année Benoît Mandelbrot a-t-il forgé le mot « fractale » ?","v":1975,"u":"","annee":true,"a":"Mandelbrot a tiré ce mot du latin fractus, « brisé », pour décrire des formes qui se répètent à toutes les échelles.","c":"Sciences"},{"id":"3i56uvf5","t":"En quelle année la médaille Fields a-t-elle été décernée pour la première fois ?","v":1936,"u":"","annee":true,"a":"Elle fut remise à Oslo à deux lauréats, le Finlandais Lars Ahlfors et l'Américain Jesse Douglas.","c":"Sciences"},{"id":"5dbd8uzm","t":"En quelle année le vaccin BCG a-t-il été administré pour la première fois à un nouveau-né, à Paris ?","v":1921,"u":"","annee":true,"a":"Ce premier vaccin a été donné par la bouche, en trois doses, à un bébé menacé par la tuberculose dans sa famille.","c":"Sciences"},{"id":"s0djbxe8","t":"En quelle année Fibonacci achève-t-il son Liber abaci, qui fait connaître les chiffres indo-arabes en Europe ?","v":1202,"u":"","annee":true,"a":"C'est dans ce livre qu'apparaît le problème des lapins, à l'origine de la célèbre suite qui porte son nom.","c":"Sciences"},{"id":"ubwv0xxr","t":"Selon le Système international d'unités, combien d'octets compte un kilooctet ?","v":1000,"u":"octets","a":"Pour lever l'ambiguïté, la CEI a créé en 1998 des préfixes binaires comme le kibioctet, qui vaut 1 024 octets.","c":"Sciences"},{"id":"ebtp51i2","t":"Combien font 15 % de 200 ?","v":30,"u":"","a":"Pour 15 %, on peut prendre 10 % d'un nombre, puis y ajouter la moitié de ce résultat.","c":"Sciences"},{"id":"fczjzsq5","t":"Quelle est la température normale du corps humain, à peu près ?","v":37,"u":"°C","a":"Le médecin allemand Carl Wunderlich a fixé ce repère au XIXe siècle, en relevant la température de milliers de patients.","c":"Sciences"},{"id":"t5u6x3tx","t":"Combien de couleurs comptait la palette dite « web safe », sûre sur les écrans des débuts du Web ?","v":216,"u":"couleurs","a":"Chaque couleur primaire n'y prenait que six niveaux, notés 00, 33, 66, 99, CC et FF en hexadécimal.","c":"Sciences"},{"id":"yddidnzs","t":"Combien y a-t-il de nombres premiers entre 1 et 100 ?","v":25,"u":"","a":"Parmi eux, 2 est le seul nombre premier pair : tous les autres pairs se divisent par 2.","c":"Sciences"},{"id":"1xzrlzvx","t":"En partant de 2, quel est le dixième nombre premier ?","v":29,"u":"","a":"Euclide a démontré il y a plus de deux mille ans que la liste des nombres premiers ne s'arrête jamais.","c":"Sciences"},{"id":"m6vw05sy","t":"Combien fait la moitié de 50 ?","v":25,"u":"","a":"Diviser par deux revient à multiplier par 0,5 : la moitié et 50 % désignent toujours la même quantité.","c":"Sciences"}],"Nature":[{"id":"z37vm0q5","t":"En quelle année a-t-on découvert la faune foisonnante des sources hydrothermales, près des îles Galápagos ?","v":1977,"u":"","annee":true,"a":"La découverte a été faite grâce au sous-marin Alvin : des vers géants, des palourdes et des crabes y vivent sans lumière, grâce à des bactéries.","c":"Nature"},{"id":"vcwntcz0","t":"En quelle année la Ligue pour la protection des oiseaux a-t-elle été fondée ?","v":1912,"u":"","annee":true,"a":"Elle est née pour sauver les macareux moines des Sept-Îles, en Bretagne, alors chassés en nombre.","c":"Nature"},{"id":"clowgcr3","t":"En quelle année l'UICN a-t-elle déclaré éteinte la sous-espèce de rhinocéros noir d'Afrique de l'Ouest ?","v":2011,"u":"","annee":true,"a":"Le dernier refuge connu de ce rhinocéros se trouvait au nord du Cameroun, où le braconnage pour ses cornes l'a anéanti.","c":"Nature"},{"id":"n4nkmbgs","t":"En quelle année a-t-on découvert le premier squelette d'archéoptéryx, en Bavière ?","v":1861,"u":"","annee":true,"a":"Ce fossile mi-oiseau, mi-dinosaure, est apparu deux ans à peine après la parution de L'Origine des espèces de Darwin.","c":"Nature"},{"id":"2bs3m73f","t":"En quelle année le missionnaire Armand David a-t-il fait connaître le panda géant à la science occidentale ?","v":1869,"u":"","annee":true,"a":"Armand David, prêtre lazariste et naturaliste, a aussi fait connaître en Europe le cerf qui porte son nom.","c":"Nature"},{"id":"n3gzxoq5","t":"En quelle année le crapaud doré, petit amphibien orange du Costa Rica, a-t-il été observé pour la dernière fois ?","v":1989,"u":"","annee":true,"a":"Il ne vivait que dans la forêt de nuages de Monteverde, et seuls les mâles étaient d'un orange vif.","c":"Nature"},{"id":"hfrdqt54","t":"En quelle année a été créé le GIEC, groupe d'experts chargé d'évaluer les connaissances sur le changement climatique ?","v":1988,"u":"","annee":true,"a":"Il a reçu en 2007 le prix Nobel de la paix, partagé avec l'ancien vice-président américain Al Gore.","c":"Nature"},{"id":"exepok7p","t":"En 1862, combien de livres sterling le British Museum a-t-il payé pour acquérir le premier squelette d'Archaeopteryx ?","v":700,"u":"£","a":"Richard Owen, l'inventeur du mot « dinosaure », a obtenu l'achat pour Londres ; le squelette y est toujours appelé « spécimen de Londres ».","c":"Nature"},{"id":"jlhkhdv6","t":"Combien de kilogrammes pèse environ un éléphant d'Afrique mâle adulte ?","v":6000,"u":"kg","a":"Un éléphanteau pèse déjà autour d'une centaine de kilos à la naissance.","c":"Nature"},{"id":"837n6iwh","t":"Jusqu'à combien de mètres peut mesurer une feuille du palmier Raphia regalis ?","v":25,"u":"m","a":"Ce palmier d'Afrique centrale possède les plus longues feuilles du règne végétal.","c":"Nature"},{"id":"nip6b6bo","t":"Combien de litres d'eau un grand baobab africain peut-il stocker dans son tronc ?","v":120000,"u":"litres","a":"Les éléphants, en saison sèche, arrachent parfois l'écorce des baobabs pour en mâcher le bois gorgé d'eau.","c":"Nature"},{"id":"av1ttsc5","t":"Quel volume de bois, en mètres cubes, compte le tronc de General Sherman, le séquoia géant de Californie ?","v":1487,"u":"m³","a":"General Sherman pousse dans le parc national de Sequoia ; il porte le nom d'un général de la guerre de Sécession.","c":"Nature"},{"id":"5yr5adfl","t":"Jusqu'à combien d'yeux la coquille Saint-Jacques peut-elle porter au bord de son manteau ?","v":200,"u":"yeux","a":"Ces petits yeux bleus fonctionnent avec des miroirs naturels qui concentrent la lumière, un peu comme un télescope.","c":"Nature"},{"id":"rsjv11r5","t":"Quelle longueur, en centimètres, mesure environ un grand dauphin adulte ?","v":300,"u":"cm","a":"Les petits naissent par la queue, et leur mère les aide à remonter respirer à la surface dès les premières secondes.","c":"Nature"}],"Cinéma & séries":[{"id":"xhgsw9p4","t":"En quelle année commence la première saison de « Mad Men » ?","v":2007,"u":"","annee":true,"a":"Les acteurs fument tant à l'écran que la production utilisait des cigarettes aux herbes, sans tabac.","c":"Cinéma & séries"},{"id":"o78iepan","t":"En quelle année a eu lieu la première cérémonie des Oscars ?","v":1929,"u":"","annee":true,"a":"Les gagnants étaient connus trois mois à l'avance, et la soirée n'a duré qu'une quinzaine de minutes.","c":"Cinéma & séries"},{"id":"41rqs0yn","t":"En quelle année sort « Avengers: Endgame », qui conclut l'arc narratif de l'univers cinématographique Marvel ?","v":2019,"u":"","annee":true,"a":"Il a réuni la plupart des héros de Marvel apparus au cinéma depuis plus de dix ans.","c":"Cinéma & séries"},{"id":"97o1oor5","t":"En quelle année Marty McFly arrive-t-il dans le futur, dans « Retour vers le futur II » (1989) ?","v":1989,"u":"","annee":true,"a":"Le film imaginait des hoverboards, des chaussures qui se lacent seules et des vestes qui sèchent toutes seules.","c":"Cinéma & séries"},{"id":"bzq07rqd","t":"En quelle année le studio Pixar est-il fondé en tant que société indépendante ?","v":1986,"u":"","annee":true,"a":"Steve Jobs rachète alors à George Lucas la division d'images de synthèse, qui devient Pixar.","c":"Cinéma & séries"},{"id":"tad6c9im","t":"En quelle année la série Game of Thrones a-t-elle débuté sur HBO ?","v":2011,"u":"","annee":true,"a":"La série est adaptée des romans de George R. R. Martin.","c":"Cinéma & séries"},{"id":"mo5ybwni","t":"En quelle année la Cinémathèque française est-elle fondée ?","v":1936,"u":"","annee":true,"a":"Henri Langlois et Georges Franju comptent parmi ses fondateurs ; Langlois y a sauvé des milliers de films.","c":"Cinéma & séries"},{"id":"a9c7n0pe","t":"Combien de minutes dure « Toy Story » (1995), premier film de Pixar ?","v":81,"u":"min","a":"Le film est réalisé par John Lasseter, l'un des fondateurs artistiques de Pixar.","c":"Cinéma & séries"},{"id":"mww073eo","t":"Combien d'Oscars « Le Seigneur des anneaux : Le Retour du roi » (2003) a-t-il remportés ?","v":11,"u":"Oscars","a":"Le film a gagné dans toutes les catégories où il était nommé, dont ceux du meilleur film et du meilleur réalisateur.","c":"Cinéma & séries"},{"id":"fi3wxv87","t":"Dans « This Is Spinal Tap » (1984), jusqu'à quel chiffre montent les boutons de volume des amplis du guitariste ?","v":11,"u":"","a":"« Monter jusqu'à onze » est devenu une expression anglaise pour dire qu'on pousse une chose au maximum.","c":"Cinéma & séries"},{"id":"1sbcj81r","t":"Quel numéro de vol porte l'avion qui s'écrase sur l'île au début de la série « Lost » (2004) ?","v":815,"u":"","a":"Ce numéro fait partie d'une suite de chiffres qui revient sans cesse dans la série et ses mystères.","c":"Cinéma & séries"},{"id":"7uqktcsl","t":"À quelle vitesse, en miles par heure, la DeLorean doit-elle rouler pour voyager dans le temps dans « Retour vers le futur » ?","v":88,"u":"mph","a":"88 miles par heure font environ 142 kilomètres par heure.","c":"Cinéma & séries"},{"id":"lh3qa45k","t":"Combien d'épisodes compte la série originale « Les Mystérieuses Cités d'or » ?","v":39,"u":"épisodes","a":"La série est une coproduction franco-japonaise, où l'on suit Esteban, Zia et Tao en quête des cités.","c":"Cinéma & séries"},{"id":"y4e8xx6i","t":"Quelle est la durée du « Parrain » (1972) de Francis Ford Coppola, en minutes ?","v":175,"u":"min","a":"Marlon Brando y a remporté un Oscar qu'il a refusé d'aller chercher.","c":"Cinéma & séries"}],"Musique":[{"id":"sn5f504v","t":"En quelle année la rumba congolaise a-t-elle rejoint la liste du patrimoine immatériel de l'UNESCO ?","v":2021,"u":"","annee":true,"a":"Le dossier a été porté conjointement par les deux Congo, de part et d'autre du fleuve.","c":"Musique"},{"id":"ummt6z52","t":"En quelle année l'Opéra Garnier de Paris a-t-il été inauguré ?","v":1875,"u":"","annee":true,"a":"Charles Garnier avait remporté le concours en 1861 à 35 ans, sans être très connu jusque-là.","c":"Musique"},{"id":"oaxic3jf","t":"En quelle année Michael Jackson a-t-il dévoilé son moonwalk à la télévision, lors de l'émission « Motown 25 » ?","v":1983,"u":"","annee":true,"a":"Il a exécuté ce pas glissé à reculons en chantant « Billie Jean », lors d'un spectacle célébrant les 25 ans du label Motown.","c":"Musique"},{"id":"mlnj0fpz","t":"En quelle année l'Académie française a-t-elle décerné son Grand prix de poésie à Georges Brassens ?","v":1967,"u":"","annee":true,"a":"Brassens a mis en musique des poèmes de Victor Hugo, d'Aragon ou de Verlaine.","c":"Musique"},{"id":"win5y4sg","t":"En quelle année la platine Technics SL-1200, chère aux DJ, a-t-elle été lancée ?","v":1972,"u":"","annee":true,"a":"Pensée d'abord pour la hi-fi de salon, la SL-1200 a conquis les DJ grâce à son entraînement direct, robuste et précis.","c":"Musique"},{"id":"g5w56qht","t":"En quelle année la maison de pianos Steinway & Sons a-t-elle été fondée à New York ?","v":1853,"u":"","annee":true,"a":"Son fondateur, Heinrich Steinweg, avait émigré d'Allemagne en 1850 ; la famille a ensuite anglicisé son nom en Steinway.","c":"Musique"},{"id":"aup8wapt","t":"En quelle année la rumba cubaine a-t-elle été inscrite sur la liste du patrimoine culturel immatériel de l'UNESCO ?","v":2016,"u":"","annee":true,"a":"Elle est née dans les quartiers pauvres de La Havane et de Matanzas, parmi les descendants d'esclaves africains et les dockers.","c":"Musique"},{"id":"t2adx17n","t":"Combien de boutons de basses compte un accordéon chromatique complet, au système Stradella ?","v":120,"u":"boutons","a":"Le système porte le nom de la ville italienne de Stradella, qui a été un grand centre de fabrication d'accordéons.","c":"Musique"},{"id":"gih17r15","t":"Quel nombre, celui de la Bête, donne son sujet à la chanson « The Number of the Beast » d'Iron Maiden ?","v":666,"u":"","a":"La chanson a donné son nom à l'album de 1982, le premier du groupe avec le chanteur Bruce Dickinson.","c":"Musique"},{"id":"5o3dsc3g","t":"À quel âge le guitariste Jimi Hendrix est-il mort ?","v":27,"u":"ans","a":"Il a joué l'hymne américain, déformé à la guitare, devant le public de Woodstock en 1969.","c":"Musique"},{"id":"2ul5w0l2","t":"Quelle taille mesurait Édith Piaf, en centimètres ?","v":147,"u":"cm","a":"Sur scène, elle portait presque toujours une robe noire, qui la faisait paraître encore plus menue.","c":"Musique"},{"id":"yt01c89j","t":"Combien de quatuors à cordes Beethoven a-t-il composés ?","v":16,"u":"quatuors","a":"Ses derniers quatuors, écrits alors qu'il était sourd, ont dérouté ses contemporains avant d'être tenus pour des sommets.","c":"Musique"},{"id":"lslo4wop","t":"Combien de symphonies numérotées Mozart a-t-il laissées ?","v":41,"u":"symphonies","a":"La dernière a reçu après sa mort le surnom de « Jupiter », qui ne vient pas de Mozart lui-même.","c":"Musique"},{"id":"ocae78fp","t":"Quelle sonate pour piano de Beethoven porte le surnom « Clair de lune » ?","v":14,"u":"","a":"Le surnom n'est pas de Beethoven : le critique Ludwig Rellstab l'a donné après sa mort, en pensant au lac des Quatre-Cantons.","c":"Musique"}],"Arts & lettres":[{"id":"bipia8ew","t":"En quelle année Rimbaud publie-t-il Une saison en enfer ?","v":1873,"u":"","annee":true,"a":"Rimbaud n'a pas encore vingt ans et renonce à la poésie peu après.","c":"Arts & lettres"},{"id":"f1tspdp8","t":"En quelle année est publié pour la première fois le Journal d'Anne Frank, aux Pays-Bas ?","v":1947,"u":"","annee":true,"a":"Otto Frank, seul survivant de la famille, a fait publier le texte de sa fille.","c":"Arts & lettres"},{"id":"us919wmc","t":"En quelle année les Folies Bergère ouvrent-elles leurs portes à Paris ?","v":1869,"u":"","annee":true,"a":"Elles s'ouvrirent sous le nom de Folies-Trévise avant de prendre celui de la rue voisine.","c":"Arts & lettres"},{"id":"gt0daqwy","t":"En quelle année Alvin Ailey a-t-il fondé sa compagnie à New York ?","v":1958,"u":"","annee":true,"a":"Sa troupe est née à New York avec un petit groupe de danseurs afro-américains.","c":"Arts & lettres"},{"id":"vw9mum8t","t":"En quelle année Gaston Gallimard fonde-t-il, avec André Gide et Jean Schlumberger, les éditions de la Nouvelle Revue française ?","v":1911,"u":"","annee":true,"a":"La maison a pris le nom de Librairie Gallimard en 1919, l'année où elle a obtenu le Goncourt avec Proust.","c":"Arts & lettres"},{"id":"punnt8ba","t":"En quelle année Jean Vilar lance-t-il ce qui deviendra le Festival d'Avignon ?","v":1947,"u":"","annee":true,"a":"La première édition s'appelait « Semaine d'art en Avignon » et se jouait dans la cour d'honneur du palais des Papes.","c":"Arts & lettres"},{"id":"qhwbsaos","t":"En quelle année Albert Camus reçoit-il le prix Nobel de littérature ?","v":1957,"u":"","annee":true,"a":"Camus a dédié son discours de réception à Louis Germain, son instituteur à Alger.","c":"Arts & lettres"},{"id":"sqthp9z6","t":"Depuis combien de jours le pêcheur Santiago n'a-t-il rien pris au début du Vieil Homme et la Mer ?","v":84,"u":"jours","a":"Ce court roman a beaucoup compté dans le prix Nobel de littérature remis à Hemingway en 1954.","c":"Arts & lettres"},{"id":"stztwa9s","t":"Quelle est la hauteur, en centimètres, du tableau La Joconde de Léonard de Vinci ?","v":77,"u":"cm","a":"Peint sur un panneau de peuplier, le portrait est étonnamment petit au regard de sa célébrité.","c":"Arts & lettres"},{"id":"7709mozh","t":"Combien de chapitres numérotés compte le roman Moby Dick, sans compter l'épilogue ?","v":135,"u":"chapitres","a":"Le roman s'ouvre sur la phrase célèbre « Call me Ishmael », qui désigne le narrateur.","c":"Arts & lettres"},{"id":"g2mdn0gm","t":"Quelle est la longueur, en mètres, de la galerie des Glaces du château de Versailles ?","v":73,"u":"m","a":"Elle compte dix-sept arcades de miroirs, qui font face à dix-sept fenêtres ouvertes sur le jardin.","c":"Arts & lettres"},{"id":"j7snq06j","t":"Combien de syllabes compte un alexandrin ?","v":12,"u":"syllabes","a":"Son nom viendrait du Roman d'Alexandre, poème médiéval écrit dans ce vers.","c":"Arts & lettres"},{"id":"guas6s89","t":"Quelle est la hauteur, en mètres, de la statue de la Liberté, du sol du socle à la flamme de la torche ?","v":93,"u":"m","a":"Gustave Eiffel a conçu la structure métallique interne qui soutient la statue.","c":"Arts & lettres"},{"id":"69jfmmu5","t":"En combien de livres La République de Platon est-elle divisée ?","v":10,"u":"livres","a":"Le dialogue s'achève sur le mythe d'Er, un soldat revenu de l'au-delà qui raconte le sort des âmes.","c":"Arts & lettres"}],"Sport":[{"id":"r1o8q9c7","t":"En quelle année l'équipe de France masculine de handball devient-elle championne olympique pour la première fois ?","v":2008,"u":"","annee":true,"a":"Ce premier titre olympique a été remporté à Pékin, en finale face à l'Islande.","c":"Sport"},{"id":"fypubswr","t":"En quelle année le tournoi de Wimbledon remplace-t-il les balles blanches par des balles jaunes ?","v":1986,"u":"","annee":true,"a":"La balle jaune, adoptée pour être plus visible à la télévision, s'était déjà répandue ailleurs bien avant.","c":"Sport"},{"id":"qi3jx9xc","t":"En quelle année le maillot vert du classement par points est-il créé sur le Tour de France ?","v":1953,"u":"","annee":true,"a":"Lancé pour le cinquantenaire du Tour, il est vert en hommage à son parrain, le magasin La Belle Jardinière.","c":"Sport"},{"id":"3jdnfg9w","t":"En quelle année le Paris Saint-Germain est-il fondé ?","v":1970,"u":"","annee":true,"a":"Le club naît de la fusion du Paris FC et du Stade saint-germanois, club de Saint-Germain-en-Laye.","c":"Sport"},{"id":"jt7p7bnb","t":"En quelle année le Tour de France arrive-t-il pour la première fois au sommet de l'Alpe d'Huez ?","v":1952,"u":"","annee":true,"a":"Fausto Coppi s'impose lors de cette première arrivée, puis il remporte le Tour cette même année.","c":"Sport"},{"id":"atpb46cn","t":"En quelle année la Formule 1 introduit-elle le DRS, un aileron arrière mobile destiné à faciliter les dépassements ?","v":2011,"u":"","annee":true,"a":"Le pilote ne peut l'ouvrir que dans des zones définies et s'il se trouve à moins d'une seconde de la voiture qui le précède.","c":"Sport"},{"id":"sqhtsaks","t":"En quelle année naît la ligue qui deviendra la NBA, alors appelée BAA ?","v":1946,"u":"","annee":true,"a":"La BAA a pris le nom de NBA en 1949, en fusionnant avec une ligue rivale, la NBL.","c":"Sport"},{"id":"ltubslg6","t":"Combien de voitures prennent traditionnellement le départ des 500 Miles d'Indianapolis ?","v":33,"u":"voitures","a":"Les voitures s'élancent en onze rangées de trois, après un départ lancé derrière une voiture de tête.","c":"Sport"},{"id":"v5aa0z5o","t":"En cas de prolongation au football, combien de temps dure chacune des deux périodes supplémentaires ?","v":15,"u":"minutes","a":"Au tournant des années 2000, un « but en or » pouvait y mettre fin sur-le-champ : la première équipe à marquer l'emportait. La règle a été abandonnée en 2004.","c":"Sport"},{"id":"khh5t2ry","t":"Quelle est l'altitude du col du Tourmalet, en mètres ?","v":2115,"u":"m","a":"Le Tour de France l'a franchi pour la première fois en 1910.","c":"Sport"},{"id":"3j63xnoj","t":"Combien de minutes dure un quart-temps dans un match de basket FIBA ?","v":10,"u":"minutes","a":"Les rencontres de la WNBA, la ligue féminine nord-américaine, se jouent aussi en quarts de dix minutes.","c":"Sport"},{"id":"wsrl6ng3","t":"Aux Jeux de Berlin en 1936, le handball fait ses débuts olympiques : combien de joueurs chaque équipe aligne-t-elle ?","v":11,"u":"joueurs","a":"Ce handball se jouait en plein air, sur un terrain de football ; il a ensuite disparu au profit du handball en salle.","c":"Sport"},{"id":"4x6nk2ao","t":"Combien de grands tours, Tour de France, Tour d'Italie et Tour d'Espagne réunis, Eddy Merckx a-t-il remportés ?","v":11,"u":"grands tours","a":"Il a gagné cinq Tours de France, cinq Tours d'Italie et un seul Tour d'Espagne, en 1973.","c":"Sport"},{"id":"r4if924t","t":"Combien de pieds mesure la longueur d'une patinoire de la NHL ?","v":200,"u":"pieds","a":"Les patinoires internationales sont un peu plus larges que celles de la NHL, ce qui change le style de jeu.","c":"Sport"}],"Cuisine":[{"id":"8vzjbtq6","t":"En quelle année la pâte à tartiner Nutella, de la firme italienne Ferrero, est-elle lancée ?","v":1964,"u":"","annee":true,"a":"Elle descend d'une pâte de noisettes et de cacao créée à Alba dans les années 1940, quand le cacao manquait.","c":"Cuisine"},{"id":"d15qi27x","t":"En quelle année l'Auberge du Pont de Collonges, de Paul Bocuse, a-t-elle décroché ses trois étoiles Michelin ?","v":1965,"u":"","annee":true,"a":"Cette maison de Collonges-au-Mont-d'Or est restée triplement étoilée pendant plus de cinquante ans.","c":"Cuisine"},{"id":"uw7oo9ri","t":"En quelle année le classement britannique des 50 meilleurs restaurants du monde est-il publié pour la première fois ?","v":2002,"u":"","annee":true,"a":"Ce classement est établi par les votes de plusieurs centaines de chefs, critiques et gastronomes voyageurs.","c":"Cuisine"},{"id":"ewl1pd78","t":"En quelle année le chimiste Andreas Marggraf a-t-il découvert du sucre dans la betterave ?","v":1747,"u":"","annee":true,"a":"L'industrie du sucre de betterave n'a vraiment décollé qu'au début du XIXe siècle, quand le blocus privait l'Europe du sucre de canne.","c":"Cuisine"},{"id":"rudk0sky","t":"En quelle année l'ingénieur américain Percy Spencer dépose-t-il le brevet du four à micro-ondes ?","v":1945,"u":"","annee":true,"a":"Spencer aurait eu l'idée en voyant fondre une barre chocolatée dans sa poche, près d'un radar.","c":"Cuisine"},{"id":"1fdwdlzw","t":"En quelle année ouvre Maxim's, restaurant parisien de la rue Royale ?","v":1893,"u":"","annee":true,"a":"Son décor Art nouveau a fait sa légende, et Pierre Cardin en est devenu propriétaire en 1981.","c":"Cuisine"},{"id":"p3of5o1v","t":"En quelle année Auguste Fauchon ouvre-t-il son épicerie fine place de la Madeleine, à Paris ?","v":1886,"u":"","annee":true,"a":"Venu de Normandie, Auguste Fauchon vendait d'abord fruits et légumes avant d'en faire un temple de l'épicerie de luxe.","c":"Cuisine"},{"id":"cc8x4qxd","t":"À partir de combien de grammes un œuf est-il classé « gros » (calibre L) en Europe ?","v":63,"u":"g","a":"Un œuf pèse plus de 73 grammes ? Il passe dans la catégorie « très gros », le calibre XL.","c":"Cuisine"},{"id":"m0zij2hq","t":"Combien de jours le roquefort doit-il être affiné au minimum avant d'être vendu ?","v":90,"u":"jours","a":"Il s'affine dans des caves naturelles aérées par des fissures de la roche, appelées fleurines.","c":"Cuisine"},{"id":"w8cu4kkv","t":"Selon la règle européenne, quel pourcentage minimal de cacao doit contenir un chocolat noir ?","v":35,"u":"%","a":"La même directive de 2000 autorise jusqu'à 5 % de graisses végétales autres que le beurre de cacao, à condition de le signaler.","c":"Cuisine"},{"id":"ifdyhywm","t":"À combien de degrés Celsius correspond le thermostat 6 d'un four de cuisine français ?","v":180,"u":"°C","a":"Sur ces fours, le thermostat monte de 30 °C par cran : le 1 correspond à 30 °C et le 8 à 240 °C.","c":"Cuisine"},{"id":"tuh812bb","t":"Combien de jours après la ponte la date de durabilité d'un œuf frais est-elle fixée dans l'Union européenne ?","v":28,"u":"jours","a":"Sur la coquille, le premier chiffre du code imprimé indique le mode d'élevage, de 0 pour le bio à 3 pour les poules en cage.","c":"Cuisine"},{"id":"zv332gt9","t":"Combien de millilitres contient une canette standard de Coca-Cola en France ?","v":330,"u":"ml","a":"La recette du Coca-Cola est restée secrète depuis le XIXe siècle et la marque n'a jamais publié sa formule.","c":"Cuisine"},{"id":"hjwvlict","t":"À quelle température, en degrés Celsius, chauffe-t-on le lait pendant 15 secondes lors de sa pasteurisation rapide ?","v":72,"u":"°C","a":"Le procédé porte le nom de Louis Pasteur, qui l'avait d'abord mis au point pour conserver le vin.","c":"Cuisine"}],"Jeux & pop culture":[{"id":"9hcoa5nv","t":"En quelle année Wham-O a-t-elle rebaptisé son disque volant « Frisbee » ?","v":1957,"u":"","annee":true,"a":"Wham-O est aussi à l'origine du Hula Hoop, autre folie de jouet des années 1950.","c":"Jeux & pop culture"},{"id":"5fwy8yjv","t":"En quelle année Atari a-t-il lancé la console Jaguar ?","v":1993,"u":"","annee":true,"a":"Atari la présentait comme une console 64 bits, un argument très discuté.","c":"Jeux & pop culture"},{"id":"ebi3zwzq","t":"En quelle année Canal+ a-t-elle commencé à émettre en France ?","v":1984,"u":"","annee":true,"a":"Chaîne payante cryptée, elle exigeait un décodeur et misait sur le cinéma et le sport.","c":"Jeux & pop culture"},{"id":"891qntqh","t":"En quelle année le Vogue américain a-t-il comparé la petite robe noire de Chanel à la Ford T, la voiture de tout le monde ?","v":1926,"u":"","annee":true,"a":"Le magazine prédisait que cette robe simple deviendrait une sorte d'uniforme pour toutes les femmes de goût.","c":"Jeux & pop culture"},{"id":"udkrs4xg","t":"En quelle année Microsoft a-t-il racheté le service de messagerie Hotmail ?","v":1997,"u":"","annee":true,"a":"Hotmail, lancé en 1996, a séduit des millions d'utilisateurs en moins de deux ans.","c":"Jeux & pop culture"},{"id":"n4nnacsa","t":"En quelle année la société Ohio Art a-t-elle lancé l'Écran magique, ou Etch A Sketch ?","v":1960,"u":"","annee":true,"a":"Son inventeur est le Français André Cassagnes, qui l'a d'abord appelé L'Écran magique.","c":"Jeux & pop culture"},{"id":"o12sd4fv","t":"En quelle année Hasbro a-t-il lancé Mr. Patate, le jouet dont on pique les yeux et le nez ?","v":1952,"u":"","annee":true,"a":"Mr. Patate a été le premier jouet à bénéficier d'une publicité télévisée. À ses débuts, on piquait ses pièces dans une vraie pomme de terre.","c":"Jeux & pop culture"},{"id":"vzog7ock","t":"Combien de pixels de large mesure l'écran de la Game Boy d'origine ?","v":160,"u":"pixels","a":"Son écran n'affichait que quatre nuances d'un gris tirant sur le vert.","c":"Jeux & pop culture"},{"id":"50pllb68","t":"Sur combien de cases se joue le jeu de dames anglaises ?","v":64,"u":"cases","a":"Aux dames anglaises, chaque joueur commence avec douze pions, et la dame ne se déplace que d'une case.","c":"Jeux & pop culture"},{"id":"294pyttw","t":"Combien d'hôtels contient la boîte du Monopoly classique ?","v":12,"u":"hôtels","a":"Ce nombre limité fait partie du jeu : quand la banque n'en a plus, personne ne peut en construire.","c":"Jeux & pop culture"},{"id":"kf4hyu5o","t":"Combien de pièces compte un jeu de dominos classique, du double blanc au double six ?","v":28,"u":"pièces","a":"Chaque combinaison de deux valeurs, de zéro à six, n'apparaît qu'une seule fois dans le jeu.","c":"Jeux & pop culture"},{"id":"xth8s654","t":"Combien de cartes compte un jeu classique, jokers non compris ?","v":52,"u":"cartes","a":"Chacune des quatre couleurs, cœur, carreau, trèfle et pique, compte treize cartes.","c":"Jeux & pop culture"},{"id":"yb4v8h85","t":"Combien de flèches, ou points, compte le plateau de backgammon ?","v":24,"u":"flèches","a":"Chaque joueur démarre avec quinze pions.","c":"Jeux & pop culture"},{"id":"nywwpgdr","t":"Combien de cases compte le plateau du Monopoly, case Départ comprise ?","v":40,"u":"cases","a":"Le plateau compte vingt-deux rues, quatre gares et deux compagnies, plus les cases Chance, Caisse de communauté, impôts et les coins.","c":"Jeux & pop culture"}],"Autour de la fête":[{"id":"wmwoembh","t":"En quelle année la Grande-Bretagne adopte-t-elle le calendrier grégorien, en retranchant onze jours ?","v":1752,"u":"","annee":true,"a":"Le mercredi 2 septembre 1752 fut directement suivi du jeudi 14 septembre ; la même loi avait fixé le début de l'année au 1er janvier.","c":"Autour de la fête"},{"id":"4q7oqzf0","t":"En quelle année a été inauguré le Sambódromo de Rio de Janeiro, l'allée où défilent les écoles de samba ?","v":1984,"u":"","annee":true,"a":"L'allée a été dessinée par Oscar Niemeyer, l'architecte de Brasília. Avant sa construction, les écoles défilaient dans les rues de la ville.","c":"Autour de la fête"},{"id":"fje4lcjs","t":"En quelle année est sorti « L'Étrange Noël de monsieur Jack », film d'animation image par image produit par Tim Burton ?","v":1993,"u":"","annee":true,"a":"Le film n'est pas réalisé par Tim Burton, qui l'a imaginé et produit, mais par Henry Selick.","c":"Autour de la fête"},{"id":"ezz3l00p","t":"En quelle année a défilé à New York la première parade de la Saint-Patrick, organisée par des soldats irlandais de l'armée britannique ?","v":1762,"u":"","annee":true,"a":"La parade new-yorkaise est plus ancienne que les États-Unis eux-mêmes, et elle est longtemps restée plus grande que celles d'Irlande.","c":"Autour de la fête"},{"id":"r95f6y7f","t":"En quelle année Mariah Carey a-t-elle sorti « All I Want for Christmas Is You » ?","v":1994,"u":"","annee":true,"a":"La chanson figure sur l'album « Merry Christmas » et revient dans les classements chaque mois de décembre.","c":"Autour de la fête"},{"id":"vbvyvpo8","t":"En quelle année a été organisée à Paris la première Fête des voisins ?","v":1999,"u":"","annee":true,"a":"Elle est née dans le 17e arrondissement de Paris, à l'initiative d'Atanase Périfan, puis s'est étendue à de nombreux pays.","c":"Autour de la fête"},{"id":"6o7wuyww","t":"En quelle année Elizabeth II a-t-elle fêté son jubilé d'argent, pour ses vingt-cinq ans de règne ?","v":1977,"u":"","annee":true,"a":"Pour l'occasion, la reine a parcouru le Royaume-Uni et le Commonwealth, et des fêtes de rue ont été organisées partout dans le pays.","c":"Autour de la fête"},{"id":"idh6sl2t","t":"À quelle heure, le 6 juillet, est tiré le chupinazo, la fusée qui ouvre les fêtes de San Fermín à Pampelune ?","v":12,"u":"h","a":"La fusée part du balcon de l'hôtel de ville, devant une place noire de monde où chacun noue alors son foulard rouge.","c":"Autour de la fête"},{"id":"fnj6c0x4","t":"Combien d'animaux compte le cycle du zodiaque chinois ?","v":12,"u":"animaux","a":"Chaque année porte le nom d'un animal : le cycle revient donc tous les douze ans.","c":"Autour de la fête"},{"id":"c3kp9ztf","t":"Quelle gemme, produite par une huître, symbolise les noces des trente ans de mariage ?","v":30,"u":"ans","a":"La perle se forme quand l'huître enrobe un corps étranger de couches de nacre, année après année.","c":"Autour de la fête"},{"id":"aepbxryo","t":"Quel anniversaire d'une jeune fille la quinceañera célèbre-t-elle en Amérique latine ?","v":15,"u":"ans","a":"La fête commence souvent par une messe ; la jeune fille y porte une grande robe de bal et ouvre la danse, souvent avec son père.","c":"Autour de la fête"},{"id":"blsp3sc6","t":"Combien de mètres mesure la grande roue du London Eye, d'où part le feu d'artifice londonien du Nouvel An ?","v":135,"u":"m","a":"Inaugurée pour l'an 2000, la roue devait rester cinq ans ; elle est devenue un emblème de Londres.","c":"Autour de la fête"},{"id":"m35lvq2j","t":"Dans le film « La Belle au bois dormant » de Disney, avant le coucher du soleil de quel anniversaire Aurore doit-elle se piquer ?","v":16,"u":"ans","a":"Pour la protéger, les trois bonnes fées l'élèvent dans une chaumière de la forêt sous le nom d'Églantine.","c":"Autour de la fête"},{"id":"248wv1bl","t":"Combien de mois un enfant a-t-il vécus le jour de ses 2 ans ?","v":24,"u":"mois","a":"Pour les tout-petits, on compte souvent l'âge en mois jusqu'à deux ans, car leur développement change très vite.","c":"Autour de la fête"}]}};
window.TABLEAUX = [{"q":"Q1167907","t":"Le Déjeuner des canotiers","p":"Auguste Renoir","a":1880,"an":"La scène se déroule sur la terrasse d'un restaurant de Chatou, au bord de la Seine."},{"q":"Q1231009","t":"Le Sacre de Napoléon","p":"Jacques-Louis David","a":1807,"an":"David est le « premier peintre » de l'Empereur ; il a représenté Napoléon couronnant Joséphine, et non lui-même."},{"q":"Q12418","t":"La Joconde","p":"Léonard de Vinci","a":1503,"an":"Le voleur, le vitrier italien Vincenzo Peruggia, avait travaillé au Louvre ; il fut arrêté à Florence en voulant vendre le tableau."},{"q":"Q1245354","t":"Un bar aux Folies Bergère","p":"Édouard Manet","a":1882,"an":"Le reflet de la serveuse dans le miroir ne correspond pas à sa position de face, ce qui a longtemps intrigué les spectateurs."},{"q":"Q1368055","t":"Des glaneuses","p":"Jean-François Millet","a":1857,"an":"Le tableau montre trois paysannes courbées pour ramasser les épis laissés après la moisson."},{"q":"Q1452762","t":"Rue de Paris, temps de pluie","p":"Gustave Caillebotte","a":1877,"an":"Fortuné, Caillebotte a acheté des toiles de ses amis ; sa collection est entrée dans les musées de l'État après sa mort, en 1894."},{"q":"Q157541","t":"Les Tournesols","p":"Vincent van Gogh","a":1888,"an":"Il les a peints pour décorer la chambre de son ami Gauguin, venu le rejoindre dans la Maison jaune."},{"q":"Q164517","t":"La Danse","p":"Henri Matisse","a":1910,"an":"La toile n'utilise que trois couleurs : le rouge des corps, le bleu du ciel et le vert de la colline. Elle fut commandée par un collectionneur russe."},{"q":"Q167605","t":"La Laitière","p":"Johannes Vermeer","a":1660,"an":null},{"q":"Q17277950","t":"Les Joueurs de cartes","p":"Paul Cézanne","a":1893,"an":"Les modèles étaient des paysans des environs d'Aix-en-Provence ; une version a battu en 2011 un record de vente privée."},{"q":"Q185372","t":"La Jeune Fille à la perle","p":"Johannes Vermeer","a":1665,"an":"Son modèle reste inconnu, et la perle pourrait n'être qu'une imitation en verre ou en étain."},{"q":"Q208758","t":"Les Ménines","p":"Diego Vélasquez","a":1656,"an":"Picasso en a donné cinquante-huit variations en 1957."},{"q":"Q212616","t":"Le Radeau de la Méduse","p":"Théodore Géricault","a":1819,"an":"Pour peindre son tableau, Géricault a interrogé des survivants, dont Savigny et Corréard."},{"q":"Q219831","t":"La Ronde de nuit","p":"Rembrandt","a":1642,"an":"Le titre est trompeur : la scène se déroule en plein jour, mais le vernis noirci par les siècles lui donnait l'allure d'une nuit."},{"q":"Q220859","t":"Les Époux Arnolfini","p":"Jan van Eyck","a":1434,"an":"Au mur, il a tracé « Jan van Eyck fut ici, 1434 », comme un témoin de la scène."},{"q":"Q2339059","t":"Pluie, Vapeur et Vitesse","p":"William Turner","a":1844,"an":"Le tableau représente un train sur le pont de Maidenhead, sur la Tamise, dans la brume."},{"q":"Q2571560","t":"L'Angélus","p":"Jean-François Millet","a":1858,"an":"Salvador Dalí était si obsédé par cette toile qu'il lui a consacré un essai, Le Mythe tragique de l'Angélus de Millet."},{"q":"Q257580","t":"Le Dernier Voyage du Téméraire","p":"William Turner","a":1839,"an":"Le Téméraire avait combattu à Trafalgar en 1805 avant d'être remorqué pour être démoli. La toile figure aujourd'hui à la National Gallery de Londres."},{"q":"Q29530","t":"La Liberté guidant le peuple","p":"Eugène Delacroix","a":1830,"an":"La toile, achetée par l'État en 1831, fut jugée trop subversive pour être exposée pendant plusieurs années."},{"q":"Q311243","t":"Le Voyageur contemplant une mer de nuages","p":"Caspar David Friedrich","a":1818,"an":"Le voyageur est vu de dos, procédé cher à Friedrich pour inviter le spectateur à se placer devant le paysage."},{"q":"Q354396","t":"Portrait d'Adele Bloch-Bauer I","p":"Gustav Klimt","a":1907,"an":"Saisi par les nazis, le tableau fut rendu en 2006 à Maria Altmann, nièce du modèle, après une longue bataille judiciaire."},{"q":"Q45585","t":"La Nuit étoilée","p":"Vincent van Gogh","a":1889,"an":"Le paysage est celui que l'artiste voyait de la fenêtre de sa chambre à l'asile, mais il a ajouté le village de mémoire."},{"q":"Q464782","t":"American Gothic","p":"Grant Wood","a":1930,"an":"Ses modèles étaient sa sœur et son dentiste ; la maison existe à Eldon, dans l'Iowa."},{"q":"Q471379","t":"Le Cri","p":"Edvard Munch","a":1893,"an":"Munch a décliné son Cri en plusieurs versions : deux peintures, deux pastels et des lithographies."},{"q":"Q476458","t":"Le Serment des Horaces","p":"Jacques-Louis David","a":1784,"an":"Le tableau a été peint à Rome, avant d'être envoyé à Paris pour le Salon."},{"q":"Q500985","t":"Chasseurs dans la neige","p":"Pieter Brueghel l'Ancien","a":1565,"an":"Le tableau appartient à une série consacrée aux saisons ou aux mois de l'année."},{"q":"Q523974","t":"Vue de Delft","p":"Johannes Vermeer","a":1661,"an":"Marcel Proust la jugeait le plus beau tableau du monde et l'évoque dans « La Prisonnière »."},{"q":"Q683274","t":"Bal du moulin de la Galette","p":"Auguste Renoir","a":1876,"an":"Le moulin de la Galette était un lieu de danse populaire de Montmartre."},{"q":"Q698487","t":"Le Baiser","p":"Gustav Klimt","a":1907,"an":"Klimt a fondé la Sécession viennoise en 1897 et s'est inspiré des mosaïques byzantines de Ravenne."},{"q":"Q699091","t":"La Tour de Babel","p":"Pieter Brueghel l'Ancien","a":1563,"an":"La tour y ressemble au Colisée de Rome, que le peintre avait vu lors de son voyage en Italie."}];
